window.BUNPO={"groups":[{"id":"n5base","name":"기본 문장 (명사·형용사)","lv":5},{"id":"n5verb","name":"동사 정중형·보통형","lv":5},{"id":"n5place","name":"있다·없다·위치","lv":5},{"id":"n5part","name":"기본 조사","lv":5},{"id":"n5ask","name":"권유·부탁·희망","lv":5},{"id":"n5etc","name":"자주 쓰는 표현","lv":5},{"id":"conj","name":"접속사 — 문장과 문장 잇기","lv":4},{"id":"adv","name":"부사","lv":4},{"id":"part","name":"조사","lv":4},{"id":"form","name":"동사 활용 형식 (가능·의지·명령·수동·사역)","lv":4},{"id":"time","name":"시간·순서","lv":4},{"id":"aspect","name":"시작·계속·끝","lv":4},{"id":"cond","name":"가정·조건","lv":4},{"id":"reason","name":"이유·목적","lv":4},{"id":"guess","name":"추측·전해 들음","lv":4},{"id":"will","name":"의지·계획·결정","lv":4},{"id":"rule","name":"허가·금지·의무·명령","lv":4},{"id":"give","name":"주고받기","lv":4},{"id":"te","name":"～て 보조 표현","lv":4},{"id":"change","name":"변화·만들기","lv":4},{"id":"comp","name":"비교","lv":4},{"id":"noun","name":"명사화·인용·질문·기타","lv":4},{"id":"short","name":"회화 축약형","lv":4},{"id":"demo","name":"지시어 (こそあど)","lv":4},{"id":"keigo","name":"경어","lv":4},{"id":"sup","name":"보충 (시험에 나오는 그 밖의 N4)","lv":4}],"items":[{"id":"b001","g":"n5base","lv":5,"p":"～は～です","m":"~은/는 ~입니다","c":"명사 + は + 명사 + です","d":"'A는 B입니다'를 말하는 가장 기본 문장이에요. 조사 は는 '하'가 아니라 '와(わ)'로 읽어요. 반말(보통체)에서는 です 대신 だ를 써요.","ex":[["田中さんは先生です。","たなかさんは せんせいです。","다나카 씨는 선생님입니다."],["今日は日曜日です。","きょうは にちようびです。","오늘은 일요일입니다."]],"cmp":[["～が","は는 이미 아는 화제(~은/는), が는 새로 알려 주는 주어(~이/가). 의문사가 주어면 だれが처럼 が"]],"qz":["はじめまして。私（　　）キムです。よろしくお願いします。","は",["を","に","で"],"はじめまして。わたしは キムです。よろしく おねがいします。","처음 뵙겠습니다. 저는 김입니다. 잘 부탁합니다.","'저는'처럼 이야기의 주제를 말할 때 は예요. を는 목적어, に는 때·장소, で는 장소·수단이라 '~은/는' 뜻이 안 돼요."]},{"id":"b002","g":"n5base","lv":5,"p":"～じゃありません（～ではありません）","m":"~이/가 아닙니다","c":"명사 + じゃありません / ではありません","d":"です의 부정이에요. ではありません은 조금 딱딱한 말(글·공식 자리), じゃありません은 회화에서 쓰는 말이고 뜻은 같아요. では의 は도 '와'로 읽어요. 회화에서는 じゃないです도 많이 써요.","ex":[["私は学生じゃありません。","わたしは がくせいじゃ ありません。","저는 학생이 아닙니다."],["ここは駅ではありません。","ここは えきでは ありません。","여기는 역이 아닙니다."]],"qz":["「田中さんは先生ですか。」「いいえ、先生（　　）。学生です。」","じゃありません",["です","でした","じゃありませんでした"],"「たなかさんは せんせいですか。」「いいえ、せんせいじゃありません。がくせいです。」","\"다나카 씨는 선생님입니까?\" \"아니요, 선생님이 아닙니다. 학생입니다.\"","いいえ라고 했으니 '아닙니다' じゃありません. です는 いいえ와 반대이고, でした·じゃありませんでした는 과거라 지금 묻는 말과 안 맞아요."]},{"id":"b003","g":"n5base","lv":5,"p":"～でした／～じゃありませんでした","m":"~이었습니다 / ~이/가 아니었습니다","c":"명사·な형용사 + でした / じゃありませんでした","d":"です의 과거는 でした, じゃありません의 과거는 끝에 でした를 붙인 じゃありませんでした예요. い형용사에는 でした를 쓰지 않아요 (高いでした ✕ → 高かったです).","ex":[["昨日はいい天気でした。","きのうは いい てんきでした。","어제는 날씨가 좋았습니다."],["先週は休みじゃありませんでした。","せんしゅうは やすみじゃ ありませんでした。","지난주는 휴일이 아니었습니다."]],"qz":["昨日は雨（　　）。でも、今日はいい天気です。","でした",["です","じゃありません","ました"],"きのうは あめでした。でも、きょうは いい てんきです。","어제는 비가 왔습니다. 하지만 오늘은 좋은 날씨입니다.","昨日(어제) 일이라 명사의 과거 でした. です·じゃありません은 지금 일이고, ました는 동사에만 붙어서 雨 뒤에 못 와요."]},{"id":"b004","g":"n5base","lv":5,"p":"～か（질문）","m":"~까? (질문)","c":"です·ます 문장 끝 + か","d":"です·ます로 끝나는 문장 끝에 か만 붙이면 질문이 돼요. 일본어는 질문에도 물음표 대신 마침표(。)를 쓰는 것이 기본이에요. 대답은 はい(네)·いいえ(아니요)로 시작해요.","ex":[["田中さんは学生ですか。","たなかさんは がくせいですか。","다나카 씨는 학생입니까?"],["明日、学校へ行きますか。","あした、がっこうへ いきますか。","내일 학교에 갑니까?"]],"qz":["「すみません、あの人はだれです（　　）。」「山田さんです。」","か",["ね","よ","を"],"「すみません、あの ひとは だれですか。」「やまださんです。」","\"실례합니다, 저 사람은 누구입니까?\" \"야마다 씨입니다.\"","だれ(누구)로 묻는 질문이라 끝에 か. ね·よ는 묻는 말이 아니라 맞장구·알려 줄 때 쓰고, を는 문장 끝에 못 와요."]},{"id":"b005","g":"n5base","lv":5,"p":"～の（소유·소속）","m":"~의 (소유·소속)","c":"명사 + の + 명사","d":"명사와 명사를 이을 때 써요. 한국어는 '우리 학교·일본 차'처럼 '의'를 자주 빼지만, 일본어는 보통 の를 넣어요 (私たちの学校·日本の車). 다만 日本語·日本人처럼 한 단어로 굳은 말에는 の가 없어요. 뒤 명사를 빼면 '~의 것'이 돼요: 私のです(제 것입니다).","ex":[["これは私のかばんです。","これは わたしの かばんです。","이것은 제 가방입니다."],["キムさんはさくら大学の学生です。","キムさんは さくらだいがくの がくせいです。","김 씨는 사쿠라 대학의 학생입니다."]],"qz":["これは山田さん（　　）本です。私の本じゃありません。","の",["は","を","で"],"これは やまださんの ほんです。わたしの ほんじゃありません。","이것은 야마다 씨의 책입니다. 제 책이 아닙니다.","'야마다 씨의 책'처럼 누구 것인지 말할 때 명사와 명사 사이에 の. は·を·で를 넣으면 '책'과 이어지지 않아요."]},{"id":"b006","g":"n5base","lv":5,"p":"い형용사 ～いです／～くないです","m":"~합니다 / ~하지 않습니다 (い형용사 현재)","c":"い형용사 ～い + です / ～い → ～くないです","d":"い형용사는 그대로 です를 붙이고, 부정은 끝의 い를 く로 바꿔 ないです를 붙여요 (寒い → 寒くないです). いい(좋다)만 예외로 よくないです예요 (いくないです ✕). ～くありません도 같은 뜻이에요.","ex":[["この本はおもしろいです。","この ほんは おもしろいです。","이 책은 재미있습니다."],["今日はあまり寒くないです。","きょうは あまり さむくないです。","오늘은 그다지 춥지 않습니다."]],"qz":["「今日は寒いですか。」「いいえ、あまり（　　）。」","寒くないです",["寒いです","寒かったです","寒いじゃありません"],"「きょうは さむいですか。」「いいえ、あまり さむくないです。」","\"오늘은 춥습니까?\" \"아니요, 별로 춥지 않습니다.\"","あまり 뒤에는 부정이 와요. い형용사 부정은 い→くない라서 寒くないです. 寒いじゃありません은 な형용사 꼴이라 틀려요."]},{"id":"b007","g":"n5base","lv":5,"p":"い형용사 ～かったです／～くなかったです","m":"~했습니다 / ~하지 않았습니다 (い형용사 과거)","c":"い형용사 ～い → ～かったです / ～い → ～くなかったです","d":"과거는 끝의 い를 かった로 바꿔요 (楽しい → 楽しかったです). 楽しいでした는 틀린 말이에요. いい는 よかったです·よくなかったです로 바뀌어요.","ex":[["旅行はとても楽しかったです。","りょこうは とても たのしかったです。","여행은 매우 즐거웠습니다."],["昨日のテストは難しくなかったです。","きのうの テストは むずかしくなかったです。","어제 시험은 어렵지 않았습니다."]],"qz":["昨日の運動会はとても（　　）。また来年も出たいです。","楽しかったです",["楽しいです","楽しいでした","楽しくなかったです"],"きのうの うんどうかいは とても たのしかったです。また らいねんも でたいです。","어제 운동회는 아주 즐거웠습니다. 내년에도 또 나가고 싶습니다.","어제 일이라 과거 楽しかったです. い형용사 과거는 楽しいでした가 아니라 い→かった예요. 楽しくなかった는 '또 나가고 싶다'와 안 맞아요."]},{"id":"b008","g":"n5base","lv":5,"p":"な형용사 ～です／～じゃありません／～でした","m":"~합니다 / ~하지 않습니다 / ~했습니다 (な형용사)","c":"な형용사(な를 뺀 꼴) + です·じゃありません·でした·じゃありませんでした","d":"な형용사는 명사와 똑같이 바뀌어요: 静かです·静かじゃありません·静かでした. きれい·きらい는 い로 끝나지만 な형용사라서 きれくない ✕, きれいじゃありません ○예요.","ex":[["昨日はひまでした。","きのうは ひまでした。","어제는 한가했습니다."],["この部屋はきれいじゃありません。","この へやは きれいじゃ ありません。","이 방은 깨끗하지 않습니다."]],"qz":["「この町は静かですか。」「いいえ、あまり（　　）。車が多いです。」","静かじゃありません",["静かです","静かくないです","静かでした"],"「この まちは しずかですか。」「いいえ、あまり しずかじゃありません。くるまが おおいです。」","\"이 동네는 조용합니까?\" \"아니요, 별로 조용하지 않습니다. 차가 많습니다.\"","あまり 뒤에는 부정, 静か는 な형용사라 静かじゃありません. 静かくない는 い형용사 꼴이라 틀리고, です·でした는 부정이 아니에요."]},{"id":"b009","g":"n5base","lv":5,"p":"형용사 + 명사 (高い山·静かな町)","m":"~한 (명사) — 명사 꾸미기","c":"い형용사 ～い + 명사 / な형용사 ～な + 명사","d":"い형용사는 모양 그대로 명사 앞에 놓고(高い山), な형용사는 な를 넣어요(静かな町). 한국어 '높은 산·조용한 마을'의 '-ㄴ'에 해당해요. 大きい·小さい는 大きな·小さな 꼴로도 꾸며요.","ex":[["富士山は高い山です。","ふじさんは たかい やまです。","후지산은 높은 산입니다."],["きれいな花を買いました。","きれいな はなを かいました。","예쁜 꽃을 샀습니다."]],"qz":["駅の近くに（　　）公園があります。","きれいな",["きれい","きれいい","きれいの"],"えきの ちかくに きれいな こうえんが あります。","역 근처에 예쁜 공원이 있습니다.","きれい는 い로 끝나도 な형용사라 명사 앞에서 きれいな. きれい·きれいの는 명사 앞에 못 오고, きれいい라는 말은 없어요."]},{"id":"b010","g":"n5base","lv":5,"p":"～くて／～で（형용사 잇기）","m":"~하고 · ~해서 (형용사 잇기)","c":"い형용사 ～い → ～くて / な형용사·명사 + で","d":"형용사 두 개를 이을 때 써요 (安くておいしい). '~해서'처럼 이유로도 써요 (高くて買えません). いい는 よくて예요. 보통 좋은 말끼리·나쁜 말끼리 잇고, 반대되는 말은 ～ですが(~지만)로 이어요.","ex":[["このかばんは軽くて便利です。","この かばんは かるくて べんりです。","이 가방은 가볍고 편리합니다."],["あの公園は静かできれいです。","あの こうえんは しずかで きれいです。","저 공원은 조용하고 깨끗합니다."]],"qz":["私の部屋は（　　）明るいです。","広くて",["広い","広いで","広くで"],"わたしの へやは ひろくて あかるいです。","제 방은 넓고 밝습니다.","い형용사 두 개를 이을 때는 い→くて로 広くて. 広い를 그대로 두거나 広いで·広くで처럼 で를 붙이면 틀려요(で는 な형용사·명사)."]},{"id":"b011","g":"n5verb","lv":5,"p":"～ます／～ません／～ました／～ませんでした","m":"~합니다 / ~하지 않습니다 / ~했습니다 / ~하지 않았습니다","c":"동사 ます형(ます 뺀 꼴) + ます·ません·ました·ませんでした","d":"동사를 정중하게 말하는 꼴이에요. ます는 습관(毎朝食べます)과 앞으로의 일(明日行きます)을 나타내서 行きます는 '갑니다'도 '가겠습니다'도 돼요. 지금 하고 있는 동작은 ～ています로 말해요. 과거 부정은 ませんでした 하나로 기억하세요.","ex":[["毎朝パンを食べます。","まいあさ パンを たべます。","매일 아침 빵을 먹습니다."],["昨日はテレビを見ませんでした。","きのうは テレビを みませんでした。","어제는 텔레비전을 보지 않았습니다."]],"qz":["昨日は何も（　　）。おなかがすきました。","食べませんでした",["食べます","食べません","食べました"],"きのうは なにも たべませんでした。おなかが すきました。","어제는 아무것도 먹지 않았습니다. 배가 고팠습니다.","何も 뒤에는 부정, 昨日라서 과거 부정 食べませんでした. 食べます·食べました는 부정이 아니고, 食べません은 지금·앞으로의 일이에요."]},{"id":"b012","g":"n5verb","lv":5,"p":"보통형 (사전형·ない형·た형)","m":"~한다 / ~하지 않는다 / ~했다 (보통체·반말)","c":"사전형(行く) · ない형(行かない) · た형(行った) · なかった(行かなかった)","d":"ます를 쓰지 않는 꼴로, 친구·가족과의 반말이나 일기·글에서 써요. ～と思う·～でしょう·～時처럼 다른 문형 앞에 붙는 꼴이기도 해서 꼭 익혀야 해요.","ex":[["今日は学校に行かない。","きょうは がっこうに いかない。","오늘은 학교에 안 가."],["昨日、友だちと公園で遊んだ。","きのう、ともだちと こうえんで あそんだ。","어제 친구랑 공원에서 놀았어."]],"qz":["昨日、友だちとプールで（　　）。とても楽しかった。","泳いだ",["泳ぐ","泳がない","泳いた"],"きのう、ともだちと プールで およいだ。とても たのしかった。","어제 친구랑 수영장에서 수영했다. 아주 즐거웠다.","昨日 일이라 た형. 泳ぐ의 た형은 ぐ→いだ로 泳いだ. 泳いた는 없는 꼴이고, 泳ぐ·泳がない는 지금·앞으로의 일이에요."]},{"id":"b013","g":"n5verb","lv":5,"p":"～ないでください","m":"~하지 마세요 · ~하지 말아 주세요","c":"동사 ない형 + でください","d":"～てください(~해 주세요)의 반대예요. ない형에 でください를 붙여요 (走らない → 走らないでください). 가까운 사이에는 ください를 빼고 ～ないで만 말해요.","ex":[["教室で走らないでください。","きょうしつで はしらないで ください。","교실에서 뛰지 마세요."],["明日、かさを忘れないでください。","あした、かさを わすれないで ください。","내일 우산을 잊지 마세요."]],"qz":["ここは図書館です。大きな声で（　　）。","話さないでください",["話してください","話さないください","話すないでください"],"ここは としょかんです。おおきな こえで はなさないで ください。","여기는 도서관입니다. 큰 소리로 말하지 마세요.","도서관이라 '말하지 마세요'. ない형 話さない + でください. 話してください는 반대 뜻이고, で가 빠지거나 話すない로 바꾼 꼴은 틀려요."]},{"id":"b014","g":"n5verb","lv":5,"p":"～たり～たりする","m":"~하기도 하고 ~하기도 하다","c":"동사 た형 + り, 동사 た형 + り + する","d":"여러 일 중 몇 개만 예로 들 때 써요. 끝에 꼭 する가 붙고, 정중하게 말할 때는 마지막 する만 します로 바꿔요 (読んだり見たりします).","ex":[["休みの日は本を読んだり、音楽を聞いたりします。","やすみの ひは ほんを よんだり、おんがくを きいたり します。","쉬는 날에는 책을 읽기도 하고 음악을 듣기도 합니다."],["公園で走ったり遊んだりしました。","こうえんで はしったり あそんだり しました。","공원에서 뛰기도 하고 놀기도 했습니다."]],"cmp":[["～て、～","て는 한 일을 순서대로 다 말하기, たり는 그중 몇 개만 예로 들기"]],"qz":["日曜日は本を（　　）、ゲームをしたりします。","読んだり",["読みたり","読むたり","読んたり"],"にちようびは ほんを よんだり、ゲームを したり します。","일요일에는 책을 읽기도 하고 게임을 하기도 합니다.","たり는 た형에 붙어요. 読む의 た형은 読んだ라서 読んだり. 読みたり·読むたり·読んたり는 た형이 아니라 틀린 꼴이에요."]},{"id":"b015","g":"n5verb","lv":5,"p":"～ましょう","m":"~합시다","c":"동사 ます형(ます 뺀 꼴) + ましょう","d":"상대에게 같이 하자고 이끄는 말이에요. 이미 하기로 한 일을 '자, 합시다'라고 시작할 때도 써요. 반말로는 의지형(食べよう·帰ろう)을 써요.","ex":[["いっしょに昼ごはんを食べましょう。","いっしょに ひるごはんを たべましょう。","같이 점심을 먹읍시다."],["もう遅いですから、帰りましょう。","もう おそいですから、かえりましょう。","이제 늦었으니 돌아갑시다."]],"cmp":[["～ませんか","ませんか는 상대 뜻을 묻는 부드러운 권유, ましょう는 함께 하자고 이끄는 말"]],"qz":["「もう五時ですね。いっしょに帰りませんか。」「ええ、（　　）。」","帰りましょう",["帰りませんか","帰りません","帰りました"],"「もう ごじですね。いっしょに かえりませんか。」「ええ、かえりましょう。」","\"벌써 5시네요. 같이 돌아가지 않을래요?\" \"네, 돌아갑시다.\"","권유에 '좋아요'라고 응할 때 ええ、～ましょう. 帰りませんか는 같은 말로 되묻는 꼴, 帰りません은 ええ와 반대, 帰りました는 과거예요."]},{"id":"b016","g":"n5verb","lv":5,"p":"～ませんか","m":"~하지 않겠습니까? · ~할래요? (권유)","c":"동사 ます형(ます 뺀 꼴) + ませんか","d":"부정 꼴이지만 '안 해요?'라는 질문이 아니라 '같이 ~하지 않을래요?'라는 정중한 권유예요. 상대가 고를 여지를 줘서 ましょう보다 부드러워요. 좋다고 할 때는 いいですね로 대답해요.","ex":[["日曜日、いっしょに映画を見ませんか。","にちようび、いっしょに えいがを みませんか。","일요일에 같이 영화 보지 않을래요?"],["ちょっと休みませんか。","ちょっと やすみませんか。","잠깐 쉬지 않을래요?"]],"qz":["「今度の日曜日、いっしょに海へ（　　）。」「いいですね。行きましょう。」","行きませんか",["行きましたか","行きません","行かないでください"],"「こんどの にちようび、いっしょに うみへ いきませんか。」「いいですね。いきましょう。」","\"이번 일요일에 같이 바다에 가지 않을래요?\" \"좋아요. 갑시다.\"","'같이 가지 않을래요?' 하고 권하는 말이라 行きませんか. 行きましたか는 지난 일, 行きません·行かないでください는 '좋아요'와 안 맞아요."]},{"id":"b017","g":"n5verb","lv":5,"p":"～ましょうか","m":"(제가) ~할까요? · (같이) ~할까요?","c":"동사 ます형(ます 뺀 꼴) + ましょうか","d":"두 가지로 써요. ① 내가 해 주겠다는 제안: 持ちましょうか(들어 드릴까요?). ② 같이 할 일을 의논: どこで会いましょうか(어디서 만날까요?). 제안을 받으면 お願いします(부탁해요)로 대답해요.","ex":[["寒いですね。窓を閉めましょうか。","さむいですね。まどを しめましょうか。","춥네요. 제가 창문을 닫을까요?"],["明日、どこで会いましょうか。","あした、どこで あいましょうか。","내일 어디서 만날까요?"]],"qz":["「その荷物、重いですね。一つ（　　）。」「ありがとうございます。」","持ちましょうか",["持ちませんか","持ってください","持ちました"],"「その にもつ、おもいですね。ひとつ もちましょうか。」「ありがとうございます。」","\"그 짐 무겁네요. 하나 들어 드릴까요?\" \"고맙습니다.\"","'제가 ~할까요?' 하고 도와주겠다고 할 때 ～ましょうか. 持ちませんか는 상대에게 권하는 말, 持ってください는 부탁이라 '고맙다'와 안 맞아요."]},{"id":"b018","g":"n5verb","lv":5,"p":"～に行く（목적）","m":"~하러 가다","c":"동사 ます형(ます 뺀 꼴) + に行く·来る·帰る / 동작 명사(買い物·散歩) + に行く","d":"가는 목적을 나타내요. 食べに行く(먹으러 가다)처럼 ます를 뺀 꼴에 に를 붙여요. 買い物·散歩처럼 동작을 뜻하는 명사는 바로 に를 붙여요. 가는 곳은 へ·に로 앞에 와요 (図書館へ本を借りに行く).","ex":[["図書館へ本を借りに行きます。","としょかんへ ほんを かりに いきます。","도서관에 책을 빌리러 갑니다."],["友だちと買い物に行きました。","ともだちと かいものに いきました。","친구와 쇼핑하러 갔습니다."]],"qz":["明日、デパートへ新しいくつを（　　）行きます。","買いに",["買うに","買いで","買いへ"],"あした、デパートへ あたらしい くつを かいに いきます。","내일 백화점에 새 신발을 사러 갑니다.","'~하러 가다'는 ます형(ます를 뺀 꼴) + に行く라서 買いに. 사전형 買う에는 붙지 않고, で·へ로는 목적을 나타낼 수 없어요."]},{"id":"b019","g":"n5place","lv":5,"p":"～があります／～がいます","m":"~이/가 있습니다","c":"물건·식물·일 + があります / 사람·동물 + がいます","d":"한국어는 모두 '있다'지만 일본어는 둘로 나눠요. 스스로 움직이는 것(사람·동물)은 いる, 움직이지 않는 것(물건·식물)은 ある예요. 시험·약속·시간 같은 일도 ある를 써요. 부정은 ありません·いません.","ex":[["明日、テストがあります。","あした、テストが あります。","내일 시험이 있습니다."],["庭に猫がいます。","にわに ねこが います。","마당에 고양이가 있습니다."]],"qz":["見てください。公園に小さい犬が（　　）。","います",["あります","ありません","いるます"],"みて ください。こうえんに ちいさい いぬが います。","보세요. 공원에 작은 개가 있습니다.","개처럼 움직이는 동물·사람이 있을 때는 います. あります·ありません은 물건에 쓰고, いるます는 없는 꼴이에요."]},{"id":"b020","g":"n5place","lv":5,"p":"～に～があります（위치）","m":"(장소)에 ~이/가 있습니다","c":"장소 + に + 명사 + があります·がいます","d":"'어디에 무엇이 있다'를 말하는 순서예요. 있는 곳에는 に를 써요 (で ✕). 자리는 上(위)·下(아래)·中(안)·前(앞)·後ろ(뒤)·となり(옆) 앞에 の를 넣어 말해요: 机の上に.","ex":[["かばんの中にかぎがあります。","かばんの なかに かぎが あります。","가방 안에 열쇠가 있습니다."],["駅の前に田中さんがいます。","えきの まえに たなかさんが います。","역 앞에 다나카 씨가 있습니다."]],"qz":["テーブルの上（　　）りんごが三つあります。","に",["で","を","へ"],"テーブルの うえに りんごが みっつ あります。","테이블 위에 사과가 세 개 있습니다.","무엇이 '있는' 곳은 に. で는 동작을 하는 곳(公園で遊ぶ)이라 あります와 쓰지 않고, を·へ도 있는 곳을 나타내지 못해요."]},{"id":"b021","g":"n5place","lv":5,"p":"～は～にあります","m":"~은/는 (장소)에 있습니다","c":"명사 + は + 장소 + に + あります·います","d":"이미 이야기에 나온 것이 '어디에' 있는지 말할 때 써요. 묻는 말은 ～はどこにありますか예요. 회화에서는 줄여서 ～はどこですか·～は二階です처럼 です로도 말해요.","ex":[["トイレは二階にあります。","トイレは にかいに あります。","화장실은 2층에 있습니다."],["田中さんは今、教室にいます。","たなかさんは いま、きょうしつに います。","다나카 씨는 지금 교실에 있습니다."]],"cmp":[["～に～があります","に～があります는 '그곳에 무엇이 있나', ～は～にあります는 '그것이 어디에 있나'"]],"qz":["「お母さんはどこですか。」「母は今、台所（　　）。」","にいます",["にあります","がいます","でいます"],"「おかあさんは どこですか。」「ははは いま、だいどころに います。」","\"어머니는 어디 계세요?\" \"엄마는 지금 부엌에 있어요.\"","사람이 어디에 있는지는 장소 + に + います. あります는 물건에 쓰고, がいます는 장소 뒤에 못 오며, で는 있는 곳이 아니라 동작하는 곳이에요."]},{"id":"b022","g":"n5place","lv":5,"p":"これ・それ・あれ・どれ","m":"이것·그것·저것·어느 것","c":"명사처럼 씀 (これは·それを·どれが)","d":"こ는 나에게 가까운 것, そ는 상대에게 가까운 것, あ는 둘 다에게 먼 것, ど는 질문이에요. 명사 앞에서는 この·その·あの·どの로 바꿔요 (この本 ○, これ本 ✕). どれ는 셋 이상에서 고를 때이고, 둘 중에서는 どちら예요.","ex":[["それは何ですか。","それは なんですか。","그것은 무엇입니까?"],["田中さんのかさはどれですか。","たなかさんの かさは どれですか。","다나카 씨의 우산은 어느 것입니까?"]],"qz":["「（　　）は何ですか。」「これですか。日本のおかしです。」","それ",["これ","あれ","どれ"],"「それは なんですか。」「これですか。にほんの おかしです。」","\"그건 뭐예요?\" \"이거요? 일본 과자예요.\"","대답한 사람이 これ(내 가까이)라고 했으니 묻는 사람에게는 상대 가까이의 それ. これ면 대답이 それ, あれ면 あれ가 되고, どれ는 何와 함께 못 써요."]},{"id":"b023","g":"n5place","lv":5,"p":"ここ・そこ・あそこ・どこ","m":"여기·거기·저기·어디","c":"장소를 가리키는 말, 명사처럼 씀 (ここは·ここで·どこに)","d":"こ·そ·あ·ど의 규칙은 これ·それ와 같아요. 상대 가까이는 そこ, 둘 다에게 먼 곳은 あそこ예요 (あこ ✕). 더 정중하게 말할 때는 こちら·そちら·あちら·どちら를 써요.","ex":[["すみません、駅はどこですか。","すみません、えきは どこですか。","실례합니다, 역은 어디입니까?"],["あそこに銀行があります。","あそこに ぎんこうが あります。","저기에 은행이 있습니다."]],"qz":["「田中さんの家は（　　）ですか。」「駅の近くです。」","どこ",["だれ","いつ","なに"],"「たなかさんの いえは どこですか。」「えきの ちかくです。」","\"다나카 씨 집은 어디입니까?\" \"역 근처입니다.\"","'역 근처'라고 장소로 대답했으니 장소를 묻는 どこ. だれ는 사람, いつ는 때, なに는 물건을 물어요."]},{"id":"b024","g":"n5part","lv":5,"p":"～へ（방향）","m":"~로 · ~에 (가는 곳·방향)","c":"장소 + へ + 行く·来る·帰る","d":"가는 곳·방향을 나타내요. 조사 へ는 '헤'가 아니라 '에(え)'로 읽어요. 가는 곳에는 に도 쓸 수 있고 뜻은 거의 같아요. へ는 '그쪽으로'라는 방향 느낌이에요.","ex":[["夏休みに国へ帰ります。","なつやすみに くにへ かえります。","여름방학에 고국에 돌아갑니다."],["キムさんは去年日本へ来ました。","キムさんは きょねん にほんへ きました。","김 씨는 작년에 일본에 왔습니다."]],"qz":["夏休みに、おばあさんの家（　　）行きます。","へ",["で","を","が"],"なつやすみに、おばあさんの いえへ いきます。","여름 방학에 할머니 댁에 갑니다.","가는 곳(방향)은 へ. で는 동작을 하는 곳, を는 목적어, が는 주어라서 行きます의 목적지를 나타내지 못해요."]},{"id":"b025","g":"n5part","lv":5,"p":"～で（장소·수단）","m":"~에서 (동작하는 곳) · ~로 (수단·도구)","c":"장소 + で + 동작 / 교통·도구·말 + で","d":"① 무엇을 '하는' 곳: 図書館で勉強する. ② 수단·도구: バスで行く·はしで食べる·日本語で話す. 있는 곳(ある·いる)은 で가 아니라 に예요 (部屋にいる / 部屋で寝る).","ex":[["公園でサッカーをしました。","こうえんで サッカーを しました。","공원에서 축구를 했습니다."],["毎日、電車で会社へ行きます。","まいにち、でんしゃで かいしゃへ いきます。","매일 전철로 회사에 갑니다."]],"cmp":[["～に（장소）","に는 있는 곳·도착하는 곳, で는 동작을 하는 곳"]],"qz":["毎週土曜日、図書館（　　）本を読みます。","で",["に","を","へ"],"まいしゅう どようび、としょかんで ほんを よみます。","매주 토요일, 도서관에서 책을 읽습니다.","책을 '읽는' 동작을 하는 곳이라 で. に는 있는 곳·도착하는 곳(図書館にいる), へ는 가는 방향이라 読みます와 안 맞아요."]},{"id":"b026","g":"n5part","lv":5,"p":"～や～など","m":"~랑 ~ 등 (몇 개만 예로 들기)","c":"명사 + や + 명사 (+ など)","d":"여러 개 가운데 몇 개만 예로 들 때 써요. など(등)는 빼도 돼요. 시험에는 と와의 차이가 자주 나와요.","ex":[["かばんの中に本やノートなどがあります。","かばんの なかに ほんや ノートなどが あります。","가방 안에 책이랑 공책 등이 있습니다."],["朝、パンや果物を食べます。","あさ、パンや くだものを たべます。","아침에 빵이랑 과일을 먹습니다."]],"cmp":[["～と","と는 말한 것이 전부(りんごとみかん = 딱 둘), や는 그 밖에도 더 있음"]],"qz":["れいぞうこの中にたまご（　　）牛乳などがあります。","や",["を","で","へ"],"れいぞうこの なかに たまごや ぎゅうにゅうなどが あります。","냉장고 안에 달걀이랑 우유 등이 있습니다.","뒤에 など(등)가 있으니 몇 개만 예로 드는 や. を·で·へ는 명사 두 개를 나란히 잇지 못해요."]},{"id":"b027","g":"n5part","lv":5,"p":"～から～まで","m":"~부터 ~까지 · ~에서 ~까지","c":"시간·장소 + から + 시간·장소 + まで","d":"시작점은 から, 끝점은 まで예요. 시간에도 장소에도 쓰고, 장소의 から는 한국어 '~에서'로 옮겨요. 하나만 따로 써도 돼요 (九時から·駅まで).","ex":[["授業は九時から三時までです。","じゅぎょうは くじから さんじまでです。","수업은 9시부터 3시까지입니다."],["家から駅まで歩きます。","いえから えきまで あるきます。","집에서 역까지 걸어갑니다."]],"cmp":[["～までに","まで는 그때까지 계속, までに는 그때까지 한 번 끝내기(기한)"]],"qz":["月曜日（　　）金曜日まで学校があります。","から",["まで","に","を"],"げつようびから きんようびまで がっこうが あります。","월요일부터 금요일까지 학교가 있습니다.","뒤에 まで(까지)가 있으니 시작점 から. まで를 두 번 쓰면 '부터'가 없어지고, に·を로는 '~부터'를 나타낼 수 없어요."]},{"id":"b028","g":"n5part","lv":5,"p":"～と一緒に","m":"~와 함께 · ~랑 같이","c":"사람 + と一緒に + 동사","d":"누구와 함께 하는지 말해요. と만 써도 '~와'라는 뜻이지만(友だちと行く), 一緒に를 붙이면 '함께'가 더 분명해져요. 一緒に만 따로 쓰면 '같이'예요 (一緒に帰りましょう).","ex":[["友だちと一緒に映画を見ました。","ともだちと いっしょに えいがを みました。","친구와 함께 영화를 봤습니다."],["母と一緒に料理を作ります。","ははと いっしょに りょうりを つくります。","어머니와 함께 요리를 만듭니다."]],"qz":["日曜日、父（　　）一緒に山に登りました。","と",["を","に","へ"],"にちようび、ちちと いっしょに やまに のぼりました。","일요일에 아빠랑 같이 산에 올랐습니다.","'~와 함께'는 사람 + と一緒に. を·に·へ는 一緒に 앞에서 '누구와'를 나타내지 못해요."]},{"id":"b029","g":"n5ask","lv":5,"p":"～をください／～をお願いします","m":"~을/를 주세요 / ~을/를 부탁합니다","c":"명사 (+ 수량) + をください / 명사 + をお願いします","d":"가게·식당에서 물건을 달라고 할 때 써요. 수량은 を 뒤에 놓아요 (りんごを三つください). お願いします는 더 부드럽고, 물건뿐 아니라 일(계산·안내)을 부탁할 때도 써요.","ex":[["このりんごを三つください。","この りんごを みっつ ください。","이 사과를 세 개 주세요."],["すみません、お水をお願いします。","すみません、おみずを おねがいします。","저기요, 물 좀 부탁합니다."]],"qz":["「いらっしゃいませ。」「オレンジジュース（　　）一つお願いします。」","を",["が","に","へ"],"「いらっしゃいませ。」「オレンジジュースを ひとつ おねがいします。」","\"어서 오세요.\" \"오렌지 주스 하나 부탁합니다.\"","달라고 하는 물건 뒤에는 を(을/를). ～をお願いします·～をください로 써요. が·に·へ는 부탁하는 물건을 나타내지 못해요."]},{"id":"b030","g":"n5ask","lv":5,"p":"～てください","m":"~해 주세요","c":"동사 て형 + ください","d":"상대에게 정중하게 부탁하거나 지시할 때 써요. 동사를 て형으로 바꿔 ください를 붙여요 (書く → 書いてください). 가까운 사이에는 ください를 빼고 ～て만 말해요 (ちょっと待って).","ex":[["もう一度言ってください。","もう いちど いって ください。","한 번 더 말해 주세요."],["ゆっくり話してください。","ゆっくり はなして ください。","천천히 말해 주세요."]],"qz":["字が小さいです。もう少し大きく（　　）。","書いてください",["書きてください","書くてください","書いたください"],"じが ちいさいです。もう すこし おおきく かいて ください。","글씨가 작습니다. 조금 더 크게 써 주세요.","てください는 て형에 붙어요. 書く의 て형은 く→いて로 書いて. 書きて·書くて는 없는 꼴이고, た형 書いた에는 ください가 못 붙어요."]},{"id":"b031","g":"n5ask","lv":5,"p":"～がほしい","m":"~을/를 갖고 싶다","c":"명사 + が + ほしい(です)","d":"내가 갖고 싶은 것을 말해요. 한국어는 '~을'이지만 일본어는 が를 써요. ほしい는 い형용사라서 ほしくないです·ほしかったです로 바뀌어요. 하고 싶은 '동작'은 ほしい가 아니라 ～たい예요.","ex":[["新しいくつがほしいです。","あたらしい くつが ほしいです。","새 신발을 갖고 싶습니다."],["今は何もほしくないです。","いまは なにも ほしくないです。","지금은 아무것도 갖고 싶지 않습니다."]],"cmp":[["～たい","ほしい는 물건(명사)을 갖고 싶음, たい는 동작(동사)을 하고 싶음 (行きたい)"]],"qz":["「誕生日に何がほしいですか。」「新しいゲーム（　　）ほしいです。」","が",["に","で","へ"],"「たんじょうびに なにが ほしいですか。」「あたらしい ゲームが ほしいです。」","\"생일에 무엇을 갖고 싶어요?\" \"새 게임을 갖고 싶어요.\"","갖고 싶은 물건은 ～がほしい로 が를 써요. 질문도 何がほしい예요. に·で·へ는 갖고 싶은 것을 나타내지 못해요."]},{"id":"b032","g":"n5ask","lv":5,"p":"～が好きです／～が上手です","m":"~을/를 좋아합니다 / ~을/를 잘합니다","c":"명사 + が + 好き·嫌い·上手·下手 + です","d":"한국어는 '~을'이지만 일본어는 が를 써요 (音楽を好きです ✕). 好き·上手는 な형용사라서 부정은 好きじゃありません이에요. 上手는 주로 남을 칭찬할 때 쓰고, 내가 잘하는 것은 得意(자신 있다)로 말하는 게 자연스러워요.","ex":[["私は犬が好きです。","わたしは いぬが すきです。","저는 개를 좋아합니다."],["田中さんは歌が上手ですね。","たなかさんは うたが じょうずですね。","다나카 씨는 노래를 잘하네요."]],"qz":["姉はピアノ（　　）とても上手です。","が",["を","に","で"],"あねは ピアノが とても じょうずです。","언니(누나)는 피아노를 아주 잘 칩니다.","上手·好き 앞의 대상은 が(한국어로는 '을/를'). ピアノを上手です처럼 を를 쓰면 틀리고, に·で도 맞지 않아요."]},{"id":"b033","g":"n5ask","lv":5,"p":"～のが好き／～のが上手","m":"~하는 것을 좋아한다 / ~하는 것을 잘한다","c":"동사 사전형 + のが + 好き·嫌い·上手·下手","d":"동사 뒤에 の를 붙이면 '~하는 것'이라는 명사처럼 돼요. 그 뒤는 명사 때와 같이 が好き·が上手를 써요. ～ことが好き도 같은 뜻이에요.","ex":[["私は絵をかくのが好きです。","わたしは えを かくのが すきです。","저는 그림 그리는 것을 좋아합니다."],["姉は料理を作るのが上手です。","あねは りょうりを つくるのが じょうずです。","언니는 요리를 잘합니다."]],"qz":["私は朝、公園を走る（　　）好きです。","のが",["のを","が","を"],"わたしは あさ、こうえんを はしるのが すきです。","저는 아침에 공원을 달리는 것을 좋아합니다.","동사를 好き와 이으려면 の를 붙여 명사처럼 만든 뒤 が: 走るのが好き. 走るが·走るを처럼 の가 없거나 のを를 쓰면 틀려요."]},{"id":"b034","g":"n5etc","lv":5,"p":"～の中で～が一番","m":"~ 중에서 ~이/가 가장","c":"범위(명사) + の中で + 명사 + が一番 + 형용사","d":"셋 이상 가운데 '가장'을 말할 때 써요. 물을 때는 ～の中で何/どれ/だれが一番～ですか예요. 둘 중에서 고를 때는 ～と～とどちらが를 써요.","ex":[["スポーツの中でサッカーが一番好きです。","スポーツの なかで サッカーが いちばん すきです。","스포츠 중에서 축구를 가장 좋아합니다."],["家族の中でだれが一番早く起きますか。","かぞくの なかで だれが いちばん はやく おきますか。","가족 중에서 누가 가장 일찍 일어납니까?"]],"qz":["私は動物（　　）パンダが一番好きです。","の中で",["の中に","より","のほうが"],"わたしは どうぶつの なかで パンダが いちばん すきです。","저는 동물 중에서 판다를 가장 좋아합니다.","一番(가장)의 범위는 ～の中で. の中に는 '~의 안에(있다)', より·のほうが는 둘을 비교하는 말이라 一番과 함께 못 써요."]},{"id":"b035","g":"n5etc","lv":5,"p":"～でしょう","m":"~겠지요 · ~일 것입니다 (추측) / ~지요? (확인)","c":"동사·い형용사 보통형 + でしょう / な형용사·명사 + でしょう (だ 없이)","d":"확실하지 않은 일을 추측할 때 써요. 일기 예보에 자주 나오고 たぶん(아마)과 잘 어울려요. 끝을 올려 말하면 '~지요?'라고 상대에게 확인하는 말이 돼요. 반말은 ～だろう예요.","ex":[["明日はたぶん雨でしょう。","あしたは たぶん あめでしょう。","내일은 아마 비가 오겠지요."],["この本、おもしろいでしょう？","この ほん、おもしろいでしょう？","이 책 재미있지요?"]],"qz":["雲が多いですね。明日の朝はたぶん寒い（　　）。","でしょう",["でした","だでしょう","ましょう"],"くもが おおいですね。あしたの あさは たぶん さむいでしょう。","구름이 많네요. 내일 아침은 아마 춥겠지요.","たぶん(아마)과 함께 앞일을 짐작하니 でしょう. 寒い에 だ를 넣은 だでしょう는 틀리고, でした는 과거, ましょう는 동사에만 붙어요."]},{"id":"b036","g":"n5etc","lv":5,"p":"～ね／～よ","m":"~네요·~지요 (공감·확인) / ~요 (알려 줌)","c":"문장 끝 + ね·よ","d":"ね는 상대도 아는 일에 공감하거나 확인할 때, よ는 상대가 모르는 일을 알려 줄 때 써요. 윗사람에게 よ를 너무 많이 쓰면 가르치는 느낌이 날 수 있어요. 둘을 합친 よね는 '~죠?'예요.","ex":[["今日は暑いですね。","きょうは あついですね。","오늘은 덥네요."],["あの店のパンはおいしいですよ。","あの みせの パンは おいしいですよ。","저 가게 빵은 맛있어요."]],"qz":["「この本、おもしろいですか。」「ええ、おもしろいです（　　）。ぜひ読んでみてください。」","よ",["ね","か","を"],"「この ほん、おもしろいですか。」「ええ、おもしろいですよ。ぜひ よんで みて ください。」","\"이 책 재미있어요?\" \"네, 재미있어요. 꼭 읽어 보세요.\"","아직 안 읽은 상대에게 알려 주며 권하니 よ. ね는 둘 다 아는 것에 맞장구칠 때라 어색하고, か는 질문, を는 문장 끝에 못 와요."]},{"id":"b037","g":"n5etc","lv":5,"p":"～ぐらい／～ごろ","m":"~쯤·~정도 (양·시간 길이) / ~쯤 (때·시각)","c":"수량·기간 + ぐらい(くらい) / 시각·날짜 + ごろ","d":"둘 다 '~쯤'이지만 ぐらい는 '얼마나'(양·길이), ごろ는 '언제'(시각)예요: 一時間ぐらい(한 시간쯤) / 一時ごろ(1시쯤). ぐらい는 くらい라고도 해요.","ex":[["家から学校まで二十分ぐらいかかります。","いえから がっこうまで にじゅっぷんぐらい かかります。","집에서 학교까지 20분쯤 걸립니다."],["昨日は七時ごろ家に帰りました。","きのうは しちじごろ いえに かえりました。","어제는 7시쯤 집에 돌아왔습니다."]],"qz":["家から駅まで、歩いて十五分（　　）かかります。","ぐらい",["ごろ","に","を"],"いえから えきまで、あるいて じゅうごふんぐらい かかります。","집에서 역까지 걸어서 15분쯤 걸립니다.","걸리는 시간의 '길이'는 ぐらい. ごろ는 '7시쯤'처럼 시각에 쓰고, に·を는 かかります 앞에서 시간의 양을 나타내지 못해요."]},{"id":"b038","g":"n5etc","lv":5,"p":"의문사 + か／의문사 + も","m":"무언가·누군가·어딘가 / 아무것도·아무도·아무 데도 (+ 부정)","c":"何か·だれか·どこか·いつか / 何も·だれも·どこへも + 부정","d":"의문사 + か는 '무언가·누군가'처럼 정해지지 않은 것, 의문사 + も + 부정은 '아무것도 ~않다'예요. 조사가 붙으면 どこへも·だれにも처럼 조사 뒤에 も가 와요 (どこもへ ✕).","ex":[["だれか来ましたか。","だれか きましたか。","누군가 왔습니까?"],["日曜日はどこへも行きませんでした。","にちようびは どこへも いきませんでした。","일요일에는 아무 데도 가지 않았습니다."]],"cmp":[["何を～か","何を飲みますか는 '무엇을' 묻는 질문, 何か飲みますか는 마실지 말지 묻는 예/아니요 질문"]],"qz":["「暑いですね。（　　）飲みますか。」「はい、お茶をお願いします。」","何か",["何を","何も","何が"],"「あついですね。なにか のみますか。」「はい、おちゃを おねがいします。」","\"덥네요. 뭔가 마실래요?\" \"네, 차 부탁합니다.\"","はい로 답했으니 '뭔가 마실래요?' 하는 예/아니요 질문, 何か. 何を는 '무엇을' 물어 はい로 답하지 않고, 何も는 부정과 짝, 何が는 飲む의 대상이 못 돼요."]},{"id":"b039","g":"n5etc","lv":5,"p":"～はどうですか","m":"~은/는 어떻습니까? (의견·상태 묻기 · 권하기)","c":"명사 + はどうですか (더 정중하게: ～はいかがですか)","d":"상대의 느낌·상태를 물을 때(学校はどうですか)와 무언가를 제안할 때(三時はどうですか) 써요. 손님·윗사람에게는 いかがですか가 더 정중해요. 지난 일은 どうでしたか로 물어요.","ex":[["新しい学校はどうですか。","あたらしい がっこうは どうですか。","새 학교는 어떻습니까?"],["明日の三時はどうですか。","あしたの さんじは どうですか。","내일 3시는 어떻습니까?"]],"qz":["「日本の食べ物（　　）。」「とてもおいしいです。」","はどうですか",["はどこですか","はだれですか","はいつですか"],"「にほんの たべものは どうですか。」「とても おいしいです。」","\"일본 음식은 어떻습니까?\" \"아주 맛있습니다.\"","'맛있다'는 느낌·상태를 답했으니 '어떻습니까?' はどうですか. どこ(어디)·だれ(누구)·いつ(언제)는 이 대답과 안 맞아요."]},{"id":"b040","g":"n5etc","lv":5,"p":"빈도 (～に～回·いつも·よく·時々)","m":"~에 ~번 / 늘·자주·가끔 (얼마나 자주)","c":"기간 + に + 횟수(一回·二回) / いつも·よく·時々 + 동사","d":"기간 뒤에 に를 붙이고 횟수를 말해요 (一週間に二回). 많은 순서는 いつも > よく > 時々 > あまり～ない > 全然～ない예요. あまり·全然 뒤에는 부정이 짝으로 와요.","ex":[["一日に三回、歯をみがきます。","いちにちに さんかい、はを みがきます。","하루에 세 번 이를 닦습니다."],["休みの日はよく公園を散歩します。","やすみの ひは よく こうえんを さんぽします。","쉬는 날에는 자주 공원을 산책합니다."]],"qz":["一週間（　　）二回、プールで泳ぎます。","に",["へ","を","が"],"いっしゅうかんに にかい、プールで およぎます。","일주일에 두 번 수영장에서 수영합니다.","'일주일에 두 번'처럼 기간 + に + 횟수로 빈도를 말해요. へ·を·が로는 '~에 몇 번'을 나타내지 못해요."]},{"id":"b041","g":"n5etc","lv":5,"p":"～にします（고르기）","m":"~로 하겠습니다 · ~로 할게요 (고르기·정하기)","c":"명사 + にします","d":"여러 개 가운데 하나를 골라 정할 때 써요. 가게에서 주문할 때 자주 써요 (コーヒーにします). 무엇으로 할지 물을 때는 何にしますか, 이미 정한 것은 ～にしました예요.","ex":[["飲み物は何にしますか。","のみものは なにに しますか。","음료는 무엇으로 하겠습니까?"],["じゃ、私はこの赤いシャツにします。","じゃ、わたしは この あかい シャツに します。","그럼 저는 이 빨간 셔츠로 할게요."]],"qz":["「ケーキはどれにしますか。」「じゃ、私はこのいちごのケーキ（　　）。」","にします",["をします","がします","でします"],"「ケーキは どれに しますか。」「じゃ、わたしは この いちごの ケーキに します。」","\"케이크는 어느 것으로 할래요?\" \"그럼 저는 이 딸기 케이크로 할게요.\"","여러 개 중에서 고를 때는 명사 + にします(~로 할게요). 질문도 どれにしますか예요. を·が·で로는 '고르다'는 뜻이 안 돼요."]},{"id":"b042","g":"conj","lv":4,"p":"しかし","m":"그러나 · 하지만","c":"문장 앞 (앞 문장을 받아서)","d":"앞 문장과 반대되는 내용을 이어요. 글이나 발표에서 쓰는 조금 딱딱한 말이고, 회화에서는 でも를 더 많이 써요.","ex":[["このりんごは小さいです。しかし、甘いです。","この りんごは ちいさいです。しかし、あまいです。","이 사과는 작습니다. 그러나 답니다."],["日本語はおもしろいです。しかし、漢字は難しいです。","にほんごは おもしろいです。しかし、かんじは むずかしいです。","일본어는 재미있습니다. 하지만 한자는 어렵습니다."]],"tag":"r5","cmp":[["でも","でも는 회화에서 편하게, しかし는 글·공식적인 말에서"]],"qz":["このレストランは有名です。（　　）、料理はあまりおいしくなかったです。","しかし",["だから","それとも","たとえば"],"この レストランは ゆうめいです。しかし、りょうりは あまり おいしくなかったです。","이 레스토랑은 유명합니다. 하지만 요리는 별로 맛있지 않았습니다.","'유명한데 맛없었다'처럼 앞과 반대되는 말이 오니 しかし. だから는 이유와 결과, それとも는 질문의 '아니면', たとえば는 예를 들 때예요."]},{"id":"b043","g":"conj","lv":4,"p":"そして","m":"그리고","c":"문장 앞 (앞 문장을 받아서)","d":"앞 문장에 내용을 더하거나, 그다음에 한 일을 이어 말할 때 써요. 한국어 '그리고'와 거의 같아요. 단어(명사)끼리는 보통 と로 이어요 (パンと牛乳).","ex":[["この部屋は広いです。そして、明るいです。","この へやは ひろいです。そして、あかるいです。","이 방은 넓습니다. 그리고 밝습니다."],["朝ごはんを食べました。そして、学校へ行きました。","あさごはんを たべました。そして、がっこうへ いきました。","아침밥을 먹었습니다. 그리고 학교에 갔습니다."]],"tag":"r5","qz":["田中さんは歌が上手です。（　　）、ダンスも上手です。","そして",["しかし","だから","それとも"],"たなかさんは うたが じょうずです。そして、ダンスも じょうずです。","다나카 씨는 노래를 잘합니다. 그리고 춤도 잘 춥니다.","좋은 점에 좋은 점을 이어 말하니 そして. しかし는 반대되는 말, だから는 이유와 결과, それとも는 질문의 '아니면'이라 안 맞아요."]},{"id":"b044","g":"conj","lv":4,"p":"それから","m":"그다음에 · 그러고 나서 / 그리고 (덧붙이기)","c":"문장 앞 (앞 문장을 받아서)","d":"앞의 일이 끝난 '다음에' 하는 일을 말해요. 주문·부탁에서 '그리고 또'라고 하나 더 보탤 때도 써요. 순서를 분명히 말할 때는 そして보다 それから가 잘 맞아요.","ex":[["宿題をしました。それから、テレビを見ました。","しゅくだいを しました。それから、テレビを みました。","숙제를 했습니다. 그다음에 텔레비전을 봤습니다."],["パンを二つください。それから、牛乳もください。","パンを ふたつ ください。それから、ぎゅうにゅうも ください。","빵을 두 개 주세요. 그리고 우유도 주세요."]],"tag":"r5","cmp":[["そして","そして는 그냥 이어 말하기, それから는 '그다음에'라는 순서가 더 분명"]],"qz":["学校から帰って、まず手を洗います。（　　）、おやつを食べます。","それから",["しかし","それとも","たとえば"],"がっこうから かえって、まず てを あらいます。それから、おやつを たべます。","학교에서 돌아와서 먼저 손을 씻습니다. 그러고 나서 간식을 먹습니다.","まず(먼저) 한 일 다음에 하는 일이니 '그다음에' それから. しかし는 반대, それとも는 질문의 '아니면', たとえば는 예를 들 때예요."]},{"id":"b045","g":"conj","lv":4,"p":"でも","m":"하지만 · 그래도","c":"문장 앞 (앞 문장을 받아서)","d":"앞 문장과 반대되는 내용을 이어요. 회화에서 가장 많이 쓰는 '하지만'이에요. 글이나 딱딱한 자리에서는 しかし를 써요.","ex":[["昨日は雨でした。でも、楽しかったです。","きのうは あめでした。でも、たのしかったです。","어제는 비가 왔습니다. 하지만 즐거웠습니다."],["この服はかわいいです。でも、ちょっと高いです。","この ふくは かわいいです。でも、ちょっと たかいです。","이 옷은 귀엽습니다. 하지만 좀 비쌉니다."]],"tag":"r5","cmp":[["～でも（~라도）","명사 뒤에 붙는 でも(お茶でも飲みませんか)는 '~라도'. 접속사 でも는 문장 맨 앞"]],"qz":["「いっしょにプールへ行きませんか。」「行きたいです。（　　）、今日は時間がありません。」","でも",["だから","それに","それとも"],"「いっしょに プールへ いきませんか。」「いきたいです。でも、きょうは じかんが ありません。」","\"같이 수영장에 가지 않을래요?\" \"가고 싶어요. 하지만 오늘은 시간이 없어요.\"","'가고 싶다'와 반대로 '시간이 없다'가 오니 でも. だから는 이유와 결과, それに는 같은 쪽 말을 더할 때, それとも는 질문의 '아니면'이에요."]},{"id":"b046","g":"conj","lv":4,"p":"それでは／では","m":"그러면 · 그럼","c":"문장 앞 (앞 말을 받아서 · 이야기를 시작하거나 끝낼 때)","d":"앞 이야기를 받아 '그렇다면'이라고 이을 때와, 수업·모임을 시작하거나 끝낼 때 써요 (では、始めましょう). では의 は는 '와'로 읽어요. 회화에서는 줄여서 じゃ·じゃあ라고 해요.","ex":[["では、授業を始めます。","では、じゅぎょうを はじめます。","그럼 수업을 시작하겠습니다."],["もう五時ですね。それでは、また明日。","もう ごじですね。それでは、また あした。","벌써 5시네요. 그럼 내일 또 봐요."]],"tag":"r5","qz":["九時になりました。（　　）、テストを始めます。","では",["しかし","それとも","なぜなら"],"くじに なりました。では、テストを はじめます。","9시가 되었습니다. 그럼 시험을 시작하겠습니다.","앞 상황을 받아 무언가를 시작할 때 では(그럼). しかし는 반대, それとも는 질문의 '아니면', なぜなら는 이유를 뒤에서 말할 때예요."]},{"id":"b047","g":"conj","lv":4,"p":"けれども","m":"그렇지만 · 하지만","c":"문장 앞 (앞 문장을 받아서)","d":"앞 문장과 반대되는 내용을 이어요. しかし보다 부드럽고 でも보다는 조금 정중한 느낌이에요. 줄여서 けれど·けど라고도 해요. 앞 문장 끝에 붙여 두 문장을 하나로 잇는 ～けれども(~지만)와 뜻이 같아요.","ex":[["この店は少し遠いです。けれども、とても安いです。","この みせは すこし とおいです。けれども、とても やすいです。","이 가게는 조금 멉니다. 그렇지만 매우 쌉니다."],["毎日練習しました。けれども、試合に負けました。","まいにち れんしゅうしました。けれども、しあいに まけました。","매일 연습했습니다. 그렇지만 시합에서 졌습니다."]],"qz":["妹はまだ小さいです。（　　）、ひらがなが全部読めます。","けれども",["だから","それに","たとえば"],"いもうとは まだ ちいさいです。けれども、ひらがなが ぜんぶ よめます。","여동생은 아직 어립니다. 그렇지만 히라가나를 전부 읽을 수 있습니다.","'어린데도 다 읽는다'처럼 예상과 반대라 けれども. だから는 이유와 결과, それに는 같은 쪽 말을 더할 때, たとえば는 예를 들 때예요."]},{"id":"b048","g":"conj","lv":4,"p":"すると","m":"그러자 · 그랬더니","c":"문장 앞 (앞 문장을 받아서)","d":"앞의 일을 하자 바로 뒤의 일이 일어났다는 뜻이에요. 뒤에는 보통 '일어난 일·알게 된 일'이 과거형으로 와요. 내 뜻으로 하는 일(～ましょう·～てください)은 뒤에 오지 않아요.","ex":[["ボタンを押しました。すると、ドアが開きました。","ボタンを おしました。すると、ドアが あきました。","버튼을 눌렀습니다. 그러자 문이 열렸습니다."],["窓を開けました。すると、冷たい風が入ってきました。","まどを あけました。すると、つめたい かぜが はいって きました。","창문을 열었습니다. 그러자 차가운 바람이 들어왔습니다."]],"cmp":[["それで","それで는 '그래서'(이유와 결과), すると는 '그러자'(하자마자 일어난 일)"]],"qz":["犬の名前を呼びました。（　　）、犬が走ってきました。","すると",["しかし","それとも","なぜなら"],"いぬの なまえを よびました。すると、いぬが はしって きました。","개 이름을 불렀습니다. 그러자 개가 달려왔습니다.","내가 한 일 바로 뒤에 일어난 일이라 '그러자' すると. しかし는 반대, それとも는 질문의 '아니면', なぜなら는 이유를 말할 때예요."]},{"id":"b049","g":"conj","lv":4,"p":"そこで","m":"그래서 (그 상황에서 이렇게 했다)","c":"문장 앞 (앞 문장을 받아서)","d":"앞의 상황·문제를 보고 '그래서 이렇게 했다'라고 대책이나 행동을 말할 때 써요. 뒤에는 보통 내가 일부러 한 일이 와요. 장소를 가리키는 そこ + で(거기에서)와는 다른 말이에요.","ex":[["道が分かりませんでした。そこで、駅の人に聞きました。","みちが わかりませんでした。そこで、えきの ひとに ききました。","길을 몰랐습니다. 그래서 역 직원에게 물었습니다."],["漢字が覚えられませんでした。そこで、カードを作りました。","かんじが おぼえられませんでした。そこで、カードを つくりました。","한자를 외울 수가 없었습니다. 그래서 카드를 만들었습니다."]],"cmp":[["それで","それで는 저절로 이어진 결과, そこで는 문제를 풀려고 일부러 한 행동"]],"qz":["宿題が難しくて分かりませんでした。（　　）、兄に聞きました。","そこで",["それとも","たとえば","なぜなら"],"しゅくだいが むずかしくて わかりませんでした。そこで、あにに ききました。","숙제가 어려워서 몰랐습니다. 그래서 형(오빠)에게 물어봤습니다.","문제를 풀려고 일부러 한 행동이 뒤에 오니 そこで. それとも는 질문의 '아니면', たとえば는 예를 들 때, なぜなら는 이유를 말할 때예요."]},{"id":"b050","g":"conj","lv":4,"p":"それで","m":"그래서 · 그래서요? (이야기 재촉)","c":"문장 앞 (앞 문장을 받아서)","d":"앞 일이 이유가 되어 뒤의 결과가 생겼다는 뜻이에요. 뒤에는 이미 일어난 일·상태가 오고, 명령·부탁·권유는 잘 오지 않아요. 회화에서 '그래서요?'라고 다음 이야기를 재촉할 때도 써요.","ex":[["昨日は熱がありました。それで、学校を休みました。","きのうは ねつが ありました。それで、がっこうを やすみました。","어제는 열이 있었습니다. 그래서 학교를 쉬었습니다."],["電車が止まりました。それで、学校に遅れました。","でんしゃが とまりました。それで、がっこうに おくれました。","전철이 멈췄습니다. 그래서 학교에 늦었습니다."]],"cmp":[["だから","だから는 뒤에 부탁·의지도 옴(だから、早く寝なさい), それで는 일어난 결과를 담담하게"]],"qz":["今朝、ねぼうしました。（　　）、学校におくれました。","それで",["そこで","しかし","それとも"],"けさ、ねぼうしました。それで、がっこうに おくれました。","오늘 아침 늦잠을 잤습니다. 그래서 학교에 늦었습니다.","늦잠의 결과로 저절로 늦은 것이라 それで. そこで는 일부러 한 행동에만 쓰고, しかし는 반대, それとも는 질문의 '아니면'이에요."]},{"id":"b051","g":"conj","lv":4,"p":"それとも","m":"아니면 (질문에서 둘 중 고르기)","c":"문장 앞 (두 질문 사이에)","d":"'A입니까? 아니면 B입니까?'처럼 둘 중 하나를 고르라고 물을 때 써요. 질문에만 쓰고, 보통 문장에서 'A 또는 B'라고 할 때는 または·か를 써요.","ex":[["コーヒーにしますか。それとも、紅茶にしますか。","コーヒーに しますか。それとも、こうちゃに しますか。","커피로 하겠습니까? 아니면 홍차로 하겠습니까?"],["バスで行きますか。それとも、歩いて行きますか。","バスで いきますか。それとも、あるいて いきますか。","버스로 갑니까? 아니면 걸어서 갑니까?"]],"cmp":[["または","または는 안내·설명의 '또는', それとも는 질문에서 '아니면'"]],"qz":["夏休みは海へ行きますか。（　　）、山へ行きますか。","それとも",["そして","しかし","だから"],"なつやすみは うみへ いきますか。それとも、やまへ いきますか。","여름 방학에는 바다에 갑니까? 아니면 산에 갑니까?","두 질문 중 하나를 고르게 하니 '아니면' それとも. そして는 이어 말하기, しかし는 반대, だから는 이유와 결과라 질문 사이에 못 와요."]},{"id":"b052","g":"conj","lv":4,"p":"それなら","m":"그렇다면 · 그러면","c":"문장 앞 (상대의 말을 받아서)","d":"상대가 한 말을 받아 '그런 사정이라면'이라고 조언·제안할 때 써요. 뒤에는 ～てください·～がいいですよ 같은 말이 잘 와요. 회화에서는 だったら도 같은 뜻으로 써요.","ex":[["「頭が痛いです。」「それなら、早く帰ってください。」","「あたまが いたいです。」「それなら、はやく かえって ください。」","\"머리가 아파요.\" \"그렇다면 일찍 돌아가세요.\""],["「日本の料理が好きです。」「それなら、この店がいいですよ。」","「にほんの りょうりが すきです。」「それなら、この みせが いいですよ。」","\"일본 요리를 좋아해요.\" \"그렇다면 이 가게가 좋아요.\""]],"cmp":[["それでは","それでは는 이야기를 시작·끝낼 때도 씀, それなら는 상대 말을 조건으로 받아 제안"]],"qz":["「明日は雨ですよ。」「（　　）、かさを持って行きます。」","それなら",["しかし","それとも","なぜなら"],"「あしたは あめですよ。」「それなら、かさを もって いきます。」","\"내일은 비가 와요.\" \"그렇다면 우산을 가지고 갈게요.\"","상대의 말을 받아 '그렇다면' 하고 내 생각을 말하니 それなら. しかし는 반대, それとも는 질문의 '아니면', なぜなら는 이유를 말할 때예요."]},{"id":"b053","g":"conj","lv":4,"p":"それに","m":"게다가 · 더구나","c":"문장 앞 (앞 문장을 받아서)","d":"앞 문장과 같은 방향의 내용을 하나 더 보탤 때 써요 (좋은 점 + 또 좋은 점). 이유를 늘어놓을 때 많이 쓰는 회화 말이에요.","ex":[["この店は安いです。それに、おいしいです。","この みせは やすいです。それに、おいしいです。","이 가게는 쌉니다. 게다가 맛있습니다."],["今日は雨です。それに、風も強いです。","きょうは あめです。それに、かぜも つよいです。","오늘은 비가 옵니다. 게다가 바람도 강합니다."]],"cmp":[["そして","そして는 그냥 이어 말하기, それに는 '게다가'라고 하나 더 얹어 강조"]],"qz":["この自転車は軽いです。（　　）、色もきれいです。","それに",["しかし","だから","それとも"],"この じてんしゃは かるいです。それに、いろも きれいです。","이 자전거는 가볍습니다. 게다가 색도 예쁩니다.","좋은 점에 좋은 점을 하나 더 얹으니 '게다가' それに. しかし는 반대, だから는 이유와 결과, それとも는 질문의 '아니면'이에요."]},{"id":"b054","g":"conj","lv":4,"p":"だから／ですから","m":"그러니까 · 그래서","c":"문장 앞 (앞 문장을 받아서) — だから는 보통체, ですから는 정중체","d":"앞 문장이 이유이고 뒤가 결과·판단이에요. 뒤에 부탁·명령·의지도 올 수 있어요. だから는 반말에, 윗사람에게는 ですから를 써요. 강하게 말하면 따지는 느낌이 날 수 있어요.","ex":[["明日はテストです。ですから、今日は早く寝ます。","あしたは テストです。ですから、きょうは はやく ねます。","내일은 시험입니다. 그러니까 오늘은 일찍 자겠습니다."],["もう遅い。だから、早く帰ろう。","もう おそい。だから、はやく かえろう。","이제 늦었어. 그러니까 빨리 돌아가자."]],"cmp":[["それで","それで는 일어난 결과를 담담하게, だから는 판단·주장·부탁까지"]],"qz":["外はとても寒いよ。（　　）、コートを着て行きなさい。","だから",["それで","しかし","それとも"],"そとは とても さむいよ。だから、コートを きて いきなさい。","밖은 아주 추워. 그러니까 코트를 입고 가렴.","이유 뒤에 '입고 가렴'처럼 시키는 말이 오니 だから. それで 뒤에는 명령·부탁이 올 수 없고, しかし는 반대, それとも는 질문의 '아니면'이에요."]},{"id":"b055","g":"conj","lv":4,"p":"だが","m":"그러나 · 하지만 (글말)","c":"문장 앞 (앞 문장을 받아서) — 보통체 글에서","d":"しかし와 같은 뜻으로, 주로 ～だ·～である로 끝나는 보통체 글(신문·소설·설명문)에서 써요. 딱딱한 말이라 です·ます 회화에는 쓰지 않고, 정중한 문장이면 しかし·でも를 써요.","ex":[["この町は小さい。だが、とても美しい。","この まちは ちいさい。だが、とても うつくしい。","이 마을은 작다. 그러나 매우 아름답다."],["兄は毎日練習した。だが、試合には勝てなかった。","あには まいにち れんしゅうした。だが、しあいには かてなかった。","형은 매일 연습했다. 그러나 시합에서는 이기지 못했다."]],"qz":["この本はとても長い。（　　）、一日で全部読んだ。","だが",["だから","それとも","たとえば"],"この ほんは とても ながい。だが、いちにちで ぜんぶ よんだ。","이 책은 아주 길다. 그러나 하루 만에 전부 읽었다.","'긴데도 하루 만에 읽었다'처럼 반대되는 말이 오니 だが. だから는 이유와 결과, それとも는 질문의 '아니면', たとえば는 예를 들 때예요."]},{"id":"b056","g":"conj","lv":4,"p":"たとえば","m":"예를 들면","c":"문장 앞 (앞 말의 예를 들 때)","d":"앞에서 말한 것의 구체적인 예를 들 때 써요. 한자로는 例えば예요. 뒤에 ～や·～など를 함께 써서 예가 더 있다는 느낌을 내는 일이 많아요.","ex":[["日本の食べ物が好きです。たとえば、すしやてんぷらです。","にほんの たべものが すきです。たとえば、すしや てんぷらです。","일본 음식을 좋아합니다. 예를 들면 초밥이나 튀김입니다."],["休みの日はいろいろなことをします。たとえば、買い物や散歩です。","やすみの ひは いろいろな ことを します。たとえば、かいものや さんぽです。","쉬는 날에는 여러 가지를 합니다. 예를 들면 쇼핑이나 산책입니다."]],"qz":["動物園にはいろいろな動物がいます。（　　）、ゾウやキリンなどです。","たとえば",["しかし","それとも","だから"],"どうぶつえんには いろいろな どうぶつが います。たとえば、ゾウや キリンなどです。","동물원에는 여러 가지 동물이 있습니다. 예를 들면 코끼리나 기린 등입니다.","'여러 가지 동물'의 예를 드니 たとえば. しかし는 반대, それとも는 질문의 '아니면', だから는 이유와 결과라 예를 들 수 없어요."]},{"id":"b057","g":"conj","lv":4,"p":"なぜなら","m":"왜냐하면","c":"문장 앞 (앞 문장의 이유를 뒤에서 말할 때) — 끝은 보통 ～からです","d":"결과를 먼저 말하고 그 이유를 뒤에 덧붙일 때 써요. 뒤 문장 끝은 보통 ～からです로 맺어요. 조금 딱딱한 말이라 글·발표에 많고, 회화에서는 ～から·～んです로 이유를 말하는 일이 많아요.","ex":[["私は毎朝走ります。なぜなら、体にいいからです。","わたしは まいあさ はしります。なぜなら、からだに いいからです。","저는 매일 아침 달립니다. 왜냐하면 몸에 좋기 때문입니다."],["今日は早く帰ります。なぜなら、母の誕生日だからです。","きょうは はやく かえります。なぜなら、ははの たんじょうびだからです。","오늘은 일찍 돌아가겠습니다. 왜냐하면 어머니 생신이기 때문입니다."]],"qz":["私は毎日牛乳を飲みます。（　　）、背が高くなりたいからです。","なぜなら",["だから","それで","しかし"],"わたしは まいにち ぎゅうにゅうを のみます。なぜなら、せが たかく なりたいからです。","저는 매일 우유를 마십니다. 왜냐하면 키가 크고 싶기 때문입니다.","뒤 문장이 ～からです로 이유를 말하니 なぜなら. だから·それで는 앞이 이유이고 뒤가 결과일 때 쓰고, しかし는 반대예요."]},{"id":"b058","g":"conj","lv":4,"p":"または","m":"또는 · 혹은","c":"명사 + または + 명사 / 문장 앞 (앞 문장을 받아서)","d":"둘 중 어느 쪽이든 된다는 뜻이에요. 안내문·시험 지시문처럼 조금 딱딱한 말에 많이 나오고, 회화에서는 보통 か를 써요 (ペンか鉛筆).","ex":[["黒または青のペンで書いてください。","くろ または あおの ペンで かいて ください。","검은색 또는 파란색 펜으로 써 주세요."],["明日、電話します。または、メールを送ります。","あした、でんわします。または、メールを おくります。","내일 전화하겠습니다. 또는 메일을 보내겠습니다."]],"cmp":[["それとも","それとも는 질문에서 '아니면?', または는 안내·설명의 '또는'"]],"qz":["答えは、えんぴつ（　　）ボールペンで書いてください。","または",["それとも","しかし","だから"],"こたえは、えんぴつ または ボールペンで かいて ください。","답은 연필 또는 볼펜으로 써 주세요.","안내하는 말에서 둘 중 하나를 고르게 하니 '또는' または. それとも는 질문에서만 쓰고, しかし·だから는 명사와 명사를 잇지 못해요."]},{"id":"b059","g":"adv","lv":4,"p":"いっしょうけんめい","m":"열심히 · 힘껏","c":"동사 앞 (いっしょうけんめい + 동사) · 문장 끝 いっしょうけんめいです · 명사 앞 いっしょうけんめいな","d":"온 힘을 다해 열심히 하는 모습이에요. 한자로 一生懸命라고 쓰고, いっしょうけんめいに처럼 に를 붙여도 같은 뜻이에요. 그 자체가 な형용사라서 'いっしょうけんめいです(열심입니다)'처럼 문장 끝에도 와요.","ex":[["毎日いっしょうけんめい練習しています。","まいにち いっしょうけんめい れんしゅうして います。","매일 열심히 연습하고 있습니다."],["田中さんはいつもいっしょうけんめいです。","たなかさんは いつも いっしょうけんめいです。","다나카 씨는 늘 열심입니다."]],"tag":"r5","cmp":[["ねっしんに","熱心に는 관심·열의를 갖고 꾸준히, いっしょうけんめい는 지금 온 힘을 다해"]],"qz":["試合に勝ちたいので、弟は（　　）走りました。","いっしょうけんめい",["もうすぐ","ちっとも","そろそろ"],"しあいに かちたいので、おとうとは いっしょうけんめい はしりました。","시합에서 이기고 싶어서 남동생은 힘껏 달렸습니다.","온 힘을 다해 달린 모습은 いっしょうけんめい. ちっとも는 뒤에 부정이 와야 하고, もうすぐ·そろそろ는 앞으로의 일이라 지난 일(～ました)과 맞지 않아요."]},{"id":"b060","g":"adv","lv":4,"p":"ぜんぜん","m":"전혀 (~않다)","c":"동사·형용사 앞 + 부정 (全然 + ～ない·～ません)","d":"뒤에 부정(～ない·～ません)이 오는 부사예요. あまり～ない(별로)보다 강한 '0%'예요. 회화에서 全然大丈夫(전혀 문제없어요)처럼 긍정과 쓰기도 하지만, 시험에서는 부정과 짝으로 외우세요.","ex":[["日本語の新聞は全然読めません。","にほんごの しんぶんは ぜんぜん よめません。","일본어 신문은 전혀 못 읽습니다."],["この映画は全然おもしろくなかったです。","この えいがは ぜんぜん おもしろく なかったです。","이 영화는 전혀 재미없었습니다."]],"tag":"r5","cmp":[["あまり～ない","あまり는 '별로'(조금은 함), 全然은 '전혀'(0%)"]],"qz":["昨日のテストは難しくて、（　　）分かりませんでした。","ぜんぜん",["ぜひ","もうすぐ","すっかり"],"きのうの テストは むずかしくて、ぜんぜん わかりませんでした。","어제 시험은 어려워서 전혀 몰랐습니다.","뒤의 부정(～ませんでした)과 짝인 '전혀'는 ぜんぜん. ぜひ는 바람·부탁, もうすぐ는 앞으로의 일, すっかり는 '완전히 ~했다'라 부정과 맞지 않아요."]},{"id":"b061","g":"adv","lv":4,"p":"なにも","m":"아무것도 (~않다)","c":"何も + 부정 (～ない·～ません) — 동사 앞","d":"何(무엇) + も 뒤에 부정이 와서 '아무것도 ~않다'가 돼요. 같은 꼴로 だれも(아무도)·どこも(어디도)가 있어요. '무언가'라고 할 때는 何か를 써요. 읽기는 なにも예요(なんも ✕).","ex":[["昨日は何もしませんでした。","きのうは なにも しませんでした。","어제는 아무것도 하지 않았습니다."],["かばんの中には何もありません。","かばんの なかには なにも ありません。","가방 안에는 아무것도 없습니다."]],"tag":"r5","cmp":[["何か","何か는 '무언가'(긍정·질문), 何も는 '아무것도'(부정)"]],"qz":["おなかが痛くて、朝から（　　）食べていません。","何も",["何か","何でも","何を"],"おなかが いたくて、あさから なにも たべて いません。","배가 아파서 아침부터 아무것도 안 먹었습니다.","부정(食べていません)과 짝인 '아무것도'는 何も. 何か는 '무언가', 何でも는 '무엇이든'이라 긍정에 쓰고, 何を는 묻는 문장에 써요."]},{"id":"b062","g":"adv","lv":4,"p":"ほんとうに","m":"정말로 · 진짜","c":"동사·형용사 앞 / 문장 앞 (本当にありがとう·本当にすみません)","d":"本当(정말) + に로, 느낌이나 말을 강하게 해요. ありがとう·すみません 앞에 붙이면 마음을 더 깊게 전할 수 있어요. 회화에서는 ほんとに라고 줄여 말하기도 해요.","ex":[["この料理は本当においしいです。","この りょうりは ほんとうに おいしいです。","이 요리는 정말 맛있습니다."],["本当にありがとうございました。","ほんとうに ありがとう ございました。","정말 감사했습니다."]],"tag":"r5","qz":["重い荷物を持ってくれて、（　　）ありがとうございました。","ほんとうに",["なかなか","ずいぶん","だいたい"],"おもい にもつを もって くれて、ほんとうに ありがとう ございました。","무거운 짐을 들어 줘서 정말 감사했습니다.","ありがとう 앞에서 고마운 마음을 강하게 하는 말은 ほんとうに. なかなか·ずいぶん·だいたい는 정도를 나타내는 말이라 인사말 앞에는 쓰지 않아요."]},{"id":"b063","g":"adv","lv":4,"p":"また","m":"또 (되풀이) · 다시 (다음에)","c":"동사 앞 / 인사: また明日·またね","d":"같은 일이 한 번 더 일어날 때 '또', 다음 기회를 말할 때 '다시'예요. 헤어질 때 また明日(내일 또 봐요)·またね(또 봐)처럼 인사로 많이 써요. まだ(아직)와 탁점(゛) 하나 차이라 헷갈리기 쉬워요.","ex":[["田中さんはまた遅れました。","たなかさんは また おくれました。","다나카 씨는 또 늦었습니다."],["では、また明日。","では、また あした。","그럼 내일 또 봐요."]],"tag":"r5","cmp":[["まだ","まだ는 '아직', また는 '또' — 탁점 하나 차이"]],"qz":["今日は楽しかったです。（　　）来週会いましょう。","また",["まだ","もっと","やっと"],"きょうは たのしかったです。また らいしゅう あいましょう。","오늘은 즐거웠어요. 다음 주에 또 만나요.","다음 기회를 말하는 '또·다시'는 また. 탁점 하나 차이인 まだ는 '아직', もっと는 '더', やっと는 '겨우'라 뜻이 맞지 않아요."]},{"id":"b064","g":"adv","lv":4,"p":"まだ","m":"아직 (~않았다) · 아직도 (~하고 있다)","c":"まだ + ～ていない (아직 안 했다) / まだ + 긍정·～ている (아직 ~하다)","d":"부정과 쓰면 '아직 안 했다', 긍정과 쓰면 '아직 계속되고 있다'예요. '아직 안 했다'는 まだ～ていません이에요(まだ食べませんでした ✕). 짧게 いいえ、まだです(아니요, 아직이요)라고도 대답해요.","ex":[["宿題はまだ終わっていません。","しゅくだいは まだ おわって いません。","숙제는 아직 안 끝났습니다."],["外はまだ雨が降っています。","そとは まだ あめが ふって います。","밖은 아직 비가 오고 있습니다."]],"tag":"r5","cmp":[["もう","もう는 '벌써 했다', まだ는 '아직 안 했다 / 아직 하고 있다'"]],"qz":["作文は（　　）書いていません。今夜書きます。","まだ",["もう","やっと","すっかり"],"さくぶんは まだ かいて いません。こんや かきます。","작문은 아직 안 썼습니다. 오늘 밤에 쓰겠습니다.","앞으로 할 일을 '아직 안 했다'고 할 때 まだ～ていません. もう～ていません은 '이제 안 한다'가 되어 今夜書きます와 어긋나고, やっと·すっかり는 부정과 안 맞아요."]},{"id":"b065","g":"adv","lv":4,"p":"まっすぐ","m":"똑바로 · 곧장 (들르지 않고)","c":"동사 앞 (まっすぐ行く·まっすぐ帰る) / まっすぐな + 명사","d":"휘지 않고 곧은 모양(똑바로)과, 중간에 다른 곳에 들르지 않고 바로 가는 것(곧장) 두 뜻이 있어요. 길 안내의 この道をまっすぐ行ってください가 단골 표현이에요.","ex":[["この道をまっすぐ行ってください。","この みちを まっすぐ いって ください。","이 길을 똑바로 가 주세요."],["今日はまっすぐ家に帰ります。","きょうは まっすぐ いえに かえります。","오늘은 곧장 집에 돌아갑니다."]],"tag":"r5","qz":["学校が終わったら、どこにもよらないで（　　）帰ってください。","まっすぐ",["なかなか","けっして","ほとんど"],"がっこうが おわったら、どこにも よらないで まっすぐ かえって ください。","학교가 끝나면 아무 데도 들르지 말고 곧장 돌아가세요.","중간에 들르지 않고 '곧장'은 まっすぐ. なかなか·けっして는 뒤에 부정이 와야 하고, ほとんど는 '거의'라 부탁(～てください)과 맞지 않아요."]},{"id":"b066","g":"adv","lv":4,"p":"もう","m":"벌써 · 이미 · 이제 · 더 (もう一つ)","c":"もう + 과거·완료 (벌써 ~했다) / もう + 수량 (~ 더) / もう + 부정 (이제 ~않다)","d":"뜻이 여럿이에요. ① もう食べました(벌써 먹었어요) ② もう一つ·もう少し(하나 더·조금 더) ③ もう行きません(이제 안 가요). 'もう~했어요?'에 아직이면 まだです로 대답해요.","ex":[["電車はもう出ました。","でんしゃは もう でました。","전철은 벌써 떠났습니다."],["もう一度言ってください。","もう いちど いって ください。","한 번 더 말해 주세요."]],"tag":"r5","cmp":[["もうすぐ","もうすぐ는 '곧(머지않아)' — 앞으로 일어날 일"]],"qz":["宿題は（　　）終わりました。今からテレビを見ます。","もう",["まだ","もうすぐ","そろそろ"],"しゅくだいは もう おわりました。いまから テレビを みます。","숙제는 벌써 끝났습니다. 지금부터 텔레비전을 봅니다.","이미 끝난 일(～ました)에는 もう. まだ는 '아직 안 했다'에 쓰고, もうすぐ·そろそろ는 앞으로 일어날 일이라 과거형과 맞지 않아요."]},{"id":"b067","g":"adv","lv":4,"p":"もうすぐ","m":"곧 · 이제 곧 (머지않아)","c":"문장 앞·동사 앞 (もうすぐ + 명사です / もうすぐ + 동사)","d":"얼마 안 있으면 어떤 때가 온다는 뜻이에요. もうすぐ夏休みです처럼 명사와도 잘 써요. すぐ는 '지금 바로', もうすぐ는 '얼마 안 있으면'이에요.","ex":[["もうすぐ十二時です。","もうすぐ じゅうにじです。","곧 12시입니다."],["バスはもうすぐ来ますよ。","バスは もうすぐ きますよ。","버스는 곧 와요."]],"tag":"r5","cmp":[["すぐ","すぐ는 '즉시·바로'(すぐ行きます 바로 갈게요), もうすぐ는 '머지않아'"]],"qz":["（　　）電車が来ますから、白い線の後ろで待ってください。","もうすぐ",["まだ","もっと","ずっと"],"もうすぐ でんしゃが きますから、しろい せんの うしろで まって ください。","곧 전철이 오니까 흰 선 뒤에서 기다려 주세요.","얼마 안 있어 온다는 '곧'은 もうすぐ. まだ는 '아직', もっと는 '더', ずっと는 '계속·훨씬'이라 곧 일어날 일을 말하지 못해요."]},{"id":"b068","g":"adv","lv":4,"p":"ゆっくり","m":"천천히 · 푹 (편히)","c":"동사 앞 (ゆっくり話す·ゆっくり休む)","d":"속도가 느린 '천천히'와, 서두르지 않고 편히 쉬는 '푹·느긋하게' 두 뜻이에요. どうぞごゆっくり(천천히 편하게 계세요)는 손님에게 하는 인사예요.","ex":[["もう少しゆっくり話してください。","もう すこし ゆっくり はなして ください。","조금 더 천천히 말해 주세요."],["日曜日は家でゆっくり休みました。","にちようびは いえで ゆっくり やすみました。","일요일에는 집에서 푹 쉬었습니다."]],"tag":"r5","qz":["つかれたでしょう。おふろに入って、（　　）休んでください。","ゆっくり",["すっかり","まっすぐ","ずいぶん"],"つかれたでしょう。おふろに はいって、ゆっくり やすんで ください。","피곤하죠? 목욕하고 푹 쉬세요.","서두르지 않고 편히 쉬는 '푹'은 ゆっくり. すっかり는 '완전히 ~해 버렸다', まっすぐ는 '곧장', ずいぶん은 '꽤'라 쉬라는 부탁과 맞지 않아요."]},{"id":"b069","g":"adv","lv":4,"p":"よく","m":"자주 · 잘","c":"동사 앞 (よく行く 자주 가다 / よく分かる 잘 알다)","d":"いい(좋다)의 부사형이라 '잘'과 '자주' 두 뜻이 있어요. 문맥으로 구별해요: よく行きます(자주 가요) / よく分かりました(잘 알았어요). 빈도 순서는 いつも > よく > 時々예요.","ex":[["父とよく山に登ります。","ちちと よく やまに のぼります。","아버지와 자주 산에 오릅니다."],["先生の説明がよく分かりました。","せんせいの せつめいが よく わかりました。","선생님 설명을 잘 알았습니다."]],"tag":"r5","qz":["弟は外で遊ぶのが好きで、（　　）この公園に来ます。","よく",["なかなか","ちっとも","あまり"],"おとうとは そとで あそぶのが すきで、よく この こうえんに きます。","남동생은 밖에서 노는 것을 좋아해서 이 공원에 자주 옵니다.","긍정문에서 '자주'는 よく. なかなか·ちっとも·あまり는 뒤에 ～ない가 와야 하는 말이라 来ます와 함께 쓸 수 없어요."]},{"id":"b070","g":"adv","lv":4,"p":"早く","m":"일찍 · 빨리 (어서)","c":"동사 앞 (早く起きる·早く来る) — い형용사 早い의 い → く","d":"早い(이르다)의 い를 く로 바꾼 부사예요. 시간이 이르면 '일찍', 서두르라는 뜻이면 '빨리·어서'예요. 속도가 빠른 것은 같은 소리지만 速く로 써요: 速く走る(빨리 달리다).","ex":[["毎朝早く家を出ます。","まいあさ はやく いえを でます。","매일 아침 일찍 집을 나섭니다."],["早く来てください。","はやく きて ください。","빨리 와 주세요."]],"tag":"r5","cmp":[["速く","같은 はやく지만 速く는 속도(빨리 달리다), 早く는 시간(일찍·어서)"]],"qz":["明日は六時の電車に乗るので、（　　）起きなければなりません。","早く",["速く","遅く","長く"],"あしたは ろくじの でんしゃに のるので、はやく おきなければ なりません。","내일은 6시 전철을 타니까 일찍 일어나야 합니다.","시간이 이른 '일찍'은 早く. 같은 소리인 速く는 속도(빨리 달리다)에 쓰고, 遅く는 '늦게', 長く는 '오래'라 맞지 않아요."]},{"id":"b071","g":"adv","lv":4,"p":"ほとんど","m":"거의 · 대부분","c":"동사 앞 (ほとんど終わった) / ほとんど + 부정 (거의 ~않다) / ほとんどの + 명사","d":"긍정과 쓰면 '거의 다', 부정과 쓰면 '거의 ~않다'예요. 명사처럼 ほとんどの人(대부분의 사람)라고도 써요.","ex":[["お金はほとんど使いました。","おかねは ほとんど つかいました。","돈은 거의 다 썼습니다."],["漢字はほとんど読めません。","かんじは ほとんど よめません。","한자는 거의 못 읽습니다."]],"tag":"r5","qz":["クラスの（　　）の人が、自転車で学校に来ます。","ほとんど",["ぜんぜん","みんな","とても"],"クラスの ほとんどの ひとが、じてんしゃで がっこうに きます。","반의 대부분 사람이 자전거로 학교에 옵니다.","の를 붙여 '대부분의 사람'이 되는 것은 ほとんど. ぜんぜん·とても는 の를 붙여 명사 앞에 쓸 수 없고, みんな는 みんなの人라고 하지 않아요."]},{"id":"b072","g":"adv","lv":4,"p":"必ず","m":"반드시 · 꼭 (예외 없이)","c":"동사 앞 — 약속·규칙·늘 그런 일 (必ず行きます·必ず～てください)","d":"'틀림없이 그렇게 한다/된다'는 강한 말이에요. 내 약속(必ず行きます), 늘 하는 습관, 규칙(必ず名前を書いてください)에 써요. 말하는 사람의 추측 '분명 ~일 거예요'에는 きっと가 자연스러워요.","ex":[["約束は必ず守ります。","やくそくは かならず まもります。","약속은 반드시 지킵니다."],["寝る前に必ず歯をみがきます。","ねる まえに かならず はを みがきます。","자기 전에 반드시 이를 닦습니다."]],"cmp":[["きっと","きっと는 '분명 ~일 거야'(확신 있는 추측), 必ず는 '반드시'(예외 없음·약속)"]],"qz":["教室に入る前に、（　　）くつをぬいでください。","必ず",["たぶん","まさか","なかなか"],"きょうしつに はいる まえに、かならず くつを ぬいで ください。","교실에 들어가기 전에 반드시 신발을 벗어 주세요.","예외 없이 지켜야 할 규칙에는 必ず. たぶん은 '아마'(추측), まさか는 '설마', なかなか는 '좀처럼 ~않다'라 부탁(～てください)과 맞지 않아요."]},{"id":"b073","g":"adv","lv":4,"p":"きっと","m":"분명 · 틀림없이 (~일 거예요)","c":"문장 앞·동사 앞 — 뒤에 ～でしょう·～と思う가 잘 옴","d":"말하는 사람이 강하게 믿는 추측이에요. たぶん(아마)보다 확신이 커요. きっと来てね(꼭 와)처럼 상대에게 바랄 때도 써요.","ex":[["明日はきっと晴れるでしょう。","あしたは きっと はれるでしょう。","내일은 분명 맑을 겁니다."],["田中さんはきっと来ると思います。","たなかさんは きっと くると おもいます。","다나카 씨는 분명 올 거라고 생각합니다."]],"cmp":[["たぶん","たぶん은 '아마'(반쯤 확신), きっと는 '분명'(거의 확신)"]],"qz":["田中さんは毎日練習しているから、明日の試合に（　　）勝つでしょう。","きっと",["ぜひ","けっして","まさか"],"たなかさんは まいにち れんしゅうして いるから、あしたの しあいに きっと かつでしょう。","다나카 씨는 매일 연습하고 있으니까 내일 시합에서 분명 이길 거예요.","확신 있는 추측(～でしょう)에는 きっと. ぜひ는 바람·부탁(～たい·～てください)에 쓰고, けっして·まさか는 뒤에 부정이 와야 해서 勝つでしょう와 맞지 않아요."]},{"id":"b074","g":"adv","lv":4,"p":"けっして","m":"결코 · 절대로 (~않다)","c":"決して + 부정 (～ない·～ません·～ないでください)","d":"뒤에 반드시 부정이 와요(決して～ない). 강한 결심이나 금지에 써요: 決して忘れません(결코 잊지 않겠습니다). 絶対に는 긍정·부정 둘 다 되지만, 決して는 부정만 돼요.","ex":[["このことは決して忘れません。","この ことは けっして わすれません。","이 일은 결코 잊지 않겠습니다."],["危ないですから、決してさわらないでください。","あぶないですから、けっして さわらないで ください。","위험하니까 절대로 만지지 마세요."]],"cmp":[["絶対に","絶対に는 긍정도 됨(絶対に行く), 決して는 부정만(決して行かない)"]],"qz":["これはひみつです。だれにも（　　）言わないでください。","けっして",["ぜひ","もし","ちっとも"],"これは ひみつです。だれにも けっして いわないで ください。","이건 비밀이에요. 누구에게도 절대로 말하지 마세요.","강한 금지(～ないでください)와 짝인 '절대로'는 けっして. ぜひ는 '꼭 해 주세요'처럼 긍정 부탁에, もし는 조건에 쓰고, ちっとも는 금지에 쓰지 않아요."]},{"id":"b075","g":"adv","lv":4,"p":"しっかり","m":"제대로 · 단단히 · (사람이) 야무지게","c":"동사 앞 (しっかり持つ·しっかり食べる) / しっかりしている·しっかりした + 명사","d":"빈틈없이 확실하게 하는 모습이에요. 손으로 꽉 잡을 때(しっかり持つ), 충분히 할 때(しっかり食べる·しっかり休む) 써요. 사람이 しっかりしている는 '야무지다·믿음직하다'라는 뜻이에요.","ex":[["朝ごはんをしっかり食べましょう。","あさごはんを しっかり たべましょう。","아침밥을 제대로 먹읍시다."],["田中さんの妹はしっかりしています。","たなかさんの いもうとは しっかり して います。","다나카 씨 여동생은 야무집니다."]],"qz":["このはこは重いですから、両手で（　　）持ってください。","しっかり",["すっかり","はっきり","ずいぶん"],"この はこは おもいですから、りょうてで しっかり もって ください。","이 상자는 무거우니까 두 손으로 단단히 들어 주세요.","손으로 꽉 잡는 '단단히'는 しっかり. 소리가 비슷한 すっかり는 '완전히', はっきり는 '또렷이', ずいぶん은 '꽤'라 持つ와 맞지 않아요."]},{"id":"b076","g":"adv","lv":4,"p":"ずいぶん","m":"꽤 · 상당히 · 몹시","c":"형용사·동사 앞 (ずいぶん寒い·ずいぶん大きくなった)","d":"생각보다 정도가 크다는 놀라움이 담긴 말이에요. 예전과 비교해 많이 달라졌을 때 잘 써요: ずいぶん大きくなりましたね(많이 컸네요).","ex":[["今日はずいぶん寒いですね。","きょうは ずいぶん さむいですね。","오늘은 꽤 춥네요."],["子どもがずいぶん大きくなりましたね。","こどもが ずいぶん おおきく なりましたね。","아이가 많이 컸네요."]],"cmp":[["とても","とても는 단순히 '매우', ずいぶん은 '생각보다 꽤'라는 놀람"]],"qz":["三年ぶりに会ったいとこは、（　　）背が高くなっていました。","ずいぶん",["まだ","まっすぐ","そろそろ"],"さんねんぶりに あった いとこは、ずいぶん せが たかく なって いました。","3년 만에 만난 사촌은 꽤 키가 커져 있었습니다.","예전과 비교해 생각보다 많이 변했을 때 ずいぶん. まだ는 '아직', まっすぐ는 '똑바로', そろそろ는 '슬슬'이라 변한 정도를 나타내지 못해요."]},{"id":"b077","g":"adv","lv":4,"p":"すっかり","m":"완전히 · 까맣게 (잊다) · 말끔히","c":"동사 앞 — 주로 과거·완료와 (すっかり忘れた·すっかりよくなった)","d":"남김없이 완전히 그렇게 되었다는 뜻이에요. 그래서 주로 ～た·～ている·～てしまった와 함께 써요: すっかり忘れていました(까맣게 잊고 있었어요).","ex":[["約束をすっかり忘れていました。","やくそくを すっかり わすれて いました。","약속을 까맣게 잊고 있었습니다."],["風邪はすっかりよくなりました。","かぜは すっかり よく なりました。","감기는 완전히 나았습니다."]],"qz":["今日は友だちの誕生日だったのに、（　　）忘れていました。","すっかり",["しっかり","はっきり","もうすぐ"],"きょうは ともだちの たんじょうびだったのに、すっかり わすれて いました。","오늘은 친구 생일이었는데 까맣게 잊고 있었습니다.","남김없이 '까맣게 잊다'는 すっかり忘れる. しっかり는 '단단히', はっきり는 '또렷이'라 忘れる와 안 어울리고, もうすぐ는 앞으로의 일이에요."]},{"id":"b078","g":"adv","lv":4,"p":"ずっと","m":"쭉 · 계속 · 훨씬 (비교)","c":"동사 앞 (ずっと待つ: 계속) / A は B より ずっと + 형용사 (훨씬)","d":"시간이 이어지면 '쭉·계속', 비교할 때는 '훨씬'이에요. より와 함께 오면 '훨씬'으로 옮기면 돼요: 去年よりずっと暑い(작년보다 훨씬 덥다).","ex":[["朝からずっと雨が降っています。","あさから ずっと あめが ふって います。","아침부터 계속 비가 오고 있습니다."],["電車はバスよりずっと速いです。","でんしゃは バスより ずっと はやいです。","전철은 버스보다 훨씬 빠릅니다."]],"cmp":[["もっと","もっと는 '더'(앞으로 더: もっと食べたい), ずっと는 '훨씬'(이미 큰 차이)"]],"qz":["雨だったので、朝から夜まで（　　）部屋で本を読んでいました。","ずっと",["もっと","やっと","すっかり"],"あめだったので、あさから よるまで ずっと へやで ほんを よんで いました。","비가 와서 아침부터 밤까지 계속 방에서 책을 읽고 있었습니다.","～から～まで 이어지는 시간에는 '계속'인 ずっと. もっと는 '더', やっと는 '겨우', すっかり는 '완전히'라 이어진 시간을 나타내지 못해요."]},{"id":"b079","g":"adv","lv":4,"p":"ぜひ","m":"꼭 · 부디 (바람·부탁)","c":"ぜひ + ～たい / ～てください / ～てほしい","d":"내가 꼭 하고 싶은 일(～たい)이나, 상대에게 꼭 해 달라는 부탁·권유(～てください)와 짝이에요. 부정이나 추측에는 쓰지 않아요(ぜひ行かない ✕). 초대에 ぜひ!(꼭이요!)라고만 대답하기도 해요.","ex":[["いつかぜひ富士山に登りたいです。","いつか ぜひ ふじさんに のぼりたいです。","언젠가 꼭 후지산에 오르고 싶습니다."],["今度ぜひ遊びに来てください。","こんど ぜひ あそびに きて ください。","다음에 꼭 놀러 와 주세요."]],"cmp":[["必ず","必ず는 '반드시'(약속·규칙), ぜひ는 '꼭'(바람·부탁)"]],"qz":["日本に行ったら、（　　）おすしを食べてみたいです。","ぜひ",["きっと","けっして","たぶん"],"にほんに いったら、ぜひ おすしを たべて みたいです。","일본에 가면 꼭 초밥을 먹어 보고 싶습니다.","바람(～たい)과 짝인 '꼭'은 ぜひ. きっと·たぶん은 추측이라 ～たい와 어울리지 않고, けっして는 뒤에 부정이 와야 해요."]},{"id":"b080","g":"adv","lv":4,"p":"そろそろ","m":"슬슬 · 이제 (곧)","c":"문장 앞·동사 앞 (そろそろ + ～ましょう·～ます / そろそろ + 명사です)","d":"'이제 슬슬 그럴 때가 되었다'는 느낌이에요. 자리를 뜰 때 そろそろ帰りましょう·そろそろ失礼します처럼 많이 써요. そろそろ時間です(이제 시간이 됐어요)처럼도 써요.","ex":[["そろそろ行きましょうか。","そろそろ いきましょうか。","슬슬 갈까요?"],["そろそろ寝る時間ですよ。","そろそろ ねる じかんですよ。","이제 잘 시간이에요."]],"cmp":[["もうすぐ","もうすぐ는 '머지않아'(그때가 다가옴), そろそろ는 '이제 슬슬 ~할 때'(행동을 시작할 때)"]],"qz":["もう五時ですね。（　　）帰りましょうか。","そろそろ",["もうすぐ","まだ","やっと"],"もう ごじですね。そろそろ かえりましょうか。","벌써 5시네요. 슬슬 돌아갈까요?","'이제 슬슬 ~할 때'라고 행동을 권할 때 そろそろ. もうすぐ는 '머지않아 그때가 온다'라 ～ましょう와 안 어울리고, まだ는 '아직', やっと는 '겨우'예요."]},{"id":"b081","g":"adv","lv":4,"p":"だいたい","m":"대체로 · 대강 · 대략 (약)","c":"동사 앞 (だいたい分かる) / 수량 앞 (だいたい十五分)","d":"전부는 아니지만 큰 부분은 그렇다는 뜻이에요. 수량 앞에 오면 '약·대략'이에요(だいたい十五分 약 15분). 한자로 大体라고 써요.","ex":[["話はだいたい分かりました。","はなしは だいたい わかりました。","이야기는 대강 알았습니다."],["駅まで歩いてだいたい十五分です。","えきまで あるいて だいたい じゅうごふんです。","역까지 걸어서 대략 15분입니다."]],"cmp":[["ほとんど","ほとんど는 '거의 다'(100%에 가까움), だいたい는 '대체로'(큰 부분)"]],"qz":["家から学校まで、歩いて（　　）二十分かかります。","だいたい",["ぜんぜん","もっと","すっかり"],"いえから がっこうまで、あるいて だいたい にじゅっぷん かかります。","집에서 학교까지 걸어서 대략 20분 걸립니다.","수량 앞에서 '약·대략'은 だいたい. ぜんぜん은 부정과 짝이고, もっと는 '더', すっかり는 '완전히'라 수량 앞에 쓰지 않아요."]},{"id":"b082","g":"adv","lv":4,"p":"とくに","m":"특히 · 특별히","c":"동사·형용사·명사 앞 / 特に + 부정 (특별히 ~않다)","d":"여럿 가운데 하나를 골라 강조해요. 特に～ない는 '특별히 ~않다'로, 特にありません(특별히 없어요)은 질문에 대답할 때 자주 써요. 한자로 特に라고 써요.","ex":[["今年の夏は特に暑いです。","ことしの なつは とくに あついです。","올여름은 특히 덥습니다."],["質問は特にありません。","しつもんは とくに ありません。","질문은 특별히 없습니다."]],"qz":["果物は何でも好きですが、（　　）りんごが好きです。","とくに",["ぜんぜん","やっと","もうすぐ"],"くだものは なんでも すきですが、とくに りんごが すきです。","과일은 뭐든지 좋아하지만 특히 사과를 좋아합니다.","여럿 가운데 하나를 골라 강조하는 '특히'는 とくに. ぜんぜん은 부정과 짝이고, やっと는 '겨우', もうすぐ는 '곧'이라 뜻이 맞지 않아요."]},{"id":"b083","g":"adv","lv":4,"p":"なかなか","m":"좀처럼 (~않다) · 꽤 · 제법","c":"なかなか + 부정 (좀처럼 ~않다) / なかなか + 긍정 형용사 (꽤 ~하다)","d":"부정과 쓰면 '좀처럼 ~않다'(바라는 대로 잘 안 됨), 긍정과 쓰면 '꽤·제법'(생각보다 그렇다)이에요. 같은 말인데 뒤에 따라 뜻이 갈려서 시험에 잘 나와요.","ex":[["夜、なかなか眠れません。","よる、なかなか ねむれません。","밤에 좀처럼 잠이 오지 않습니다."],["この店のラーメンはなかなかおいしいです。","この みせの ラーメンは なかなか おいしいです。","이 가게 라면은 꽤 맛있습니다."]],"qz":["新しい漢字を何回も書きましたが、（　　）覚えられません。","なかなか",["もうすぐ","やっと","すっかり"],"あたらしい かんじを なんかいも かきましたが、なかなか おぼえられません。","새 한자를 여러 번 썼지만 좀처럼 외워지지 않습니다.","애써도 바라는 대로 안 될 때 부정과 짝인 なかなか(좀처럼). もうすぐ·やっと·すっかり는 긍정과 쓰는 말이라 ～られません과 맞지 않아요."]},{"id":"b084","g":"adv","lv":4,"p":"なるほど","m":"과연 · 그렇군요 (납득)","c":"문장 앞 (맞장구·감탄)","d":"상대 설명을 듣고 '아, 그래서 그렇구나' 하고 납득할 때 써요. 윗사람에게 なるほど만 말하면 조금 가볍게 들릴 수 있어서, そうなんですね를 함께 쓰면 좋아요.","ex":[["なるほど、そういう意味ですか。","なるほど、そういう いみですか。","그렇군요, 그런 뜻이에요?"],["なるほど、だから人が多いんですね。","なるほど、だから ひとが おおいんですね。","과연, 그래서 사람이 많군요."]],"qz":["毎朝走っているんですか。（　　）、それでいつも元気なんですね。","なるほど",["まさか","もし","ぜひ"],"まいあさ はしって いるんですか。なるほど、それで いつも げんきなんですね。","매일 아침 달리고 있어요? 그렇군요, 그래서 늘 활기차군요.","설명을 듣고 '그래서 그렇구나' 하고 납득할 때 なるほど. まさか는 믿기 어려울 때, もし는 조건, ぜひ는 바람·부탁이라 ～んですね와 맞지 않아요."]},{"id":"b085","g":"adv","lv":4,"p":"なんでも","m":"무엇이든 · 뭐든지","c":"何でも + 긍정 (동사 앞) — 何 + でも","d":"何 + でも로 '어떤 것이든 다'라는 뜻이고, 뒤에 긍정이 와요: 何でも食べます(뭐든지 먹어요). 같은 꼴로 だれでも(누구든지)·どこでも(어디든지)·いつでも(언제든지)가 있어요. 읽기는 なんでも예요.","ex":[["私は何でも食べます。","わたしは なんでも たべます。","저는 뭐든지 먹습니다."],["分からないことは何でも聞いてください。","わからない ことは なんでも きいて ください。","모르는 것은 무엇이든 물어봐 주세요."]],"cmp":[["何も","何も + 부정 = 아무것도 ~않다, 何でも + 긍정 = 무엇이든 ~하다"]],"qz":["弟は好ききらいがなくて、（　　）食べます。","何でも",["何も","何を","何が"],"おとうとは すききらいが なくて、なんでも たべます。","남동생은 가리는 음식이 없어서 뭐든지 먹습니다.","긍정(食べます)과 쓰는 '무엇이든'은 何でも. 何も는 부정과 짝이고, 何を·何が는 묻는 문장에 써요."]},{"id":"b086","g":"adv","lv":4,"p":"ねっしんに","m":"열심히 (열의를 가지고)","c":"동사 앞 (熱心に勉強する) / 熱心な + 명사 / 熱心です","d":"관심과 열의를 갖고 꾸준히 하는 모습이에요. な형용사 熱心(열심이다)에 に가 붙은 꼴이라 熱心な先生(열성적인 선생님)처럼도 써요. 공부·일·연습처럼 계속하는 일에 잘 어울려요.","ex":[["学生たちは熱心に話を聞いています。","がくせいたちは ねっしんに はなしを きいて います。","학생들은 열심히 이야기를 듣고 있습니다."],["田中さんは熱心な先生です。","たなかさんは ねっしんな せんせいです。","다나카 씨는 열성적인 선생님입니다."]],"cmp":[["いっしょうけんめい","いっしょうけんめい는 '온 힘을 다해'(지금 이 순간), 熱心に는 '열의를 갖고 꾸준히'"]],"qz":["妹は毎日（　　）ピアノを練習しています。","熱心に",["熱心な","熱心の","熱心で"],"いもうとは まいにち ねっしんに ピアノを れんしゅうして います。","여동생은 매일 열심히 피아노를 연습하고 있습니다.","동사(練習する)를 꾸미려면 な형용사 熱心에 に를 붙인 熱心に. 熱心な는 명사 앞(熱心な先生)에 쓰고, 熱心の·熱心で는 이 자리에 쓸 수 없어요."]},{"id":"b087","g":"adv","lv":4,"p":"はっきり","m":"분명히 · 또렷이 · 확실히","c":"동사 앞 (はっきり言う·はっきり見える) / はっきりする (분명해지다)","d":"모양·소리·말이 흐리지 않고 분명한 모습이에요. はっきり見える(또렷이 보이다)처럼 눈·귀로 느끼는 것에도, はっきり言う(분명하게 말하다)처럼 태도에도 써요.","ex":[["今日は富士山がはっきり見えます。","きょうは ふじさんが はっきり みえます。","오늘은 후지산이 또렷이 보입니다."],["いやなことははっきり言ったほうがいいです。","いやな ことは はっきり いった ほうが いいです。","싫은 일은 분명히 말하는 편이 좋습니다."]],"qz":["めがねをかけると、黒板の字が（　　）見えます。","はっきり",["すっかり","そろそろ","なかなか"],"めがねを かけると、こくばんの じが はっきり みえます。","안경을 쓰면 칠판 글씨가 또렷이 보입니다.","흐리지 않고 '또렷이 보인다'는 はっきり. すっかり는 '완전히 ~해 버렸다', そろそろ는 '슬슬'이고, なかなか는 부정과 짝이라 見えます와 맞지 않아요."]},{"id":"b088","g":"adv","lv":4,"p":"ひじょうに","m":"매우 · 대단히","c":"형용사·동사 앞 (非常に寒い·非常に役に立つ)","d":"とても와 같은 뜻이지만 딱딱한 말이라 뉴스·안내·글에서 많이 써요. 친구끼리 말할 때는 とても·すごく를 써요. 한자로 非常に라고 써요.","ex":[["今日は非常に暑くなるでしょう。","きょうは ひじょうに あつく なるでしょう。","오늘은 매우 더워지겠습니다."],["この問題は非常に大切です。","この もんだいは ひじょうに たいせつです。","이 문제는 대단히 중요합니다."]],"cmp":[["とても","とても는 일상 회화, 非常に는 공식적인 말·글"]],"qz":["この本は、日本語の勉強に（　　）役に立ちます。","ひじょうに",["ぜんぜん","けっして","ほとんど"],"この ほんは、にほんごの べんきょうに ひじょうに やくに たちます。","이 책은 일본어 공부에 대단히 도움이 됩니다.","정도가 아주 큰 '대단히'는 ひじょうに. ぜんぜん·けっして는 뒤에 부정이 와야 하고, ほとんど는 '거의'라 役に立ちます와 맞지 않아요."]},{"id":"b089","g":"adv","lv":4,"p":"まさか","m":"설마","c":"문장 앞 — まさか + ～ないだろう·～ないでしょう / まさか、～の？(놀람) / まさか！(단독)","d":"'그럴 리 없다'고 믿는 마음이에요. 뒤에 부정 추측 ～ないだろう·～ないでしょう가 잘 와요. 뜻밖의 일에 놀라서 まさか!(설마!)라고만 말하기도 해요. 주로 회화에서 써요.","ex":[["まさか雨は降らないだろう。","まさか あめは ふらないだろう。","설마 비는 안 오겠지."],["まさか、もう全部食べたの？","まさか、もう ぜんぶ たべたの？","설마 벌써 다 먹었어?"]],"qz":["（　　）、あの小さい子が一人でここまで来たの？","まさか",["もし","ぜひ","なるほど"],"まさか、あの ちいさい こが ひとりで ここまで きたの？","설마 저 꼬마가 혼자서 여기까지 온 거야?","믿기 어려운 일에 놀라 묻는 '설마'는 まさか. もし는 조건(～たら), ぜひ는 바람·부탁, なるほど는 납득할 때라 놀라는 질문과 맞지 않아요."]},{"id":"b090","g":"adv","lv":4,"p":"まず","m":"우선 · 먼저 · 일단","c":"문장 앞·동사 앞 (まず～、それから～)","d":"여러 일 중 첫 번째를 말할 때 써요. まず～、それから(次に)～、最後に～처럼 순서를 설명할 때 단골이에요.","ex":[["まず名前を書いてください。","まず なまえを かいて ください。","우선 이름을 써 주세요."],["まず駅まで歩いて、それからバスに乗ります。","まず えきまで あるいて、それから バスに のります。","먼저 역까지 걸어가서, 그다음에 버스를 탑니다."]],"cmp":[["先に","先に는 '다른 사람·다른 일보다 먼저'(お先に·先に宿題をする), まず는 '여러 순서 중 첫째'"]],"qz":["カレーを作ります。（　　）野菜を洗って、それから切ります。","まず",["最後に","もし","やっと"],"カレーを つくります。まず やさいを あらって、それから きります。","카레를 만듭니다. 우선 채소를 씻고 그다음에 썹니다.","순서의 첫째(まず～、それから～)는 まず. 最後に는 '마지막에'라 뒤의 それから와 어긋나고, もし는 조건, やっと는 '겨우'예요."]},{"id":"b091","g":"adv","lv":4,"p":"もし","m":"만약 · 혹시","c":"문장 앞 — もし + ～たら / ～ば / ～なら / ～ても","d":"조건 문형(～たら·～ば·～なら)과 짝을 이뤄 '만약 그렇다면'을 미리 알려 줘요. もし만 쓰고 뒤를 조건형으로 바꾸지 않으면 틀려요(もし雨が降ります、～ ✕).","ex":[["もし時間があったら、手伝ってください。","もし じかんが あったら、てつだって ください。","만약 시간이 있으면 도와주세요."],["もし分からなければ、聞いてください。","もし わからなければ、きいて ください。","혹시 모르면 물어봐 주세요."]],"qz":["（　　）道が分からなかったら、電話してください。","もし",["きっと","ぜひ","たぶん"],"もし みちが わからなかったら、でんわして ください。","혹시 길을 모르겠으면 전화해 주세요.","조건 ～たら와 짝인 '만약·혹시'는 もし. きっと·たぶん은 추측, ぜひ는 바람이라 조건을 나타내는 문장 앞에 쓰지 않아요."]},{"id":"b092","g":"adv","lv":4,"p":"もっとも","m":"가장 · 제일 (딱딱한 말)","c":"형용사 앞 (最も高い·最も大切な)","d":"一番과 같은 '가장'이지만 글·뉴스에서 쓰는 딱딱한 말이에요. 한자로 最も라고 쓰고, 회화에서는 一番을 써요. もっと(더)와 も 하나 차이라 헷갈리지 않게 조심하세요.","ex":[["富士山は日本で最も高い山です。","ふじさんは にほんで もっとも たかい やまです。","후지산은 일본에서 가장 높은 산입니다."],["これは最も大切な問題です。","これは もっとも たいせつな もんだいです。","이것은 가장 중요한 문제입니다."]],"cmp":[["もっと","もっと는 '더'(비교), もっとも는 '가장'(최고)"],["一番","같은 '가장'이지만 一番은 회화, 最も는 글"]],"qz":["この川は日本で（　　）長い川です。","もっとも",["もっと","ずっと","まだ"],"この かわは にほんで もっとも ながい かわです。","이 강은 일본에서 가장 긴 강입니다.","'~에서 가장'은 もっとも(最も). も 하나 차이인 もっと는 '더', ずっと는 '훨씬'으로 둘을 비교할 때 쓰고, まだ는 '아직'이라 맞지 않아요."]},{"id":"b093","g":"adv","lv":4,"p":"やっと","m":"겨우 · 간신히 · 드디어","c":"동사 앞 — 주로 과거 (やっと着いた) / やっと + 가능형 (간신히 ~할 수 있다)","d":"오래 기다리거나 고생한 끝에 바라던 일이 이루어졌다는 뜻이에요. 그래서 바라던 결과와 함께 써요. 결국 안 좋게 끝났을 때는 とうとう(결국)를 써요.","ex":[["一時間待って、やっとバスが来ました。","いちじかん まって、やっと バスが きました。","한 시간 기다려서 드디어 버스가 왔습니다."],["宿題がやっと終わりました。","しゅくだいが やっと おわりました。","숙제가 겨우 끝났습니다."]],"cmp":[["とうとう","とうとう는 좋든 나쁘든 '결국·마침내'(とうとう来なかった), やっと는 바라던 일만"]],"qz":["何回も練習して、（　　）自転車に乗れるようになりました。","やっと",["まだ","もうすぐ","なかなか"],"なんかいも れんしゅうして、やっと じてんしゃに のれる ように なりました。","여러 번 연습해서 드디어 자전거를 탈 수 있게 되었습니다.","고생 끝에 바라던 일이 이루어졌을 때 やっと. まだ는 '아직', もうすぐ는 앞으로의 일, なかなか는 부정과 짝이라 ～ました와 맞지 않아요."]},{"id":"b094","g":"adv","lv":4,"p":"やはり／やっぱり","m":"역시 · 예상대로 · (생각해 보니) 그래도","c":"문장 앞·동사 앞 / やっぱり는 회화체","d":"① 생각했던 대로였다(역시) ② 이리저리 생각해 봐도 결국 그렇다는 뜻이에요. ②는 마음을 바꿀 때도 써요: やっぱり行かない(역시 안 갈래). やっぱり는 やはり의 회화형이에요.","ex":[["やはり田中さんが一番上手でした。","やはり たなかさんが いちばん じょうずでした。","역시 다나카 씨가 제일 잘했습니다."],["やっぱり、今日は行かないことにします。","やっぱり、きょうは いかない ことに します。","역시 오늘은 안 가기로 할게요."]],"qz":["朝から空が暗いと思っていたら、（　　）雨が降ってきました。","やはり",["まさか","もし","ぜひ"],"あさから そらが くらいと おもって いたら、やはり あめが ふって きました。","아침부터 하늘이 어둡다 싶더니 역시 비가 오기 시작했습니다.","생각했던 대로 되었을 때 '역시'는 やはり. まさか는 '설마(그럴 리 없다)', もし는 조건, ぜひ는 바람이라 뜻이 맞지 않아요."]},{"id":"b095","g":"part","lv":4,"p":"～か（～인지·~이나）","m":"~나 (A나 B) · ~인지 (문장 속 질문)","c":"명사 + か + 명사 (A か B) / 의문사가 든 보통형 + か (～か分かりません)","d":"둘 중 하나를 고를 때 'A나 B'예요(コーヒーか紅茶 커피나 홍차). 의문사가 든 문장 뒤에 붙이면 '~인지'가 되어 문장 속에 질문을 넣어요(どこにあるか 어디에 있는지). 문장 끝의 질문 か(~까?)와 같은 글자예요.","ex":[["土曜日か日曜日に行きます。","どようびか にちようびに いきます。","토요일이나 일요일에 갑니다."],["かぎがどこにあるか分かりません。","かぎが どこに あるか わかりません。","열쇠가 어디에 있는지 모르겠습니다."]],"tag":"r5","cmp":[["～や","や는 '~랑'(둘 다 해당), か는 '~나'(둘 중 하나)"]],"qz":["テストが何時に始まる（　　）知っていますか。","か",["が","を","と"],"テストが なんじに はじまるか しって いますか。","시험이 몇 시에 시작하는지 알고 있어요?","의문사(何時)가 든 문장을 '~인지'로 문장 속에 넣을 때 か. が·を·と를 붙이면 문장 속 질문이 되지 않아요."]},{"id":"b096","g":"part","lv":4,"p":"～が","m":"~이/가 (주어) · ~을/를 (好き·分かる 등 앞) · ~지만","c":"명사 + が (주어) / 명사 + が + 好き·上手·分かる·ほしい / 문장 + が (~지만)","d":"기본은 주어 '~이/가'예요. 好き·嫌い·上手·分かる·ほしい 앞에서는 한국어로 '~을'이지만 が를 써요. 문장 뒤에 붙으면 '~지만'이에요(高いですが 비싸지만).","ex":[["庭に花がさいています。","にわに はなが さいて います。","마당에 꽃이 피어 있습니다."],["妹は歌が上手です。","いもうとは うたが じょうずです。","여동생은 노래를 잘합니다."]],"tag":"r5","cmp":[["～は","は는 이미 아는 화제, が는 새 정보·의문사 주어 (だれが来ましたか)"]],"qz":["だれ（　　）この絵をかきましたか。","が",["は","を","に"],"だれが この えを かきましたか。","누가 이 그림을 그렸어요?","의문사 だれ·何가 주어일 때는 が. だれは라고는 하지 않고, を·に는 주어를 나타내지 못해요."]},{"id":"b097","g":"part","lv":4,"p":"～から（부터·재료·이유）","m":"~부터·~에서 (시작) · ~로 (원료) · ~니까 (이유)","c":"시간·장소·사람 + から (시작점) / 원료 + から + 作る·できる / 보통형·정중형 + から (이유)","d":"시작점(九時から 9시부터, 駅から 역에서), 원료(牛乳から作る 우유로 만든다), 이유(寒いから 추우니까) 세 가지예요. 원료가 모양이 바뀌어 안 보이면 から, 재료가 그대로 보이면 で를 많이 써요(木で作る).","ex":[["チーズは牛乳から作ります。","チーズは ぎゅうにゅうから つくります。","치즈는 우유로 만듭니다."],["暑いから、窓を開けましょう。","あついから、まどを あけましょう。","더우니까 창문을 엽시다."]],"tag":"r5","cmp":[["～で（재료）","재료가 그대로 보이면 で(木でいすを作る), 모양이 바뀌면 から(牛乳からチーズを作る)"]],"qz":["家（　　）駅まで、歩いて十分です。","から",["に","で","を"],"いえから えきまで、あるいて じゅっぷんです。","집에서 역까지 걸어서 10분입니다.","～まで와 짝으로 시작점 '~에서'를 나타내는 것은 から. に는 도착점, で는 동작하는 곳, を는 대상이라 맞지 않아요."]},{"id":"b098","g":"part","lv":4,"p":"～だけ","m":"~만 · ~뿐","c":"명사·수량 + だけ / 동사 사전형 + だけ","d":"'그것 하나로 한정'한다는 뜻이에요. 뒤에 긍정·부정 둘 다 올 수 있어요. 비슷한 しか는 뒤에 반드시 부정이 와요(一つしか食べない 하나밖에 안 먹는다).","ex":[["少しだけ待ってください。","すこしだけ まって ください。","조금만 기다려 주세요."],["私だけ知りませんでした。","わたしだけ しりませんでした。","저만 몰랐습니다."]],"tag":"r5","cmp":[["～しか～ない","だけ는 긍정·부정 다 됨, しか는 반드시 부정 + '그것밖에 없다'는 아쉬움"]],"qz":["おなかがいっぱいなので、ケーキは一つ（　　）食べました。","だけ",["しか","も","でも"],"おなかが いっぱいなので、ケーキは ひとつだけ たべました。","배가 불러서 케이크는 하나만 먹었습니다.","긍정(食べました)과 쓰는 '~만'은 だけ. しか는 뒤에 반드시 부정이 오고, 一つも는 '하나도 ~않다'로 부정과 짝, でも는 '~라도'라 맞지 않아요."]},{"id":"b099","g":"part","lv":4,"p":"～で（수단·원인·범위）","m":"~로 (수단·도구) · ~로·~ 때문에 (원인) · ~에서 (범위)","c":"도구·교통·말 + で / 병·날씨·사고 + で (원인) / 장소·모임 + で + 一番 등 (범위)","d":"で는 뜻이 많아요. 수단(はしで 젓가락으로·日本語で 일본어로), 원인(風邪で 감기로), 범위(クラスで一番 반에서 제일), 그리고 동작하는 곳(図書館で 도서관에서)이에요. '있다'의 장소는 で가 아니라 に예요.","ex":[["風邪で学校を休みました。","かぜで がっこうを やすみました。","감기로 학교를 쉬었습니다."],["クラスで田中さんが一番背が高いです。","クラスで たなかさんが いちばん せが たかいです。","반에서 다나카 씨가 가장 키가 큽니다."]],"tag":"r5","cmp":[["～に（장소）","に = 있는 곳·도착점(部屋にいる), で = 동작하는 곳(部屋で寝る)"]],"qz":["日本人は、はし（　　）ごはんを食べます。","で",["に","を","が"],"にほんじんは、はしで ごはんを たべます。","일본 사람은 젓가락으로 밥을 먹습니다.","도구·수단 '~로'는 で. に는 있는 곳·도착점, を는 대상(ごはんを), が는 주어라 도구를 나타내지 못해요."]},{"id":"b100","g":"part","lv":4,"p":"～と（~와/과）","m":"~와/과 (나열) · ~와 (함께하는 상대)","c":"명사 + と + 명사 (나열) / 사람 + と + 동사 (상대)","d":"명사를 이어 '~와/과'예요. 나열하는 と는 '그게 전부'(りんごとみかん = 딱 둘)라는 뜻이고, 다른 것도 있으면 や를 써요. 사람 뒤에 붙으면 함께하거나 마주하는 상대예요(友だちと話す 친구와 이야기하다).","ex":[["パンと卵を買いました。","パンと たまごを かいました。","빵과 달걀을 샀습니다."],["昨日、母と電話で話しました。","きのう、ははと でんわで はなしました。","어제 어머니와 전화로 이야기했습니다."]],"tag":"r5","cmp":[["～や","と는 전부 나열, や는 몇 개만 예로 (など와 함께)"]],"qz":["昨日、友だち（　　）いっしょに公園で遊びました。","と",["や","に","を"],"きのう、ともだちと いっしょに こうえんで あそびました。","어제 친구와 함께 공원에서 놀았습니다.","いっしょに 앞에서 함께하는 상대 '~와'는 と. や는 몇 개를 예로 드는 나열이고, に·を는 함께하는 상대를 나타내지 못해요."]},{"id":"b101","g":"part","lv":4,"p":"～に","m":"~에 (때·있는 곳·가는 곳) · ~에게 (상대) · ~이/가 (되다)","c":"시간 + に / 장소 + に + ある·いる / 장소 + に + 行く·来る / 사람 + に + 동사 / 명사 + に + なる","d":"に는 딱 한 점을 가리켜요. 때(七時に), 있는 곳(部屋に), 도착점(学校に), 상대(友だちに), 변화의 결과(医者になる)를 나타내요. 会う·乗る는 한국어로 '~을'이지만 に를 써요(友だちに会う).","ex":[["駅の前に本屋があります。","えきの まえに ほんやが あります。","역 앞에 서점이 있습니다."],["友だちに手紙を書きました。","ともだちに てがみを かきました。","친구에게 편지를 썼습니다."]],"tag":"r5","cmp":[["～で","に = 있는 곳·도착점(公園にいる), で = 동작하는 곳(公園で遊ぶ)"]],"qz":["つくえの上（　　）ねこがいます。","に",["で","を","へ"],"つくえの うえに ねこが います。","책상 위에 고양이가 있습니다.","いる·ある의 '있는 곳'은 に. で는 동작하는 곳(上で寝る), を는 대상, へ는 가는 방향이라 います와 맞지 않아요."]},{"id":"b102","g":"part","lv":4,"p":"～は","m":"~은/는 (화제·대비)","c":"명사 + は (조사 は는 わ로 읽음)","d":"'이 문장은 ~에 대한 이야기'라고 화제를 정해요. 둘을 맞대어 비교할 때(대비)도 써요: 犬は好きですが、猫は～. 조사 は는 글자는 は지만 '와'로 읽어요.","ex":[["私の兄は高校生です。","わたしの あには こうこうせいです。","제 형은 고등학생입니다."],["犬は好きですが、猫は好きじゃありません。","いぬは すきですが、ねこは すきじゃ ありません。","개는 좋아하지만 고양이는 좋아하지 않습니다."]],"tag":"r5","cmp":[["～が","だれが·何が처럼 의문사가 주어일 때와 그 대답은 が, 이미 아는 화제는 は"]],"qz":["肉は食べますが、魚（　　）食べません。","は",["も","が","に"],"にくは たべますが、さかなは たべません。","고기는 먹지만 생선은 안 먹습니다.","둘을 맞대어 비교(대비)할 때 は. も는 '~도'라 앞의 '먹는다'와 어긋나고, が를 쓰면 '생선이 먹는다'가 되며, に는 대상을 나타내지 못해요."]},{"id":"b103","g":"part","lv":4,"p":"～も","m":"~도","c":"명사 + も (が·を 대신) / 명사 + に·で·と 등 + も (にも·でも)","d":"같은 것을 하나 더할 때 써요. が·を 자리에서는 も만 남기고(私が → 私も, 水を → 水も), に·で 등은 にも·でも처럼 뒤에 붙여요. 何も·だれも + 부정은 '아무것도·아무도 ~않다'예요.","ex":[["田中さんも日本人です。","たなかさんも にほんじんです。","다나카 씨도 일본인입니다."],["日曜日は図書館にも行きました。","にちようびは としょかんにも いきました。","일요일에는 도서관에도 갔습니다."]],"tag":"r5","qz":["兄も私（　　）、野球が大好きです。","も",["は","が","と"],"あにも わたしも、やきゅうが だいすきです。","형도 저도 야구를 아주 좋아합니다.","앞의 兄も와 짝으로 '~도 ~도'라고 하려면 も. は·が·と를 넣으면 兄も와 이어지지 않아요."]},{"id":"b104","g":"part","lv":4,"p":"～を（대상·지나가는 곳·떠나는 곳）","m":"~을/를 (대상) · ~을/를 (지나가는 곳) · ~에서 (떠나는 곳)","c":"명사 + を + 동사 / 장소 + を + 歩く·渡る·散歩する / 장소 + を + 出る·降りる","d":"기본은 동작의 대상 '~을/를'이에요. 歩く·渡る처럼 움직이는 동사 앞에서는 지나가는 곳(道を歩く 길을 걷다), 出る·降りる 앞에서는 떠나는 곳(家を出る 집을 나서다)이에요. バスを降りる는 한국어로 '버스에서 내리다'예요. を는 '오'로 읽어요.","ex":[["この道を歩いて駅へ行きます。","この みちを あるいて えきへ いきます。","이 길을 걸어서 역에 갑니다."],["七時に家を出ます。","しちじに いえを でます。","7시에 집을 나섭니다."]],"tag":"r5","qz":["その橋（　　）渡って、右に曲がってください。","を",["に","で","が"],"その はしを わたって、みぎに まがって ください。","그 다리를 건너서 오른쪽으로 도세요.","渡る·歩く처럼 지나가는 곳은 を. に는 도착점, で는 동작하는 곳, が는 주어라 渡る와 함께 쓰지 않아요."]},{"id":"b105","g":"part","lv":4,"p":"～まで","m":"~까지 (끝나는 때·곳)","c":"시간·장소 + まで / ～から～まで","d":"시간·거리의 끝을 나타내요. から(부터)와 짝으로 많이 써요: 九時から五時まで. 그때까지 쭉 계속되는 일에 쓰고, '그때까지 한 번 끝내는' 마감은 までに예요.","ex":[["駅まで歩きます。","えきまで あるきます。","역까지 걷습니다."],["夜十時まで勉強しました。","よる じゅうじまで べんきょうしました。","밤 10시까지 공부했습니다."]],"tag":"r5","cmp":[["～までに","まで는 '그때까지 계속'(五時まで待つ), までに는 '그때까지 한 번'(五時までに来る)"]],"qz":["月曜日から金曜日（　　）、毎日学校に行きます。","まで",["までに","に","と"],"げつようびから きんようびまで、まいにち がっこうに いきます。","월요일부터 금요일까지 매일 학교에 갑니다.","～から와 짝으로 끝나는 때까지 계속되는 일은 まで. までに는 '그때까지 한 번'(마감)이고, に·と는 から와 이어지지 않아요."]},{"id":"b106","g":"part","lv":4,"p":"～けれど（も）／～けど","m":"~지만 · ~는데 (말 꺼내기)","c":"보통형·정중형 + けれど(も)·けど","d":"が(~지만)와 같은 뜻이고 회화에서 많이 써요. 정중한 정도는 けれども > けれど > けど 순이에요. 부탁·질문 앞에 사정을 꺼낼 때 '~는데'로도 써요(聞きたいんですけど 묻고 싶은데요).","ex":[["この本は高いけれど、おもしろいです。","この ほんは たかいけれど、おもしろいです。","이 책은 비싸지만 재미있습니다."],["ちょっと聞きたいんですけど、いいですか。","ちょっと ききたいんですけど、いいですか。","좀 묻고 싶은데, 괜찮아요?"]],"cmp":[["～が","같은 '~지만'이지만 が는 정중·글, けど는 회화"]],"qz":["日本語は難しい（　　）、とてもおもしろいです。","けれど",["ので","から","と"],"にほんごは むずかしいけれど、とても おもしろいです。","일본어는 어렵지만 아주 재미있습니다.","앞뒤가 반대되는 '~지만'은 けれど. ので·から는 이유라 '어려워서 재미있다'가 되어 어긋나고, と는 '~하면'이라 뜻이 맞지 않아요."]},{"id":"b107","g":"part","lv":4,"p":"～し","m":"~하고 (게다가) · ~하니까 (이유 늘어놓기)","c":"보통형 + し (な형용사·명사는 ～だし)","d":"이유나 특징을 두세 개 늘어놓을 때 써요(安いし、おいしいし 싸고 맛있고). 이유를 하나만 말해도 '다른 이유도 있다'는 느낌이 들어요. な형용사·명사는 静かだし·雨だし처럼 だ를 붙여요.","ex":[["この町は静かだし、駅も近いです。","この まちは しずかだし、えきも ちかいです。","이 동네는 조용하고 역도 가깝습니다."],["今日は雨だし、家にいます。","きょうは あめだし、いえに います。","오늘은 비도 오고 하니 집에 있겠습니다."]],"cmp":[["～て","て는 단순히 잇기, し는 '게다가'처럼 이유·특징을 덧붙이기"]],"qz":["この部屋は広い（　　）、明るいし、とても気に入っています。","し",["けど","のに","ので"],"この へやは ひろいし、あかるいし、とても きに いって います。","이 방은 넓고 밝아서 정말 마음에 듭니다.","뒤의 明るいし와 나란히 좋은 점을 늘어놓는 것은 し. けど·のに는 앞뒤가 반대일 때, ので는 이유 하나를 말할 때라 明るいし와 이어지지 않아요."]},{"id":"b108","g":"part","lv":4,"p":"～しか～ない","m":"~밖에 ~않다 (~뿐)","c":"명사·수량 + しか + 부정 (～ない·～ません)","d":"뒤에 반드시 부정이 와요. 뜻은 '~만'이지만 '그것뿐이라 적다·아쉽다'는 느낌이 있어요. が·を 자리에는 しか만 쓰고(水しか飲まない), に·で 등은 にしか·でしか처럼 뒤에 붙여요.","ex":[["昨日は三時間しか寝ていません。","きのうは さんじかんしか ねて いません。","어제는 세 시간밖에 안 잤습니다."],["キムさんは野菜しか食べません。","キムさんは やさいしか たべません。","김 씨는 채소밖에 안 먹습니다."]],"cmp":[["～だけ","だけ는 긍정에도 씀, しか는 반드시 부정 + '적다'는 느낌"]],"qz":["さいふの中に百円（　　）ありません。ジュースも買えません。","しか",["だけ","ばかり","まで"],"さいふの なかに ひゃくえんしか ありません。ジュースも かえません。","지갑 안에 100엔밖에 없습니다. 주스도 못 삽니다.","부정(ありません)과 짝으로 '~밖에 없다'는 しか. だけ를 넣으면 '100엔만 없다'가 되어 뜻이 바뀌고, ばかり·まで도 맞지 않아요."]},{"id":"b109","g":"part","lv":4,"p":"～でも","m":"~라도 (가볍게 권함) · ~라도 (극단적 예) · 의문사 + でも (~든지)","c":"명사 + でも / 의문사 + でも (何でも·だれでも·いつでも)","d":"① お茶でも飲みませんか처럼 '그런 것이라도' 하고 가볍게 권해요(꼭 차가 아니어도 됨). ② 子どもでも分かる처럼 극단적인 예를 들어 '다른 사람은 물론'이라는 뜻이에요. ③ 의문사 + でも는 '~든지'예요. 문장 앞의 でも(하지만)와는 다른 말이에요.","ex":[["日曜日に映画でも見ませんか。","にちようびに えいがでも みませんか。","일요일에 영화라도 보지 않을래요?"],["この問題は子どもでも分かります。","この もんだいは こどもでも わかります。","이 문제는 아이라도 압니다."]],"qz":["のどがかわきましたね。お茶（　　）飲みませんか。","でも",["が","に","と"],"のどが かわきましたね。おちゃでも のみませんか。","목이 마르네요. 차라도 마시지 않을래요?","'~라도 하지 않을래요?' 하고 가볍게 권할 때 でも. が·に·と는 飲む의 대상을 나타내지 못해요."]},{"id":"b110","g":"part","lv":4,"p":"～と／～って（~라고）","m":"~라고 (말·생각의 내용) · ~래·~대 (전해 들은 말)","c":"「말」·보통형 + と + 言う·思う·聞く / 회화: 보통형 + って","d":"남의 말이나 내 생각을 옮길 때 と를 써요: 「はい」と言いました. 회화에서는 と 대신 って를 많이 쓰고, 문장 끝에 って만 붙이면 '~래·~대'처럼 전해 들은 말이 돼요(来ないって 안 온대).","ex":[["先生は「明日はテストです」と言いました。","せんせいは「あしたは テストです」と いいました。","선생님은 \"내일은 시험입니다\"라고 말했습니다."],["田中さんは今日来られないって。","たなかさんは きょう こられないって。","다나카 씨는 오늘 못 온대."]],"cmp":[["～という","という는 '~라는 (이름·내용)'(さくらという歌)"]],"qz":["明日はきっと晴れる（　　）思います。","と",["を","に","が"],"あしたは きっと はれると おもいます。","내일은 분명 맑을 거라고 생각합니다.","생각의 내용 '~라고'는 と思う. を·に·が는 思う 앞에서 생각의 내용을 나타내지 못해요."]},{"id":"b111","g":"part","lv":4,"p":"～ので","m":"~이기 때문에 · ~라서","c":"보통형 + ので (な형용사·명사는 ～なので) / 정중하게 ～ますので·～ですので","d":"から와 같은 이유지만, 객관적인 사정처럼 들려 부드럽고 정중해요. 그래서 윗사람에게 사정을 말하거나 양해를 구할 때 많이 써요. 명사·な형용사는 雨なので처럼 な를 붙여요(雨だので ✕).","ex":[["道がこんでいたので、遅れました。","みちが こんで いたので、おくれました。","길이 막혀서 늦었습니다."],["明日は休みなので、ゆっくり寝ます。","あしたは やすみなので、ゆっくり ねます。","내일은 쉬는 날이라서 푹 자겠습니다."]],"cmp":[["～から","から는 내 판단을 분명히(명령·의지와 잘 어울림), ので는 사정 설명으로 부드럽게"]],"qz":["明日はテスト（　　）、今日は早く寝ます。","なので",["ので","だので","なのに"],"あしたは テストなので、きょうは はやく ねます。","내일은 시험이라서 오늘은 일찍 자겠습니다.","명사 뒤에 ので를 붙일 때는 な를 넣어 なので. テストので·テストだので는 틀린 꼴이고, なのに는 '~인데도'라 뜻이 맞지 않아요."]},{"id":"b112","g":"part","lv":4,"p":"～のに","m":"~인데도 · ~했는데 (불만·뜻밖)","c":"보통형 + のに (な형용사·명사는 ～なのに)","d":"앞의 일로 보면 당연히 그래야 하는데 결과가 달라서, 불만·실망·놀람이 담긴 말이에요. 뒤에 내 의지·부탁·명령은 오지 않아요. 단순히 '~지만'이라고 할 때는 けど·が를 써요.","ex":[["たくさん勉強したのに、テストはだめでした。","たくさん べんきょうしたのに、テストは だめでした。","많이 공부했는데도 시험은 망쳤습니다."],["日曜日なのに、父は会社へ行きました。","にちようびなのに、ちちは かいしゃへ いきました。","일요일인데도 아버지는 회사에 가셨습니다."]],"cmp":[["～けど","けど는 단순히 '~지만', のに는 '~인데도'라는 불만·아쉬움이 담김"]],"qz":["約束の時間を三十分も過ぎた（　　）、友だちはまだ来ません。","のに",["ので","から","と"],"やくそくの じかんを さんじゅっぷんも すぎたのに、ともだちは まだ きません。","약속 시간이 30분이나 지났는데도 친구는 아직 안 옵니다.","당연히 와야 하는데 안 오는 불만은 のに. ので·から는 이유라 '지나서 안 온다'가 되어 어긋나고, と는 과거형(過ぎた) 뒤에 붙지 않아요."]},{"id":"b113","g":"part","lv":4,"p":"～ばかり","m":"~만 (자꾸·그것만 잔뜩)","c":"명사 + ばかり / 동사 て형 + ばかりいる","d":"'그것만 잔뜩·자꾸'라는 뜻으로, 대개 불만이 담겨요. 동사는 て형 + ばかりいる로 '~하기만 한다'예요(寝てばかりいる 잠만 잔다). た형 + ばかり(막 ~했다)는 뜻이 달라서 따로 익혀요.","ex":[["兄はまんがばかり読んでいます。","あには まんがばかり よんで います。","형은 만화만 읽고 있습니다."],["弟は遊んでばかりいます。","おとうとは あそんで ばかり います。","남동생은 놀기만 합니다."]],"cmp":[["～だけ","だけ는 단순한 한정 '~만', ばかり는 '그것만 많이·자꾸'(불만)"]],"qz":["兄は休みの日、ずっと寝て（　　）います。","ばかり",["しか","から","まで"],"あには やすみの ひ、ずっと ねて ばかり います。","형은 쉬는 날에 계속 잠만 잡니다.","て형 + ばかりいる로 '~하기만 한다'(불만). しか는 뒤에 부정이 와야 하고, から·まで는 寝て와 います 사이에 들어가지 못해요."]},{"id":"b114","g":"part","lv":4,"p":"～までに","m":"~까지 (기한·마감)","c":"시간·때 + までに / 동사 사전형 + までに","d":"그때가 오기 전에 한 번 끝내야 하는 일(마감)에 써요. まで는 '그때까지 쭉 계속'이라 뜻이 달라요: 五時まで待つ(5시까지 계속 기다림) / 五時までに帰る(5시 전에 돌아옴).","ex":[["六時までに家に帰ります。","ろくじまでに いえに かえります。","6시까지 집에 돌아갑니다."],["母が帰るまでに、部屋をそうじします。","ははが かえるまでに、へやを そうじします。","어머니가 돌아오시기 전까지 방을 청소합니다."]],"cmp":[["～まで","まで = 그때까지 계속(待つ·いる·働く), までに = 그때까지 한 번(出す·帰る·終わる)"]],"qz":["この本は、来週の金曜日（　　）返してください。","までに",["まで","から","で"],"この ほんは、らいしゅうの きんようびまでに かえして ください。","이 책은 다음 주 금요일까지 돌려주세요.","그때까지 한 번 끝내는 마감(返す)은 までに. まで는 '그때까지 계속'(待つ·いる)이라 返す와 맞지 않고, から·で도 기한을 나타내지 못해요."]},{"id":"b115","g":"part","lv":4,"p":"～も（수량 + も）","m":"~이나 (많다는 느낌) · (一 + 수량 + も + 부정) 하나도 ~않다","c":"수량 + も / 一つ·一人·一度 + も + 부정","d":"수량 뒤에 붙어 '생각보다 많다'는 놀람을 나타내요(三時間も待った 세 시간이나 기다렸다). '1 + 수량 + も' 뒤에 부정이 오면 '하나도 ~않다'예요(一度も 한 번도).","ex":[["ケーキを五つも食べました。","ケーキを いつつも たべました。","케이크를 다섯 개나 먹었습니다."],["日本へは一度も行ったことがありません。","にほんへは いちども いった ことが ありません。","일본에는 한 번도 가 본 적이 없습니다."]],"cmp":[["수량 + しか～ない","しか는 '~밖에'(적다는 느낌), も는 '~이나'(많다는 느낌)"]],"qz":["バスが来なくて、一時間（　　）待ちました。","も",["しか","に","を"],"バスが こなくて、いちじかんも まちました。","버스가 오지 않아서 한 시간이나 기다렸습니다.","수량 뒤에서 '~이나'(많다는 놀람)는 も. しか는 뒤에 부정이 와야 하고, に·を는 기다린 시간의 길이 뒤에 붙지 않아요."]},{"id":"b116","g":"form","lv":4,"p":"가능형 ～(ら)れる","m":"~할 수 있다","c":"1그룹 う단→え단 + る (書く→書ける·読む→読める) / 2그룹 る→られる (食べる→食べられる·見る→見られる) / 3그룹 する→できる·来る→来られる(こられる)","d":"능력이나 '그럴 수 있는 형편'을 나타내요. 목적어는 を보다 が를 많이 써요(漢字が読める). 2그룹은 회화에서 食べれる·見れる(来る도 来れる)처럼 ら를 빼기도 하지만 시험 정답은 られる예요. 가능형은 2그룹처럼 바뀌어요(読める→読めない·読めます).","ex":[["私は自転車に乗れます。","わたしは じてんしゃに のれます。","저는 자전거를 탈 수 있습니다."],["この魚は生で食べられます。","この さかなは なまで たべられます。","이 생선은 날것으로 먹을 수 있습니다."]],"cmp":[["～ことができる","뜻은 같아요. 가능형이 짧은 회화체, ことができる는 조금 딱딱해서 안내문·설명문에 많음"],["見える／聞こえる","見える·聞こえる는 저절로 보이고 들림, 見られる·聞ける는 볼·들을 기회나 능력이 있음"]],"qz":["兄は英語の新聞が（　　）。すごいですね。","読めます",["読まれます","読ませます","読みましょう"],"あには えいごの しんぶんが よめます。すごいですね。","형은 영어 신문을 읽을 수 있어요. 대단하네요.","'읽을 수 있다'는 능력이라 가능형 読めます. 読まれます는 수동(읽히다), 読ませます는 사역(읽게 하다), 読みましょう는 권유라 뜻이 안 맞아요."]},{"id":"b117","g":"form","lv":4,"p":"～ことができる","m":"~할 수 있다","c":"동사 사전형 + ことができる / 명사 + ができる","d":"'~하는 것이 가능하다'라는 말 그대로예요. 가능형보다 조금 딱딱해서 안내문·규칙 설명에 많이 써요. 명사에는 바로 붙여요(日本語ができる 일본어를 할 수 있다).","ex":[["この図書館では本を五冊まで借りることができます。","この としょかんでは ほんを ごさつまで かりる ことが できます。","이 도서관에서는 책을 다섯 권까지 빌릴 수 있습니다."],["ここで切符を買うことができますか。","ここで きっぷを かう ことが できますか。","여기서 표를 살 수 있습니까?"]],"cmp":[["가능형 ～(ら)れる","뜻은 같고 가능형이 더 짧음: 泳ぐことができる = 泳げる"]],"qz":["名前を書けば、だれでもこのパソコンを使う（　　）。","ことができます",["ができます","ことがなります","ことをします"],"なまえを かけば、だれでも この パソコンを つかう ことが できます。","이름을 쓰면 누구나 이 컴퓨터를 쓸 수 있습니다.","동사 사전형 뒤에는 ことができます. ができます는 명사 뒤(日本語ができる)에만 바로 붙고, ことがなります·ことをします는 틀린 말이에요."]},{"id":"b118","g":"form","lv":4,"p":"의지형 ～(よ)う／～(よ)うか","m":"~하자 · ~할까? (보통체)","c":"1그룹 う단→お단 + う (行く→行こう·読む→読もう) / 2그룹 る→よう (食べる→食べよう) / 3그룹 する→しよう·来る→来よう(こよう)","d":"ましょう(~합시다)의 보통체예요. 친구·가족에게 '~하자'라고 권하거나, 혼잣말로 '~해야지'라고 마음먹을 때 써요. 끝에 か를 붙이면 ましょうか처럼 '~할까?'가 돼요.","ex":[["そろそろ帰ろう。","そろそろ かえろう。","슬슬 돌아가자."],["いっしょに昼ごはんを食べようか。","いっしょに ひるごはんを たべようか。","같이 점심 먹을까?"]],"cmp":[["～ましょう／～ましょうか","뜻은 같고 정중체: 行こう = 行きましょう, 行こうか = 行きましょうか"]],"qz":["おなかがすいたね。いっしょにパンを（　　）か。","食べよう",["食べろ","食べて","食べれば"],"おなかが すいたね。いっしょに パンを たべようか。","배고프다. 같이 빵 먹을까?","'~할까?'하고 권하는 보통체는 의지형 + か(食べようか). 명령형 食べろ, て형 食べて, 食べれば 뒤에는 か를 붙여 권할 수 없어요."]},{"id":"b119","g":"form","lv":4,"p":"명령형 (行け·食べろ·来い·しろ)","m":"~해라 (강한 명령)","c":"1그룹 う단→え단 (行く→行け·書く→書け) / 2그룹 る→ろ (食べる→食べろ·見る→見ろ) / 3그룹 する→しろ·来る→来い(こい)","d":"아주 강하고 거친 명령이라 일상 대화에서는 거의 쓰지 않고, 응원(がんばれ)·표지판(止まれ)·급한 외침에 나와요. 부드럽게 시킬 때는 ～てください나 ～なさい를 써요. '~하지 마'는 사전형 + な(行くな)예요.","ex":[["がんばれ、もう少しだ！","がんばれ、もう すこしだ！","힘내, 조금만 더야!"],["早く起きろ。学校におくれるよ。","はやく おきろ。がっこうに おくれるよ。","빨리 일어나. 학교에 늦겠어."]],"cmp":[["～なさい","なさい는 부모·선생님이 아이에게 하는 부드러운 명령, 명령형은 거칠고 강함"]],"qz":["犬に「こっちへ（　　）！」と言うと、すぐ走ってきました。","来い",["来ろ","来れ","来た"],"いぬに「こっちへ こい！」と いうと、すぐ はしって きました。","개에게 \"이리 와!\"라고 하자 바로 달려왔습니다.","来る의 명령형은 来い(こい). 来ろ는 2그룹처럼, 来れ는 1그룹처럼 잘못 바꾼 꼴이고, 来た는 '왔다'라 명령이 되지 않아요."]},{"id":"b120","g":"form","lv":4,"p":"수동형 ～(ら)れる","m":"~당하다 · ~받다 · ~되다","c":"1그룹 う단→あ단 + れる (書く→書かれる, う→わ: 言う→言われる) / 2그룹 る→られる (食べる→食べられる·ほめる→ほめられる) / 3그룹 する→される·来る→来られる(こられる)","d":"행동을 한 사람은 に로 나타내요(先生にほめられた). 일본어는 피해를 입었다는 느낌으로 남의 행동이나 자연 현상도 수동으로 말해요(雨に降られた 비를 맞았다). 2그룹·来る는 가능형과 모양이 같아 문맥으로 구별해요.","ex":[["宿題を忘れて、先生にしかられました。","しゅくだいを わすれて、せんせいに しかられました。","숙제를 잊어서 선생님께 꾸중을 들었습니다."],["弟に私のケーキを食べられました。","おとうとに わたしの ケーキを たべられました。","남동생이 제 케이크를 먹어 버렸습니다."]],"cmp":[["가능형 ～(ら)れる","2그룹·来る는 모양이 같음(食べられる). 1그룹은 다름: 書かれる(수동) / 書ける(가능)"]],"qz":["電車の中で、知らない人に足を（　　）。痛かったです。","ふまれました",["ふみました","ふめました","ふみましょう"],"でんしゃの なかで、しらない ひとに あしを ふまれました。いたかったです。","전철 안에서 모르는 사람이 제 발을 밟았습니다. 아팠어요.","남(知らない人に)이 한 행동을 내가 당했으니 수동 ふまれました. ふみました는 내가 밟음, ふめました는 가능, ふみましょう는 권유예요."]},{"id":"b121","g":"form","lv":4,"p":"사역형 ～(さ)せる","m":"~시키다 · ~하게 하다 · ~하게 두다","c":"1그룹 う단→あ단 + せる (行く→行かせる, う→わ: 買う→買わせる) / 2그룹 る→させる (食べる→食べさせる) / 3그룹 する→させる·来る→来させる(こさせる)","d":"시키는 사람은 は·が, 실제로 하는 사람은 に나 を로 나타내요. 목적어(を)가 따로 있으면 に(母は弟に野菜を食べさせた), 없으면 を도 써요(子どもを遊ばせる). 억지로 시키는 뜻뿐 아니라, 하고 싶은 대로 '하게 두다(허락)'라는 뜻도 있어요.","ex":[["先生は学生に作文を書かせました。","せんせいは がくせいに さくぶんを かかせました。","선생님은 학생에게 작문을 쓰게 했습니다."],["子どもを公園で自由に遊ばせました。","こどもを こうえんで じゆうに あそばせました。","아이를 공원에서 마음껏 놀게 했습니다."]],"cmp":[["사역수동 ～(さ)せられる","사역은 시키는 쪽이 주어, 사역수동은 억지로 하게 된 쪽이 주어"]],"qz":["母は弟に、毎日一時間ピアノを（　　）。","練習させます",["練習します","練習できます","練習しましょう"],"ははは おとうとに、まいにち いちじかん ピアノを れんしゅうさせます。","어머니는 남동생에게 매일 한 시간 피아노를 연습시킵니다.","엄마(は)가 동생(に)에게 시키는 일이라 사역 練習させます. 練習します·できます·しましょう는 엄마가 직접 하는 말이 되어 弟に와 맞지 않아요."]},{"id":"b122","g":"form","lv":4,"p":"～(さ)せてください","m":"(제가) ~하게 해 주세요","c":"동사 사역형의 て형 + ください (休む→休ませてください·帰る→帰らせてください·する→させてください)","d":"내가 하고 싶은 일을 '하게 허락해 달라'고 부탁하는 말이에요. 하는 사람은 '나'예요. '그 일은 제가 할게요'라고 자진해서 나설 때도 써요.","ex":[["頭が痛いので、早く帰らせてください。","あたまが いたいので、はやく かえらせて ください。","머리가 아파서 일찍 돌아가게 해 주세요."],["その仕事は私にさせてください。","その しごとは わたしに させて ください。","그 일은 제가 하게 해 주세요."]],"cmp":[["～てください","てください는 상대가 하기를 부탁, させてください는 내가 하는 것을 허락해 달라는 부탁"]],"qz":["私はとてもつかれました。少し（　　）。","休ませてください",["休んでください","休ませられてください","休むください"],"わたしは とても つかれました。すこし やすませて ください。","저는 너무 지쳤어요. 잠깐 쉬게 해 주세요.","지친 사람이 '나'라서 내가 쉬도록 허락을 구하는 休ませてください. 休んでください는 상대에게 쉬라는 말이고, 나머지 둘은 틀린 꼴이에요."]},{"id":"b123","g":"form","lv":4,"p":"사역수동 ～(さ)せられる","m":"(억지로) ~하게 되다 · 어쩔 수 없이 ~하다","c":"1그룹 う단→あ단 + せられる (待つ→待たせられる) · 줄인 꼴 あ단 + される (待たされる, す로 끝나는 동사는 줄이지 않음: 話させられる) / 2그룹 る→させられる (食べさせられる) / 3그룹 する→させられる·来る→来させられる(こさせられる)","d":"남이 시켜서 하기 싫은 일을 억지로 했다는 뜻이에요. 시킨 사람은 に로 나타내요(母に野菜を食べさせられた). 1그룹은 회화에서 줄인 꼴(待たされる·飲まされる)을 더 많이 써요.","ex":[["駅で一時間も待たされました。","えきで いちじかんも またされました。","역에서 한 시간이나 기다려야 했습니다."],["子どものころ、母に野菜を食べさせられました。","こどもの ころ、ははに やさいを たべさせられました。","어릴 때 어머니가 시켜서 억지로 채소를 먹었습니다."]],"cmp":[["수동 ～(ら)れる","수동은 남의 행동을 내가 당함(しかられた), 사역수동은 시켜서 내가 억지로 행동함(待たされた)"]],"qz":["歌いたくなかったのに、先生にみんなの前で（　　）。","歌わせられました",["歌わせました","歌われました","歌えました"],"うたいたく なかったのに、せんせいに みんなの まえで うたわせられました。","노래하고 싶지 않았는데, 선생님이 시켜서 모두 앞에서 노래해야 했습니다.","하기 싫은데 선생님(に)이 시켜서 내가 억지로 했으니 사역수동 歌わせられました. 歌わせました는 내가 시킴, 歌われました는 수동, 歌えました는 가능이에요."]},{"id":"b124","g":"time","lv":4,"p":"～てから","m":"~하고 나서 · ~한 지 (얼마)","c":"동사 て형 + から","d":"앞의 일을 먼저 끝내고 뒤의 일을 한다는 순서를 분명히 해요. '~한 지 (기간)이 되다'처럼 그때부터 시간이 흘렀다는 말에도 써요(日本に来てから一年になる).","ex":[["宿題をしてから、遊びに行きます。","しゅくだいを してから、あそびに いきます。","숙제를 하고 나서 놀러 갑니다."],["日本に来てから、一年になります。","にほんに きてから、いちねんに なります。","일본에 온 지 1년이 됩니다."]],"tag":"r5","cmp":[["～たあとで","뜻이 거의 같음. '~한 지 (기간)'은 てから만 가능"],["～から（이유）","이유의 から는 보통형 뒤(行くから), 순서의 てから는 て형 뒤(行ってから)"]],"qz":["弟が生まれ（　　）、もう二年になります。","てから",["たあとで","る前に","ながら"],"おとうとが うまれてから、もう にねんに なります。","남동생이 태어난 지 벌써 2년이 됩니다.","'~한 지 (기간)이 되다'는 てから만 써요. たあとで는 이 뜻으로 쓰지 않고, る前に(~하기 전에)·ながら(~하면서)는 뜻이 맞지 않아요."]},{"id":"b125","g":"time","lv":4,"p":"～たあとで","m":"~한 후에","c":"동사 た형 + あとで / 명사 + の + あとで","d":"앞의 일이 끝난 다음에 뒤의 일이 있다는 뜻이에요. 한자로 後で라고도 쓰고, で를 빼고 ～たあと、～라고도 해요. 한국어 '먹은 후'처럼 앞 동사는 꼭 た형이에요(食べるあとで ✕).","ex":[["ごはんを食べたあとで、薬を飲みます。","ごはんを たべた あとで、くすりを のみます。","밥을 먹은 후에 약을 먹습니다."],["授業のあとで、先生に質問しました。","じゅぎょうの あとで、せんせいに しつもんしました。","수업 후에 선생님께 질문했습니다."]],"tag":"r5","cmp":[["～てから","뜻이 거의 같음. 명사에는 あとで만 붙음(授業のあとで ○)"]],"qz":["授業が（　　）あとで、友だちとサッカーをします。","終わった",["終わる","終わって","終わらない"],"じゅぎょうが おわった あとで、ともだちと サッカーを します。","수업이 끝난 후에 친구와 축구를 합니다.","あとで 앞의 동사는 꼭 た형(終わった). 사전형 終わる, て형 終わって, ない형 終わらない는 あとで 앞에 올 수 없어요."]},{"id":"b126","g":"time","lv":4,"p":"～前に","m":"~하기 전에 · ~ 전에","c":"동사 사전형 + 前に / 명사 + の + 前に / 기간 + 前に (三年前に)","d":"앞 동사는 언제나 사전형이에요. 이미 지난 일을 말할 때도 寝る前に처럼 사전형을 써요(寝た前に ✕). 三年前(3년 전)처럼 기간 뒤에는 の 없이 붙어요.","ex":[["出かける前に、窓を閉めてください。","でかける まえに、まどを しめて ください。","나가기 전에 창문을 닫아 주세요."],["食事の前に、手を洗いましょう。","しょくじの まえに、てを あらいましょう。","식사 전에 손을 씻읍시다."]],"tag":"r5","cmp":[["～までに","前に는 '어떤 일보다 먼저', までに는 '정해진 때를 넘기지 않게(기한)'"]],"qz":["夜、ベッドに（　　）前に、歯をみがきます。","入る",["入った","入って","入ろう"],"よる、ベッドに はいる まえに、はを みがきます。","밤에 침대에 들어가기 전에 이를 닦습니다.","前に 앞의 동사는 언제나 사전형(入る). 入った前に·入って前に·入ろう前に는 모두 틀린 꼴이에요."]},{"id":"b127","g":"time","lv":4,"p":"～とき","m":"~할 때 · ~했을 때","c":"동사 보통형 + とき / い형용사 ～い + とき / な형용사 ～な + とき / 명사 + の + とき","d":"앞 동사가 사전형이면 '그 일을 하기 전·하는 중', た형이면 '그 일을 마친 뒤'예요. 家を出るとき(집을 나설 때, 나가기 전) / 家に帰ったとき(집에 돌아왔을 때, 도착한 뒤). 시험에 자주 나와요.","ex":[["家を出るとき、「行ってきます」と言います。","いえを でる とき、「いってきます」と いいます。","집을 나설 때 '다녀오겠습니다'라고 말합니다."],["家に帰ったとき、「ただいま」と言います。","いえに かえった とき、「ただいま」と いいます。","집에 돌아왔을 때 '다녀왔습니다'라고 말합니다."]],"tag":"r5","qz":["日本へ（　　）とき、東京のおばさんの家にとまりました。","行った",["行く","行って","行こう"],"にほんへ いった とき、とうきょうの おばさんの いえに とまりました。","일본에 갔을 때 도쿄의 이모 댁에서 묵었습니다.","일본에 간 뒤 도쿄에서 묵었으니 た형 行ったとき. 行くとき는 '가기 전·가는 중'이 되어 맞지 않고, 行って·行こう는 とき 앞에 못 와요."]},{"id":"b128","g":"time","lv":4,"p":"～ながら","m":"~하면서 (동시에)","c":"동사 ます형(ます 뺀 꼴) + ながら","d":"한 사람이 두 동작을 동시에 할 때 써요. 중심이 되는 동작이 뒤에 와요(音楽を聞きながら勉強する — 공부가 중심). 두 사람이 각각 하는 일에는 쓰지 않아요.","ex":[["テレビを見ながら、ごはんを食べます。","テレビを みながら、ごはんを たべます。","텔레비전을 보면서 밥을 먹습니다."],["歩きながら電話をしないでください。","あるきながら でんわを しないで ください。","걸으면서 전화하지 마세요."]],"tag":"r5","cmp":[["～あいだに","ながら는 같은 사람의 동시 동작, 間に는 주어가 달라도 됨(母が寝ている間に)"]],"qz":["弟はいつも音楽を（　　）ながら、宿題をしています。","聞き",["聞いて","聞く","聞いた"],"おとうとは いつも おんがくを ききながら、しゅくだいを して います。","남동생은 늘 음악을 들으면서 숙제를 합니다.","ながら 앞은 ます형에서 ます를 뺀 꼴(聞き). 聞いて·聞く·聞いた에는 ながら가 붙지 않아요."]},{"id":"b129","g":"time","lv":4,"p":"～あいだ／～あいだに","m":"~하는 동안 (내내) / ~하는 동안에 (어느 때)","c":"동사 사전형·ている형 + 間(に) / い형용사 ～い + 間(に) / な형용사 ～な + 間(に) / 명사 + の + 間(に)","d":"間는 그 기간 내내 뒤의 일이 계속될 때, 間に는 그 기간 안에 뒤의 일이 한 번 일어날 때 써요. 뒤의 일이 '계속'인지 '한 번'인지로 고르면 돼요.","ex":[["夏休みの間、ずっとおばあさんの家にいました。","なつやすみの あいだ、ずっと おばあさんの いえに いました。","여름방학 동안 내내 할머니 댁에 있었습니다."],["母が買い物をしている間に、部屋をそうじしました。","ははが かいものを して いる あいだに、へやを そうじしました。","어머니가 장을 보는 동안에 방을 청소했습니다."]],"cmp":[["～ながら","ながら는 같은 사람이 두 동작을 동시에, 間(に)는 다른 사람의 일이어도 됨"]],"qz":["弟が昼寝をしている（　　）、私はずっと本を読んでいました。","間",["間に","ながら","前に"],"おとうとが ひるねを して いる あいだ、わたしは ずっと ほんを よんで いました。","남동생이 낮잠을 자는 동안 나는 내내 책을 읽고 있었습니다.","ずっと(내내) 계속된 일이라 間. 間に는 그동안 한 번 일어난 일, ながら는 같은 사람의 동시 동작에 쓰고, 前に는 ている 뒤에 못 와요."]},{"id":"b130","g":"time","lv":4,"p":"～中（ちゅう／じゅう）","m":"~ 중 (ちゅう) · ~ 내내, 온 ~ (じゅう)","c":"명사 + 中 (授業中·電話中·午前中 → ちゅう / 一日中·世界中 → じゅう)","d":"ちゅう는 '~하는 중'(会議中·食事中)이나 '그 기간 안에'(午前中 오전 중에)라는 뜻이고, じゅう는 '~ 내내·~ 전체'(一日中 하루 종일·世界中 온 세계)라는 뜻이에요. 한자는 같아도 읽기와 뜻이 달라서 시험에 잘 나와요.","ex":[["父は今、会議中です。","ちちは いま、かいぎちゅうです。","아버지는 지금 회의 중입니다."],["昨日は一日中雨でした。","きのうは いちにちじゅう あめでした。","어제는 하루 종일 비가 왔습니다."]],"qz":["授業（　　）は、となりの人と話してはいけません。","中",["あいだ","まま","ところ"],"じゅぎょうちゅうは、となりの ひとと はなしては いけません。","수업 중에는 옆 사람과 이야기하면 안 됩니다.","명사에 바로 붙어 '~하는 중'을 나타내는 것은 中(ちゅう). あいだ는 授業のあいだ처럼 の가 필요하고, まま·ところ도 명사에 바로 붙지 않아요."]},{"id":"b131","g":"time","lv":4,"p":"～途中で","m":"~하는 도중에 · ~ 가는 길에","c":"동사 사전형 + 途中で / 명사 + の + 途中で","d":"어떤 일이 끝나기 전, 또는 어딘가로 가는 길 위에서 다른 일이 생겼을 때 써요. 学校へ行く途中で(학교 가는 길에)처럼 이동하는 장면에 특히 많이 써요.","ex":[["学校へ行く途中で、田中さんに会いました。","がっこうへ いく とちゅうで、たなかさんに あいました。","학교에 가는 길에 다나카 씨를 만났습니다."],["映画の途中で、寝てしまいました。","えいがの とちゅうで、ねて しまいました。","영화 도중에 잠들어 버렸습니다."]],"qz":["学校から帰る（　　）、雨が降り出しました。","途中で",["ながら","まま","あとで"],"がっこうから かえる とちゅうで、あめが ふりだしました。","학교에서 돌아오는 길에 비가 내리기 시작했습니다.","돌아오는 길 위에서 일이 생겼으니 途中で. ながら는 ます형 뒤에 붙는 같은 사람의 동시 동작이고, まま·あとで는 た형 뒤에 붙어요."]},{"id":"b132","g":"time","lv":4,"p":"～ところだ（하려는 참）","m":"막 ~하려는 참이다","c":"동사 사전형 + ところだ","d":"어떤 일을 하기 바로 직전이라는 뜻이에요. 今から·これから와 잘 어울려요. 여기서 ところ는 장소가 아니라 '시점'을 나타내요.","ex":[["今から家を出るところです。","いまから いえを でる ところです。","지금 막 집을 나서려는 참입니다."],["これから晩ごはんを作るところです。","これから ばんごはんを つくる ところです。","이제 막 저녁밥을 만들려는 참입니다."]],"cmp":[["～ているところだ／～たところだ","사전형 + ところ는 시작 직전, ている + ところ는 한창 하는 중, た형 + ところ는 막 끝남"]],"qz":["晩ごはんはまだです。今から（　　）ところです。","食べる",["食べた","食べている","食べて"],"ばんごはんは まだです。いまから たべる ところです。","저녁밥은 아직이에요. 이제 막 먹으려는 참이에요.","まだ·今から가 있으니 하기 바로 전, 사전형 食べるところ. 食べた는 막 끝남, 食べている는 한창 하는 중이라 맞지 않고, 食べて는 ところ 앞에 못 와요."]},{"id":"b133","g":"time","lv":4,"p":"～ているところだ","m":"한창 ~하는 중이다","c":"동사 て형 + いるところだ","d":"바로 지금 그 동작을 하고 있는 중이라는 것을 강조해요. ～ている보다 '지금 한창'이라는 느낌이 강해요. 전화 등에서 '지금 ~하는 중이라서'라고 사정을 말할 때 자주 써요.","ex":[["今、宿題をしているところです。","いま、しゅくだいを して いる ところです。","지금 한창 숙제를 하고 있는 중입니다."],["今、ごはんを食べているところなので、あとで電話します。","いま、ごはんを たべて いる ところなので、あとで でんわします。","지금 밥을 먹고 있는 중이라서 나중에 전화하겠습니다."]],"cmp":[["～ている","ている는 상태(結婚している)도 나타내지만, ているところ는 지금 진행 중인 동작에만 씀"]],"qz":["今、この本を（　　）ところです。もう半分ぐらい読みました。","読んでいる",["読む","読んだ","読める"],"いま、この ほんを よんで いる ところです。もう はんぶんぐらい よみました。","지금 이 책을 한창 읽는 중이에요. 벌써 반쯤 읽었어요.","반쯤 읽었고 아직 다 읽지 않았으니 한창 하는 중, 読んでいるところ. 読む는 시작 직전, 読んだ는 막 끝남이라 '반쯤'과 맞지 않아요."]},{"id":"b134","g":"time","lv":4,"p":"～たところだ","m":"막 ~했다 (방금 끝남)","c":"동사 た형 + ところだ","d":"어떤 일이 바로 방금 끝났다는 뜻이에요. 今·ちょうど와 잘 어울려요. 시간이 꽤 지난 일에는 쓰지 않아요.","ex":[["今、駅に着いたところです。","いま、えきに ついた ところです。","지금 막 역에 도착했습니다."],["ちょうど仕事が終わったところです。","ちょうど しごとが おわった ところです。","마침 막 일이 끝났습니다."]],"cmp":[["～たばかり","たところ는 '방금 막 끝난 순간', たばかり는 시간이 좀 지났어도 말하는 사람이 '얼마 안 됐다'고 느끼면 씀(先月来たばかり)"]],"qz":["「宿題、もう終わった？」「うん、ちょうど今（　　）ところだよ。」","終わった",["終わる","終わっている","終わろう"],"「しゅくだい、もう おわった？」「うん、ちょうど いま おわった ところだよ。」","\"숙제 벌써 끝났어?\" \"응, 방금 막 끝났어.\"","'끝났어?'에 うん이라고 했으니 방금 끝남, 終わったところ. 終わる는 끝나기 직전이라 うん과 안 맞고, 終わっている·終わろう는 ところ와 어울리지 않아요."]},{"id":"b135","g":"time","lv":4,"p":"～たばかり","m":"~한 지 얼마 안 됐다 · 막 ~했다","c":"동사 た형 + ばかりだ (명사 앞: た형 + ばかりの + 명사)","d":"어떤 일을 하고 나서 시간이 별로 지나지 않았다는 느낌이에요. 실제로 한 달·일 년이 지났어도 말하는 사람이 '얼마 안 됐다'고 느끼면 써요. 뒤에 なのに·なので가 자주 와요(買ったばかりなのに 산 지 얼마 안 됐는데).","ex":[["先月、日本に来たばかりです。","せんげつ、にほんに きた ばかりです。","지난달에 막 일본에 왔습니다."],["買ったばかりのかさをなくしてしまいました。","かった ばかりの かさを なくして しまいました。","산 지 얼마 안 된 우산을 잃어버렸습니다."]],"cmp":[["～ばかり（명사 뒤）","명사 + ばかり는 '~만 (자꾸)'(ゲームばかり), た형 + ばかり는 '막 ~함'"]],"qz":["このくつは先週（　　）なのに、もうよごれてしまいました。","買ったばかり",["買ったところ","買うところ","買っているところ"],"この くつは せんしゅう かった ばかりなのに、もう よごれて しまいました。","이 신발은 지난주에 산 지 얼마 안 됐는데 벌써 더러워졌어요.","지난주라 시간이 좀 지났지만 '얼마 안 됐다'는 느낌이라 買ったばかり. 買ったところ는 '방금 막' 끝난 순간에만 써서 先週와 맞지 않아요."]},{"id":"b136","g":"time","lv":4,"p":"～たまま","m":"~한 채(로)","c":"동사 た형 + まま / ない형 + まま / 명사 + の + まま / い형용사 ～い·な형용사 ～な + まま","d":"어떤 상태를 바꾸지 않고 그대로 둔 채 다음 일을 한다는 뜻이에요. 보통은 바꿔야 할 상태일 때가 많아요(くつをはいたまま 신발을 신은 채). 긍정 동사는 た형에 붙어요(はくまま ✕).","ex":[["くつをはいたまま、部屋に入らないでください。","くつを はいた まま、へやに はいらないで ください。","신발을 신은 채 방에 들어가지 마세요."],["窓を開けたまま寝てしまいました。","まどを あけた まま ねて しまいました。","창문을 연 채로 잠들어 버렸습니다."]],"qz":["めがねを（　　）まま、おふろに入ってしまいました。","かけた",["かける","かけて","かけよう"],"めがねを かけた まま、おふろに はいって しまいました。","안경을 쓴 채로 목욕탕에 들어가 버렸습니다.","긍정 동사는 た형에 まま가 붙어요(かけたまま). かけるまま·かけてまま·かけようまま는 틀린 꼴이에요."]},{"id":"b137","g":"aspect","lv":4,"p":"～だす","m":"(갑자기) ~하기 시작하다","c":"동사 ます형(ます 뺀 꼴) + 出す (降り出す·泣き出す)","d":"어떤 일이 갑자기·예상치 못하게 시작될 때 써요(泣き出す·笑い出す·降り出す). 계획해서 시작하는 일에는 はじめる가 자연스러워요. 出す는 1그룹이라 出します·出した로 바뀌어요.","ex":[["急に雨が降り出しました。","きゅうに あめが ふりだしました。","갑자기 비가 내리기 시작했습니다."],["赤ちゃんが大きな声で泣き出しました。","あかちゃんが おおきな こえで なきだしました。","아기가 큰 소리로 울기 시작했습니다."]],"cmp":[["～はじめる","はじめる는 시작 일반(계획한 일도 OK), だす는 갑작스러운 시작. '~하기 시작합시다'는 はじめましょう만 가능"]],"qz":["おもしろい話を聞いて、弟が急に（　　）。","笑い出しました",["笑い出ました","笑い始まりました","笑って出しました"],"おもしろい はなしを きいて、おとうとが きゅうに わらいだしました。","재미있는 이야기를 듣고 남동생이 갑자기 웃기 시작했습니다.","갑자기 시작된 일이라 ます형 + 出す(笑い出しました). 出る·始まる는 이렇게 붙여 쓰지 않고, て형 뒤에는 出す가 붙지 않아요."]},{"id":"b138","g":"aspect","lv":4,"p":"～はじめる","m":"~하기 시작하다","c":"동사 ます형(ます 뺀 꼴) + 始める (読み始める·食べ始める)","d":"동작이나 변화가 시작된다는 뜻이에요. 始める는 2그룹이라 始めます·始めた로 바뀌어요. 내 뜻으로 시작하는 일(習い始める)에도, 저절로 시작되는 일(咲き始める)에도 써요.","ex":[["去年から日本語を習い始めました。","きょねんから にほんごを ならいはじめました。","작년부터 일본어를 배우기 시작했습니다."],["公園の桜が咲き始めました。","こうえんの さくらが さきはじめました。","공원의 벚꽃이 피기 시작했습니다."]],"qz":["みんなそろいましたね。では、食べ（　　）。","始めましょう",["出しましょう","始まりましょう","終わりましょう"],"みんな そろいましたね。では、たべはじめましょう。","모두 모였네요. 그럼 먹기 시작합시다.","'~하기 시작합시다'는 始めましょう만 돼요. 出す는 ましょう와 쓰지 않고, 始まる는 ます형에 붙지 않으며, 막 모였으니 終わりましょう는 뜻이 안 맞아요."]},{"id":"b139","g":"aspect","lv":4,"p":"～つづける","m":"계속 ~하다","c":"동사 ます형(ます 뺀 꼴) + 続ける (歩き続ける·降り続ける)","d":"같은 동작을 멈추지 않고 계속한다는 뜻이에요. 続ける는 2그룹이라 続けます·続けた로 바뀌어요. 사람의 동작에도, 비가 계속 내리는 것 같은 자연 현상에도 써요.","ex":[["三時間も歩き続けました。","さんじかんも あるきつづけました。","세 시간이나 계속 걸었습니다."],["朝から雨が降り続けています。","あさから あめが ふりつづけて います。","아침부터 비가 계속 내리고 있습니다."]],"qz":["弟は朝から三時間もゲームをし（　　）。","続けています",["出しています","始めています","終わっています"],"おとうとは あさから さんじかんも ゲームを しつづけて います。","남동생은 아침부터 세 시간이나 계속 게임을 하고 있습니다.","세 시간이나 멈추지 않고 하는 중이라 続けています. 出す·始める는 시작, 終わる는 끝이라 '세 시간이나'와 맞지 않아요."]},{"id":"b140","g":"aspect","lv":4,"p":"～おわる","m":"다 ~하다 · ~하는 것을 끝내다","c":"동사 ます형(ます 뺀 꼴) + 終わる (読み終わる·食べ終わる)","d":"어떤 일을 끝까지 다 했다는 뜻이에요. 終わる는 1그룹이라 終わります·終わった·終わったら로 바뀌어요. 읽기·먹기·쓰기처럼 끝이 있는 동작에 써요.","ex":[["この本はもう読み終わりました。","この ほんは もう よみおわりました。","이 책은 벌써 다 읽었습니다."],["食べ終わったら、お皿を洗ってください。","たべおわったら、おさらを あらって ください。","다 먹으면 접시를 씻어 주세요."]],"qz":["この本を全部読み（　　）ら、私にかしてください。","終わった",["始めた","出した","続けた"],"この ほんを ぜんぶ よみおわったら、わたしに かして ください。","이 책을 다 읽으면 저에게 빌려주세요.","전부 다 읽고 나서 빌려 달라는 말이라 読み終わったら. 始めた·出した는 시작, 続けた는 계속이라 '全部'와 맞지 않아요."]},{"id":"b141","g":"aspect","lv":4,"p":"～てしまう","m":"~해 버리다 (완료·아쉬움)","c":"동사 て형 + しまう (회화: ～ちゃう·～じゃう)","d":"뜻이 둘이에요. ① 끝까지 다 해 버림(宿題を全部してしまった) ② 원하지 않은 일이 일어나 아쉽거나 후회됨(さいふを落としてしまった). 회화에서는 食べちゃった·飲んじゃった처럼 줄여 말해요.","ex":[["宿題はもう全部してしまいました。","しゅくだいは もう ぜんぶ して しまいました。","숙제는 벌써 전부 해 버렸습니다."],["電車でさいふを落としてしまいました。","でんしゃで さいふを おとして しまいました。","전철에서 지갑을 떨어뜨리고 말았습니다."]],"cmp":[["～おわる","おわる는 '다 했다'는 사실만, てしまう는 완료에 '후련함·아쉬움' 같은 기분이 더해짐"]],"qz":["大切なお皿を（　　）しまいました。母にしかられます。","わって",["われて","わった","わる"],"たいせつな おさらを わって しまいました。ははに しかられます。","소중한 접시를 깨 버렸어요. 엄마한테 혼나겠어요.","しまう 앞은 て형이고 お皿を가 있으니 타동사 わって. われて는 자동사라 を와 못 쓰고, わった·わる는 しまう 앞에 못 와요."]},{"id":"b142","g":"cond","lv":4,"p":"～たら","m":"~하면 · ~했더니","c":"동사 た형 + ら (行ったら·食べたら) / い형용사 ～かったら (安かったら) / な형용사·명사 + だったら (元気だったら·雨だったら) / ない형 ～なかったら","d":"가장 두루 쓰는 조건이에요. 앞의 일이 이루어진 뒤에 뒤의 일이 일어나요. 뒤에 부탁·권유·의지가 와도 괜찮아요(着いたら電話してください). 과거 문장에서는 '~했더니'(뜻밖에 알게 됨)가 돼요.","ex":[["仕事が終わったら、電話してください。","しごとが おわったら、でんわして ください。","일이 끝나면 전화해 주세요."],["窓を開けたら、外は雪でした。","まどを あけたら、そとは ゆきでした。","창문을 열었더니 밖에 눈이 와 있었습니다."]],"cmp":[["～ば","ば는 '그 조건이면'에 초점. 앞이 동작이면 뒤에 부탁·의지가 어색함 → たら가 안전"],["～と（조건）","と는 '하면 늘 그렇게 됨'. 뒤에 부탁·의지·권유 불가"]],"qz":["空港に（　　）、すぐ私に電話してください。","着いたら",["着くと","着くのに","着いても"],"くうこうに ついたら、すぐ わたしに でんわして ください。","공항에 도착하면 바로 저에게 전화해 주세요.","뒤에 '~해 주세요'(부탁)가 오니 たら. と는 부탁과 못 쓰고, 着くのに는 '도착하는데도', 着いても는 '도착해도'라 뜻이 안 맞아요."]},{"id":"b143","g":"cond","lv":4,"p":"～ば","m":"~하면 (가정·조건)","c":"1그룹 う단→え단 + ば (行けば·飲めば) / 2그룹 る→れば (食べれば·見れば) / 3그룹 すれば·来れば(くれば) / い형용사 い→ければ (安ければ, いい→よければ) / ない→なければ / な형용사·명사 + なら(ば) (元気なら·雨なら)","d":"'그 조건만 갖추면 이렇게 된다'는 조건 자체를 중심으로 말해요. 앞이 동작(行く·着く)이면 뒤에 부탁·의지가 어색해서 たら를 써요. 앞이 상태(ある·형용사)면 괜찮아요(時間があれば来てください). 2그룹은 食べれば예요(食べるば ✕).","ex":[["この薬を飲めば、すぐよくなりますよ。","この くすりを のめば、すぐ よく なりますよ。","이 약을 먹으면 금방 나을 거예요."],["天気がよければ、山に登ります。","てんきが よければ、やまに のぼります。","날씨가 좋으면 산에 오릅니다."]],"cmp":[["～たら","たら는 '그 일이 일어난 뒤'에 초점이라 뒤에 부탁·의지가 자유로움, ば는 조건 자체에 초점"]],"qz":["明日、時間が（　　）、いっしょに映画を見ませんか。","あれば",["あると","あっても","あるば"],"あした、じかんが あれば、いっしょに えいがを みませんか。","내일 시간이 있으면 같이 영화 보지 않을래요?","앞이 상태(ある)라서 ば 뒤에 권유가 와도 돼요(あれば). と는 권유와 못 쓰고, あっても는 '있어도', あるば는 틀린 꼴이에요."]},{"id":"b144","g":"cond","lv":4,"p":"～と（조건）","m":"~하면 (언제나·반드시 그렇게 됨) · ~했더니","c":"동사 사전형·ない형 + と / い형용사 ～い + と / な형용사·명사 + だ + と","d":"앞의 일이 일어나면 자연히·늘 뒤의 일이 일어난다는 뜻이에요. 기계 조작·자연 현상·길 안내·습관에 써요. 뒤에 부탁·의지·권유(~해 주세요·~하자)는 올 수 없어요(駅に着くと電話してください ✕ → 着いたら).","ex":[["春になると、花が咲きます。","はるに なると、はなが さきます。","봄이 되면 꽃이 핍니다."],["この道をまっすぐ行くと、右に駅があります。","この みちを まっすぐ いくと、みぎに えきが あります。","이 길을 똑바로 가면 오른쪽에 역이 있습니다."]],"cmp":[["～たら","たら는 뒤에 부탁·의지 가능, と는 '하면 반드시 그렇게 되는' 일에만"]],"qz":["エレベーターのこのボタンを（　　）、ドアが開きます。","押すと",["押したり","押したと","押すのに"],"エレベーターの この ボタンを おすと、ドアが あきます。","엘리베이터의 이 버튼을 누르면 문이 열립니다.","누르면 늘 그렇게 되는 기계 조작이라 と. と 앞은 사전형이라 押したと는 틀리고, 押したり는 뒤에 する가 필요하며, 押すのに(누르는데)는 뜻이 맞지 않아요."]},{"id":"b145","g":"cond","lv":4,"p":"～なら","m":"~라면 (상대의 말·화제를 받아서)","c":"동사·い형용사 보통형 + なら (行くなら·安いなら) / な형용사·명사 + なら (元気なら·日曜日なら)","d":"상대가 한 말이나 지금 화제를 받아 '그것이라면'하고 조언·의견을 말할 때 써요. な형용사·명사에는 だ 없이 붙어요(元気だなら ✕). 뒤의 일이 앞의 일보다 먼저 일어나도 돼요(買うなら → 사기 전에 하는 조언).","ex":[["日曜日なら、ひまですよ。","にちようびなら、ひまですよ。","일요일이라면 한가해요."],["パソコンを買うなら、この店が安いですよ。","パソコンを かうなら、この みせが やすいですよ。","컴퓨터를 산다면 이 가게가 싸요."]],"cmp":[["～たら","行ったら는 '간 뒤에', 行くなら는 '갈 거라면 (가기 전에)'. 日本へ行ったら、すしを食べたい / 日本へ行くなら、日本語を習ったほうがいい"]],"qz":["冬の山に（　　）、あたたかい服を持っていってください。","登るなら",["登ったら","登ると","登れば"],"ふゆの やまに のぼるなら、あたたかい ふくを もって いって ください。","겨울 산에 오를 거라면 따뜻한 옷을 가져가세요.","산에 오르기 전에 하는 조언이라 登るなら. 登ったら는 '오른 뒤에'라 순서가 안 맞고, と·ば는 동작 뒤에 부탁이 오면 어색해요."]},{"id":"b146","g":"cond","lv":4,"p":"～ても","m":"~해도 · ~하더라도","c":"동사 て형 + も (行っても·読んでも) / い형용사 い→くても (高くても) / な형용사·명사 + でも (静かでも·雨でも)","d":"앞의 조건과 상관없이 뒤의 일은 그대로라는 뜻으로, 한국어 '~해도'와 같아요. いくら·どんなに와 함께 쓰면 '아무리 ~해도'가 돼요.","ex":[["いくら呼んでも、だれも来ませんでした。","いくら よんでも、だれも きませんでした。","아무리 불러도 아무도 오지 않았습니다."],["高くても、このくつがほしいです。","たかくても、この くつが ほしいです。","비싸도 이 신발을 갖고 싶습니다."]],"cmp":[["～のに","ても는 아직 일어나지 않은 가정에도 씀, のに는 이미 일어난 사실에 대한 불만·놀람(~인데도)"]],"qz":["練習がどんなに（　　）、毎日がんばります。","つらくても",["つらいても","つらければ","つらいのに"],"れんしゅうが どんなに つらくても、まいにち がんばります。","연습이 아무리 힘들어도 매일 열심히 하겠습니다.","どんなに와 함께 '아무리 ~해도'는 ても. い형용사는 い→くても(つらくても)라 つらいても는 틀리고, つらければ·つらいのに는 뜻이 안 맞아요."]},{"id":"b147","g":"reason","lv":4,"p":"～ため（に）","m":"~하기 위해 · ~ 때문에","c":"동사 사전형 / 명사 + の + ため(に) (목적) · 동사·い형용사 보통형 / な형용사 ～な / 명사 + の + ため(に) (원인)","d":"앞이 내가 하려는 일이면 목적(~하기 위해), 이미 일어난 일이면 원인(~ 때문에)이에요. 목적의 ために 앞에는 내 의지로 할 수 있는 동사가 와요. 원인의 뜻은 조금 딱딱해서 안내 방송·뉴스에 많이 나와요.","ex":[["日本語を勉強するために、日本へ来ました。","にほんごを べんきょうする ために、にほんへ きました。","일본어를 공부하기 위해 일본에 왔습니다."],["事故のため、電車が止まっています。","じこの ため、でんしゃが とまって います。","사고 때문에 전철이 멈춰 있습니다."]],"cmp":[["～ように（목적）","ために 앞은 의지 동사(買う·行く), ように 앞은 가능형·ない형·저절로 되는 동사(見える·忘れない)"]],"qz":["新しい自転車を買う（　　）、お金をためています。","ために",["ように","ながら","ことに"],"あたらしい じてんしゃを かう ために、おかねを ためて います。","새 자전거를 사기 위해 돈을 모으고 있습니다.","내 의지로 하는 '사다'의 목적이라 ために. ように는 買えるように처럼 가능형 뒤에 쓰고, ながら·ことに는 여기서 뜻이 통하지 않아요."]},{"id":"b148","g":"reason","lv":4,"p":"～ように（목적）","m":"~하도록 · ~할 수 있게","c":"동사 사전형(가능형·저절로 되는 동사) + ように / 동사 ない형 + ように","d":"'그런 상태가 되도록' 무언가를 한다는 뜻이에요. 앞에는 내 의지로 바로 정할 수 없는 말이 와요: 가능형(読めるように), ない형(忘れないように), 見える·聞こえる·なる 같은 동사.","ex":[["かぜをひかないように、早く寝ます。","かぜを ひかないように、はやく ねます。","감기에 걸리지 않도록 일찍 잡니다."],["後ろの人にも聞こえるように、大きな声で話します。","うしろの ひとにも きこえるように、おおきな こえで はなします。","뒤에 있는 사람에게도 들리도록 큰 소리로 말합니다."]],"cmp":[["～ために","ために 앞은 의지 동사(合格するために), ように 앞은 의지로 안 되는 말(合格できるように)"]],"qz":["黒板の字がよく見える（　　）、前の席にすわりました。","ように",["ために","ながら","ばかり"],"こくばんの じが よく みえるように、まえの せきに すわりました。","칠판 글씨가 잘 보이도록 앞자리에 앉았습니다.","見える는 저절로 되는 일이라 목적은 ように. ために 앞에는 의지 동사가 와야 하고, ながら·ばかり는 뜻이 맞지 않아요."]},{"id":"b149","g":"guess","lv":4,"p":"～そうだ（모양）","m":"~할 것 같다 · ~해 보인다 (보고 느낀 인상)","c":"동사 ます형(ます 뺀 꼴) + そうだ (降りそうだ) / い형용사 い를 뺀 꼴 + そうだ (おいしそうだ) / な형용사 + そうだ (元気そうだ) · いい→よさそう, ない→なさそう","d":"눈으로 보고 '그럴 것 같다·그렇게 보인다'고 느낀 인상이에요. 명사에는 붙지 않고(学生そう ✕), 보기만 하면 아는 것(きれい·赤い)에는 쓰지 않아요. 명사 앞은 おいしそうなケーキ, 동사 앞은 おいしそうに食べる예요.","ex":[["今にも雨が降りそうです。","いまにも あめが ふりそうです。","금방이라도 비가 올 것 같습니다."],["キムさんは今日、とても元気そうですね。","キムさんは きょう、とても げんきそうですね。","김 씨는 오늘 무척 기운이 넘쳐 보이네요."]],"cmp":[["～そうだ（전해 들음）","모양은 ます형·어간에 붙음(降りそう·元気そう), 전해 들음은 보통형에 붙음(降るそうだ·元気だそうだ)"],["～ようだ","そうだ는 겉모습을 보고 바로 느낀 인상, ようだ는 여러 근거로 판단한 추측"]],"qz":["見て！木の上のボールが、今にも（　　）です。","落ちそう",["落ちるそう","落ちたそう","落ちるらしい"],"みて！きの うえの ボールが、いまにも おちそうです。","봐! 나무 위의 공이 금방이라도 떨어질 것 같아요.","눈으로 보고 '곧 그럴 것 같다'는 인상이라 ます형 + そう(落ちそう). 落ちるそう·落ちたそう는 들은 말, 落ちるらしい는 들은 것에 근거한 추측이에요."]},{"id":"b150","g":"guess","lv":4,"p":"～そうだ（전해 들음）","m":"~라고 한다 (들은 것을 전함)","c":"보통형 + そうだ — 동사 (降るそうだ·降ったそうだ) / い형용사 (安いそうだ) / な형용사·명사 + だ + そうだ (元気だそうだ·先生だそうだ)","d":"남에게 듣거나 뉴스에서 본 내용을 그대로 전해요. 정보의 출처는 ～によると·～の話では로 앞에 말해요. そうだ 자체는 과거·부정으로 바꾸지 않고, 내용 쪽을 바꿔요(降らないそうだ ○ / 降るそうではない ✕).","ex":[["田中さんの話では、あの店はとても安いそうです。","たなかさんの はなしでは、あの みせは とても やすいそうです。","다나카 씨 말로는 저 가게는 아주 싸다고 합니다."],["山田さんのお母さんは先生だそうです。","やまださんの おかあさんは せんせいだそうです。","야마다 씨의 어머니는 선생님이라고 합니다."]],"cmp":[["～そうだ（모양）","元気そうだ(건강해 보인다, 내가 봄) / 元気だそうだ(건강하다고 한다, 들음) — だ 하나로 뜻이 바뀜"],["～らしい","そうだ는 들은 말을 그대로 전함, らしい는 들은 것을 바탕으로 '~인 것 같다'고 추측"]],"qz":["ニュースによると、きのう北海道で大雪が（　　）です。","降ったそう",["降りそう","降るそう","降ろう"],"ニュースに よると、きのう ほっかいどうで おおゆきが ふったそうです。","뉴스에 따르면 어제 홋카이도에 큰 눈이 내렸다고 합니다.","뉴스에서 들은 것을 전하니 보통형 + そう(降ったそう). 降りそう는 내가 보고 느낀 인상, 降るそう는 きのう와 시제가 안 맞고, 降ろう는 틀린 꼴이에요."]},{"id":"b151","g":"guess","lv":4,"p":"～ようだ","m":"~인 것 같다 (보고 듣고 판단한 추측)","c":"동사·い형용사 보통형 + ようだ / な형용사 ～な + ようだ (静かなようだ) / 명사 + の + ようだ (雨のようだ)","d":"보거나 듣거나 느낀 여러 근거로 말하는 사람이 판단한 추측이에요. 조금 딱딱한 말이라 회화에서는 みたいだ를 더 많이 써요. 명사에는 の, な형용사에는 な가 들어가는 것에 주의해요.","ex":[["部屋の電気が消えています。だれもいないようです。","へやの でんきが きえて います。だれも いないようです。","방의 불이 꺼져 있습니다. 아무도 없는 것 같습니다."],["外は雨のようです。かさを持っていきましょう。","そとは あめの ようです。かさを もって いきましょう。","밖에 비가 오는 것 같습니다. 우산을 가지고 갑시다."]],"cmp":[["～そうだ（모양）","そうだ는 겉모습 인상(おいしそう), ようだ는 근거로 판단(だれもいないようだ)"],["～らしい","ようだ는 내가 직접 보고 느낀 근거, らしい는 남에게 들은 근거"]],"qz":["お店の前にだれもいません。今日は休み（　　）です。","のよう",["よう","だよう","なよう"],"おみせの まえに だれも いません。きょうは やすみの ようです。","가게 앞에 아무도 없어요. 오늘은 쉬는 날인 것 같아요.","본 것을 근거로 한 추측 ようだ는 명사 뒤에 の가 필요해요(休みのよう). よう·だよう·なよう는 명사와의 접속이 틀린 꼴이에요."]},{"id":"b152","g":"guess","lv":4,"p":"～みたいだ","m":"~인 것 같다 (회화체 추측)","c":"동사·い형용사 보통형 + みたいだ / な형용사·명사 + みたいだ (だ·の·な 없이: 元気みたい·雨みたい)","d":"ようだ와 뜻이 같은 회화체예요. 접속이 달라서 명사·な형용사에 바로 붙어요(雨みたい ○ / 雨のみたい ✕). 친구·가족끼리 말할 때 많이 써요.","ex":[["あの人、田中さんみたいだね。","あの ひと、たなかさんみたいだね。","저 사람, 다나카 씨인 것 같아."],["かぎがない。どこかに落としたみたい。","かぎが ない。どこかに おとしたみたい。","열쇠가 없어. 어딘가에 떨어뜨린 것 같아."]],"cmp":[["～ようだ","뜻은 같고 ようだ가 조금 딱딱함. 명사: 雨のようだ / 雨みたいだ"]],"qz":["外がにぎやかだね。今日はお祭り（　　）だね。","みたい",["のみたい","なみたい","そう"],"そとが にぎやかだね。きょうは おまつりみたいだね。","밖이 북적북적하네. 오늘 축제인가 봐.","みたいだ는 명사에 바로 붙어요(お祭りみたい). のみたい·なみたい는 틀린 꼴이고, 모양의 そう는 명사에 붙지 않아요."]},{"id":"b153","g":"guess","lv":4,"p":"～ような／～ように（비유·예시）","m":"~ 같은 · ~처럼 (비유·예시)","c":"명사 + の + ような + 명사 / 명사 + の + ように + 동사·형용사 (동사 보통형 + ような·ように)","d":"닮은 것에 빗대거나(花のようにきれい 꽃처럼 예쁘다) 예를 들 때(すしのような日本料理 초밥 같은 일본 요리) 써요. 명사 앞에서는 ような, 동사·형용사 앞에서는 ように로 모양이 바뀌어요.","ex":[["今日は夏のように暑いですね。","きょうは なつの ように あついですね。","오늘은 여름처럼 덥네요."],["すしやてんぷらのような日本料理が好きです。","すしや てんぷらの ような にほんりょうりが すきです。","초밥이나 튀김 같은 일본 요리를 좋아합니다."]],"cmp":[["～ように（목적）","목적의 ように는 동사 뒤(忘れないように), 비유의 ように는 주로 명사 + の 뒤(夏のように)"]],"qz":["田中さんは、私にとってお兄さんの（　　）人です。","ような",["ように","ようで","みたいな"],"たなかさんは、わたしに とって おにいさんの ような ひとです。","다나카 씨는 저에게 형 같은 사람이에요.","뒤에 명사(人)가 오니 ような. ように는 동사·형용사 앞에 쓰고, ようで는 명사와 못 이어지며, みたいな는 の 없이 お兄さんみたいな라고 해야 해요."]},{"id":"b154","g":"guess","lv":4,"p":"～みたいな／～みたいに","m":"~ 같은 · ~처럼 (회화체)","c":"명사 + みたいな + 명사 / 명사 + みたいに + 동사·형용사","d":"ような·ように의 회화체예요. 명사에 の 없이 바로 붙어요(夢みたいな話 꿈 같은 이야기). 친구·가족과 말할 때 많이 써요.","ex":[["父は子どもみたいに喜んだ。","ちちは こどもみたいに よろこんだ。","아빠는 어린아이처럼 기뻐했어."],["ここは夢みたいなところだね。","ここは ゆめみたいな ところだね。","여기는 꿈 같은 곳이네."]],"cmp":[["～ような／～ように","뜻은 같음. 子どものような / 子どもみたいな — の가 있고 없음이 차이"]],"qz":["弟はねこ（　　）丸くなって寝ています。","みたいに",["みたいな","のみたいに","のような"],"おとうとは ねこみたいに まるく なって ねて います。","남동생은 고양이처럼 몸을 둥글게 말고 자고 있어요.","뒤에 동사(丸くなって)가 오니 みたいに. みたいな·のような는 명사 앞에 쓰고, のみたいに는 の가 필요 없어서 틀린 꼴이에요."]},{"id":"b155","g":"guess","lv":4,"p":"～らしい","m":"~라는 것 같다 (들은 것에 근거한 추측) · ~답다","c":"동사·い형용사 보통형 + らしい / な형용사·명사 + らしい (だ 없이: 静からしい·雨らしい)","d":"남에게 듣거나 읽은 정보를 바탕으로 '~인 것 같다'고 말해요. 확실하지 않은 소문을 전하는 느낌이에요. 명사 + らしい는 '~답다'라는 뜻도 있어요(春らしい 봄다운, 男らしい 남자다운).","ex":[["山田さんは来月、ひっこすらしいです。","やまださんは らいげつ、ひっこすらしいです。","야마다 씨는 다음 달에 이사한다는 것 같습니다."],["今日は春らしい暖かい日ですね。","きょうは はるらしい あたたかい ひですね。","오늘은 봄다운 따뜻한 날이네요."]],"cmp":[["～そうだ（전해 들음）","そうだ는 들은 말을 그대로 전달, らしい는 들은 것을 근거로 한 추측(확실하지 않음)"],["～ようだ","ようだ는 내가 보고 느낀 근거, らしい는 밖에서 들어온 정보"]],"qz":["うわさでは、新しい先生はとてもやさしい人（　　）です。","らしい",["そう","だらしい","のらしい"],"うわさでは、あたらしい せんせいは とても やさしい ひとらしいです。","소문으로는 새 선생님은 아주 다정한 분인 것 같아요.","소문(들은 것)에 근거한 추측이라 らしい, 명사에는 だ 없이 붙어요(人らしい). 人そう는 명사에 못 붙고, だらしい·のらしい는 틀린 꼴이에요."]},{"id":"b156","g":"guess","lv":4,"p":"～かもしれない","m":"~일지도 모른다","c":"동사·い형용사 보통형 + かもしれない / な형용사·명사 + かもしれない (だ 없이: 雨かもしれない)","d":"그럴 가능성이 있다고 볼 때 써요. 확신은 약해서 반반 정도의 느낌이에요. 정중하게는 かもしれません, 친구끼리는 かも만 쓰기도 해요. 명사·な형용사에 だ를 넣지 않아요(雨だかもしれない ✕).","ex":[["道がこんでいるので、少しおくれるかもしれません。","みちが こんで いるので、すこし おくれるかも しれません。","길이 막혀서 조금 늦을지도 모릅니다."],["あの人は先生かもしれません。","あの ひとは せんせいかも しれません。","저 사람은 선생님일지도 모릅니다."]],"cmp":[["～だろう／～でしょう","でしょう는 꽤 그럴 것이라는 추측, かもしれない는 그럴 수도 있다는 약한 추측"]],"qz":["空が暗くなってきたから、午後は雨（　　）。","かもしれません",["だかもしれません","のかもしれません","そうかもしれません"],"そらが くらく なって きたから、ごごは あめかも しれません。","하늘이 어두워졌으니 오후에는 비가 올지도 몰라요.","명사(雨)에는 だ 없이 바로 かもしれません이 붙어요. だかもしれません·のかもしれません·そうかもしれません은 틀린 꼴이에요."]},{"id":"b157","g":"guess","lv":4,"p":"～だろう","m":"~겠지 · ~일 것이다 (でしょう의 보통체)","c":"동사·い형용사 보통형 + だろう / な형용사·명사 + だろう (元気だろう·雨だろう — 元気だだろう ✕)","d":"でしょう의 보통체로, 말하는 사람의 추측이에요. 회화에서는 조금 남자 말투 느낌이 있고, 일기·작문 같은 글에도 써요. 끝을 올려 だろう？라고 하면 '~지?'하고 확인하는 말이 돼요.","ex":[["明日もきっと暑いだろう。","あしたも きっと あついだろう。","내일도 분명 덥겠지."],["キムさんも行くだろう？","キムさんも いくだろう？","김 씨도 가지?"]],"cmp":[["～でしょう","뜻은 같고 でしょう는 정중체(明日は晴れるでしょう)"]],"qz":["夜のこの時間なら、あの公園はきっと静か（　　）。","だろう",["だだろう","なだろう","のだろう"],"よるの この じかんなら、あの こうえんは きっと しずかだろう。","밤 이 시간이라면 그 공원은 분명 조용하겠지.","な형용사에는 그대로 だろう가 붙어요(静かだろう). だだろう·なだろう·のだろう는 틀린 꼴이에요."]},{"id":"b158","g":"guess","lv":4,"p":"～はずだ","m":"(당연히) ~일 것이다 · ~일 텐데","c":"동사·い형용사 보통형 + はずだ / な형용사 ～な + はずだ / 명사 + の + はずだ","d":"근거나 사정으로 보아 '당연히 그럴 것'이라고 믿을 때 써요(약속했으니 올 것이다 등). 한국어 '~일 거예요·~일 텐데'에 가까워요. 내가 마음먹은 계획은 はず가 아니라 つもり로 말해요.","ex":[["田中さんは九時に家を出たから、もうすぐ着くはずです。","たなかさんは くじに いえを でたから、もうすぐ つく はずです。","다나카 씨는 9시에 집을 나섰으니까 곧 도착할 겁니다."],["今日は日曜日だから、銀行は休みのはずです。","きょうは にちようびだから、ぎんこうは やすみの はずです。","오늘은 일요일이니까 은행은 쉬는 날일 겁니다."]],"cmp":[["～だろう","だろう는 막연한 추측, はずだ는 분명한 근거가 있는 추측"]],"qz":["リンさんは十年も日本に住んでいたから、日本語が上手な（　　）。","はずです",["ところです","ことです","ばかりです"],"リンさんは じゅうねんも にほんに すんで いたから、にほんごが じょうずな はずです。","린 씨는 10년이나 일본에 살았으니까 일본어를 잘할 거예요.","10년 살았다는 근거로 '당연히 그럴 것'이라 はずです. ところです(시점)·ことです·ばかりです는 上手な 뒤에서 뜻이 통하지 않아요."]},{"id":"b159","g":"guess","lv":4,"p":"～はずがない","m":"~일 리가 없다","c":"동사·い형용사 보통형 + はずがない / な형용사 ～な + はずがない / 명사 + の + はずがない","d":"근거로 보아 '그럴 가능성은 전혀 없다'고 강하게 부정해요. ～ないはずだ(아마 ~하지 않을 것이다)보다 훨씬 강한 말이에요. 회화에서는 が를 빼고 はずない라고도 해요.","ex":[["あんなにやさしい山田さんが怒るはずがありません。","あんなに やさしい やまださんが おこる はずが ありません。","그렇게 다정한 야마다 씨가 화낼 리가 없습니다."],["毎日練習しているから、負けるはずがない。","まいにち れんしゅうして いるから、まける はずが ない。","매일 연습하고 있으니까 질 리가 없어."]],"cmp":[["～ないはずだ","ないはずだ는 '아마 ~하지 않을 것', はずがない는 '~일 리 없다'(더 강함)"]],"qz":["これは小さい子どものための本だから、むずかしい（　　）。","はずがありません",["はずです","ようです","つもりです"],"これは ちいさい こどもの ための ほんだから、むずかしい はずが ありません。","이건 어린아이를 위한 책이니까 어려울 리가 없어요.","어린아이용 책이라는 근거로 '그럴 리 없다'고 강하게 부정하니 はずがありません. はずです·ようです는 근거와 반대 뜻이 되고, つもりです는 계획이에요."]},{"id":"b160","g":"will","lv":4,"p":"～たい","m":"~하고 싶다","c":"동사 ます형(ます 뺀 꼴) + たい","d":"말하는 사람(나)의 희망이에요. たい는 い형용사처럼 바뀌어요(行きたくない·行きたかった). 목적어는 を도 が도 써요(水が飲みたい·水を飲みたい). 남의 희망은 ～たがる나 ～たいそうだ로 말해요.","ex":[["夏休みに海で泳ぎたいです。","なつやすみに うみで およぎたいです。","여름방학에 바다에서 수영하고 싶습니다."],["今日は何も食べたくないです。","きょうは なにも たべたくないです。","오늘은 아무것도 먹고 싶지 않습니다."]],"tag":"r5","cmp":[["～がほしい","ほしい는 물건(명사)을 갖고 싶다, たい는 동작을 하고 싶다"]],"qz":["とても暑いので、冷たい水が（　　）です。","飲みたい",["飲むたい","飲みほしい","飲みたがる"],"とても あついので、つめたい みずが のみたいです。","너무 더워서 차가운 물을 마시고 싶어요.","たい는 ます형(ます 뺀 꼴)에 붙어요(飲みたい). 飲むたい는 틀린 꼴, ほしい는 명사(물건)에 쓰고, たがる는 남의 희망이에요."]},{"id":"b161","g":"will","lv":4,"p":"～(よ)うと思う","m":"~하려고 생각한다 · ~할까 한다","c":"동사 의지형 + と思う (行こうと思う·食べようと思う·しようと思う·来ようと思う)","d":"말하는 사람의 계획·의지를 부드럽게 말해요. 전부터 계속 생각해 온 일이면 ～(よ)うと思っている를 써요. 남의 생각을 말할 때도 思っている를 써요(田中さんは帰ろうと思っている).","ex":[["今晩は早く寝ようと思います。","こんばんは はやく ねようと おもいます。","오늘 밤은 일찍 자려고 합니다."],["日本の大学に入ろうと思っています。","にほんの だいがくに はいろうと おもって います。","일본 대학에 들어가려고 생각하고 있습니다."]],"cmp":[["～つもりだ","つもりだ는 이미 굳힌 계획, (よ)うと思う는 '~할까 한다'는 부드러운 의지"]],"qz":["夏休みに、いなかのおばあさんの家へ（　　）と思います。","行こう",["行け","行きましょう","行くよう"],"なつやすみに、いなかの おばあさんの いえへ いこうと おもいます。","여름방학에 시골 할머니 댁에 가려고 합니다.","내 계획은 의지형 + と思います(行こう). 명령형 行け, 정중한 권유 行きましょう, 行くよう는 と思います 앞에서 계획의 뜻이 되지 않아요."]},{"id":"b162","g":"will","lv":4,"p":"～(よ)うとする","m":"~하려고 하다 · 막 ~하려 하다","c":"동사 의지형 + とする (出かけようとする·思い出そうとする)","d":"두 가지로 써요. ① 바로 그 동작을 하려는 순간(出ようとしたとき 나가려고 했을 때) ② 하려고 애씀(思い出そうとした 떠올리려고 했다). '~하려고 했지만 안 됐다'처럼 뒤에 실패가 오는 일이 많아요.","ex":[["家を出ようとしたとき、雨が降り出しました。","いえを でようと した とき、あめが ふりだしました。","집을 나서려고 했을 때 비가 내리기 시작했습니다."],["名前を思い出そうとしましたが、思い出せませんでした。","なまえを おもいだそうと しましたが、おもいだせませんでした。","이름을 떠올리려고 했지만 떠오르지 않았습니다."]],"cmp":[["～(よ)うと思う","と思う는 마음속 계획, とする는 실제로 그 동작을 하려는 순간·노력"]],"qz":["電車に（　　）としたとき、ドアが閉まってしまいました。","乗ろう",["乗る","乗った","乗れる"],"でんしゃに のろうと した とき、ドアが しまって しまいました。","전철을 타려고 했을 때 문이 닫혀 버렸습니다.","막 타려는 순간이라 의지형 + とする(乗ろうとした). 乗る·乗った·乗れる에 としたとき를 붙이면 '~하려고 했다'는 뜻이 되지 않아요."]},{"id":"b163","g":"will","lv":4,"p":"～つもりだ／～つもりはない","m":"~할 생각이다 / ~할 생각은 없다","c":"동사 사전형·ない형 + つもりだ / 동사 사전형 + つもりはない","d":"이미 마음먹은 계획을 말해요. '~하지 않을 생각이다'는 行かないつもりだ, '~할 생각은 (전혀) 없다'고 더 강하게 말할 때는 行くつもりはない예요. 윗사람에게 직접 '~할 생각입니까?'라고 묻는 것은 실례가 될 수 있어요.","ex":[["来年、日本で働くつもりです。","らいねん、にほんで はたらく つもりです。","내년에 일본에서 일할 생각입니다."],["あの店にはもう行くつもりはありません。","あの みせには もう いく つもりは ありません。","저 가게에는 이제 갈 생각이 없습니다."]],"cmp":[["～予定だ","つもり는 내 마음속 결심, 予定는 정해진 일정(회의·출발 등)"]],"qz":["おかしは体によくないから、夜はもう（　　）つもりです。","食べない",["食べる","食べなくて","食べません"],"おかしは からだに よくないから、よるは もう たべない つもりです。","과자는 몸에 좋지 않으니까 밤에는 이제 먹지 않을 생각이에요.","몸에 안 좋으니 '먹지 않을 생각'이라 ない형 + つもり(食べないつもり). 食べる는 뜻이 반대이고, 食べなくて·食べません은 つもり 앞에 올 수 없어요."]},{"id":"b164","g":"will","lv":4,"p":"～ことにする","m":"~하기로 하다 (내가 정함)","c":"동사 사전형·ない형 + ことにする","d":"말하는 사람이 스스로 결정했다는 뜻이에요. ことにした는 '~하기로 정했다', ことにしている는 '~하기로 하고 있다(정해 둔 습관)'예요.","ex":[["体のために、毎朝歩くことにしました。","からだの ために、まいあさ あるく ことに しました。","몸을 위해 매일 아침 걷기로 했습니다."],["夜はおかしを食べないことにしています。","よるは おかしを たべない ことに して います。","밤에는 과자를 먹지 않기로 하고 있습니다."]],"cmp":[["～ことになる","ことにする는 내가 정함, ことになる는 남·상황에 의해 정해짐"]],"qz":["夏休みの間、毎日日記を書く（　　）。自分で決めたんです。","ことにしました",["ことになりました","ことがあります","ことをしました"],"なつやすみの あいだ、まいにち にっきを かく ことに しました。じぶんで きめたんです。","여름방학 동안 매일 일기를 쓰기로 했어요. 제가 스스로 정했어요.","스스로 정했으니 ことにしました. ことになりました는 남·상황이 정한 일, ことがあります는 '가끔 ~한다'라 毎日와 안 맞고, ことをしました는 틀린 말이에요."]},{"id":"b165","g":"will","lv":4,"p":"～ことになる","m":"~하게 되다 (정해지다)","c":"동사 사전형·ない형 + ことになる","d":"내 뜻이 아니라 회사·학교·상황에 의해 그렇게 정해졌다는 뜻이에요. 내가 정한 일이라도 ことになりました라고 하면 겸손하고 부드럽게 들려요.","ex":[["四月から、東京の学校に通うことになりました。","しがつから、とうきょうの がっこうに かよう ことに なりました。","4월부터 도쿄의 학교에 다니게 되었습니다."],["会議は三時から始めることになりました。","かいぎは さんじから はじめる ことに なりました。","회의는 3시부터 시작하게 되었습니다."]],"cmp":[["～ようになる","ことになる는 결정으로 정해짐, ようになる는 능력·습관이 차츰 바뀜(読めるようになった)"]],"qz":["会社が決めたので、父は来月から大阪で働く（　　）。","ことになりました",["ことにしました","ことがあります","ことをしました"],"かいしゃが きめたので、ちちは らいげつから おおさかで はたらく ことに なりました。","회사가 정해서 아버지는 다음 달부터 오사카에서 일하게 되었습니다.","회사가 정한 일이라 ことになりました. ことにしました는 자기가 정한 일, ことがあります는 가끔 하는 일이고, ことをしました는 틀린 말이에요."]},{"id":"b166","g":"will","lv":4,"p":"～ことになっている","m":"~하기로 되어 있다 (규칙·예정)","c":"동사 사전형·ない형 + ことになっている","d":"규칙·약속·예정으로 이미 정해져 있다는 뜻이에요. 학교·회사의 규칙이나 미리 정한 약속을 설명할 때 많이 써요.","ex":[["図書館の中では話さないことになっています。","としょかんの なかでは はなさない ことに なって います。","도서관 안에서는 말하지 않기로 되어 있습니다."],["明日、駅の前で田中さんと会うことになっています。","あした、えきの まえで たなかさんと あう ことに なって います。","내일 역 앞에서 다나카 씨와 만나기로 되어 있습니다."]],"cmp":[["～ことにしている","ことにしている는 내가 정한 습관, ことになっている는 밖에서 정해진 규칙·예정"]],"qz":["このプールでは、入る前に必ずシャワーをあびる（　　）。","ことになっています",["ことがあります","ところです","ばかりです"],"この プールでは、はいる まえに かならず シャワーを あびる ことに なって います。","이 수영장에서는 들어가기 전에 반드시 샤워를 하기로 되어 있습니다.","수영장 규칙으로 정해져 있으니 ことになっています. ことがあります는 '가끔', ところです는 '막 ~하려는 참', ばかりです는 '~만 한다'라 必ず와 맞지 않아요."]},{"id":"b167","g":"rule","lv":4,"p":"～てもいい","m":"~해도 된다 (허가)","c":"동사 て형 + もいい / い형용사 い→くてもいい / な형용사·명사 + でもいい","d":"허락하거나 허락을 구할 때 써요. ～てもいいですか(~해도 됩니까?)로 묻고, 대답은 はい、どうぞ나 すみません、ちょっと…예요. 더 정중하게는 ～てもよろしいですか예요.","ex":[["この部屋で写真をとってもいいですか。","この へやで しゃしんを とっても いいですか。","이 방에서 사진을 찍어도 됩니까?"],["テストのとき、辞書を使ってもいいです。","テストの とき、じしょを つかっても いいです。","시험 때 사전을 써도 됩니다."]],"tag":"r5","cmp":[["～てもかまわない","뜻은 같고 かまわない가 조금 딱딱하며 '상관없다'는 느낌"]],"qz":["「この本を（　　）いいですか。」「はい、どうぞ。」","借りても",["借りては","借りるも","借りたも"],"「この ほんを かりても いいですか。」「はい、どうぞ。」","\"이 책을 빌려도 돼요?\" \"네, 그러세요.\"","허락을 구할 때는 て형 + もいいですか(借りてもいい). 借りてはいい는 쓰지 않고, 借りるも·借りたも는 틀린 꼴이에요."]},{"id":"b168","g":"rule","lv":4,"p":"～てはいけない","m":"~하면 안 된다 (금지)","c":"동사 て형 + はいけない (회화: ～ちゃいけない·～じゃいけない)","d":"규칙이나 윗사람이 금지할 때 써요. は는 わ로 읽어요. 강하게 들려서 손님이나 윗사람에게는 ～ないでください를 많이 써요.","ex":[["ここに車を止めてはいけません。","ここに くるまを とめては いけません。","여기에 차를 세우면 안 됩니다."],["教室で走ってはいけませんよ。","きょうしつで はしっては いけませんよ。","교실에서 뛰면 안 돼요."]],"tag":"r5","cmp":[["～ないでください","ないでください는 부탁 모양의 부드러운 금지, てはいけない는 규칙 같은 강한 금지"]],"qz":["ろうかを（　　）いけません。ぶつかると危ないです。","走っては",["走れば","走らなくては","走りは"],"ろうかを はしっては いけません。ぶつかると あぶないです。","복도에서 뛰면 안 돼요. 부딪치면 위험해요.","부딪치면 위험하니 금지, 走ってはいけません. 走らなくては는 '꼭 뛰어야 한다'라 뜻이 반대이고, 走れば·走りは는 いけません과 이어지지 않아요."]},{"id":"b169","g":"rule","lv":4,"p":"～なければならない","m":"~해야 한다 (의무)","c":"동사 ない형(ない 뺀 꼴) + なければならない (行く→行かなければならない·食べる→食べなければならない·する→しなければならない·来る→来なければならない)","d":"규칙이나 사정 때문에 꼭 해야 한다는 뜻이에요. 말 그대로는 '~하지 않으면 안 된다'예요. 회화에서는 ～なきゃ·～なくちゃ로 줄여요(行かなきゃ).","ex":[["明日までにレポートを出さなければなりません。","あしたまでに レポートを ださなければ なりません。","내일까지 리포트를 내야 합니다."],["日本では、車は道の左側を走らなければなりません。","にほんでは、くるまは みちの ひだりがわを はしらなければ なりません。","일본에서는 차가 길의 왼쪽으로 달려야 합니다."]],"tag":"r5","cmp":[["～なくてはいけない／～ないといけない","뜻은 거의 같음. なければならない는 일반적인 의무·글에, ないといけない는 회화에 많음"]],"qz":["バスが七時に出るので、六時半には家を（　　）なりません。","出なければ",["出ては","出れば","出ても"],"バスが しちじに でるので、ろくじはんには いえを でなければ なりません。","버스가 7시에 출발해서 6시 반에는 집을 나서야 합니다.","버스 시간 때문에 꼭 해야 하는 일이라 なければなりません. 出てはなりません은 '나가면 안 된다'라 뜻이 반대이고, 出れば·出ても는 なりません과 이어지지 않아요."]},{"id":"b170","g":"rule","lv":4,"p":"～なくてもいい","m":"~하지 않아도 된다","c":"동사 ない형(ない 뺀 꼴) + なくてもいい (行かなくてもいい·食べなくてもいい)","d":"그 일을 할 필요가 없다는 뜻이에요. ～なければなりませんか(~해야 합니까?)에 '아니요'라고 대답할 때 많이 써요. 한국어 '안 해도 돼요'와 같아요.","ex":[["明日は休みだから、早く起きなくてもいいです。","あしたは やすみだから、はやく おきなくても いいです。","내일은 쉬는 날이니까 일찍 일어나지 않아도 됩니다."],["名前は書かなくてもいいですよ。","なまえは かかなくても いいですよ。","이름은 쓰지 않아도 돼요."]],"tag":"r5","cmp":[["～てはいけない","しなくてもいい는 '안 해도 됨(해도 괜찮음)', してはいけない는 '하면 안 됨'"]],"qz":["「全部食べなければなりませんか。」「いいえ、（　　）いいですよ。」","食べなくても",["食べては","食べなくては","食べるでも"],"「ぜんぶ たべなければ なりませんか。」「いいえ、たべなくても いいですよ。」","\"전부 먹어야 하나요?\" \"아니요, 먹지 않아도 돼요.\"","꼭 해야 하냐는 물음에 いいえ라고 했으니 '안 해도 된다', 食べなくてもいい. 食べてはいい·食べなくてはいい는 쓰지 않는 말이고, 食べるでも는 틀린 꼴이에요."]},{"id":"b171","g":"rule","lv":4,"p":"～てもかまわない","m":"~해도 상관없다","c":"동사 て형 + もかまわない / い형용사 い→くてもかまわない / な형용사·명사 + でもかまわない","d":"てもいい와 뜻이 같지만 '그래도 문제없다·상관없다'는 느낌이 더 강하고 조금 딱딱해요. 정중하게 허락을 구할 때 ～てもかまいませんか라고 해요.","ex":[["ペンで書いてもかまいません。","ペンで かいても かまいません。","펜으로 써도 상관없습니다."],["少し遠くてもかまいません。静かなところがいいです。","すこし とおくても かまいません。しずかな ところが いいです。","조금 멀어도 상관없습니다. 조용한 곳이 좋습니다."]],"qz":["意味がわからないときは、辞書を（　　）かまいません。","使っても",["使っては","使うも","使えば"],"いみが わからない ときは、じしょを つかっても かまいません。","뜻을 모를 때는 사전을 써도 상관없습니다.","'써도 상관없다'는 て형 + もかまいません(使っても). 使ってはかまいません·使えばかまいません은 쓰지 않고, 使うも는 틀린 꼴이에요."]},{"id":"b172","g":"rule","lv":4,"p":"～なくてもかまわない","m":"~하지 않아도 상관없다","c":"동사 ない형(ない 뺀 꼴) + なくてもかまわない","d":"なくてもいい와 같은 뜻으로, '안 해도 문제없다'는 느낌이 더 강해요. 조금 딱딱하고 정중한 장면에서 써요.","ex":[["明日の会議には、出なくてもかまいません。","あしたの かいぎには、でなくても かまいません。","내일 회의에는 나오지 않아도 상관없습니다."],["全部食べなくてもかまいませんよ。","ぜんぶ たべなくても かまいませんよ。","전부 먹지 않아도 상관없어요."]],"qz":["いつもは制服を着ますが、明日は（　　）かまいません。","着なくても",["着ても","着ては","着ないと"],"いつもは せいふくを きますが、あしたは きなくても かまいません。","평소에는 교복을 입지만 내일은 입지 않아도 상관없습니다.","'평소엔 입지만(が)' 내일은 다르다는 말이라 着なくても. 着ても는 평소와 같아 が와 안 맞고, 着ては·着ないと는 かまいません과 이어지지 않아요."]},{"id":"b173","g":"rule","lv":4,"p":"～なくてはいけない／～ないといけない","m":"~해야 한다 (회화에서 자주)","c":"동사 ない형(ない 뺀 꼴) + なくてはいけない / 동사 ない형 + といけない","d":"なければならない와 거의 같은 뜻이에요. 말하는 사람 자신의 사정으로 '해야 한다'고 할 때 회화에서 많이 써요. 더 줄이면 ～なくちゃ·～なきゃ, 또는 ～ないと만 써요(もう行かないと).","ex":[["明日は試験なので、勉強しなくてはいけません。","あしたは しけんなので、べんきょうしなくては いけません。","내일은 시험이라서 공부해야 합니다."],["もう九時だ。早く寝ないといけない。","もう くじだ。はやく ねないと いけない。","벌써 9시다. 빨리 자야 해."]],"cmp":[["～なければならない","뜻은 같음. なければならない는 규칙·일반적인 의무에 많고 조금 딱딱함"]],"qz":["犬がおなかをすかせているから、早くごはんをあげ（　　）。","なくてはいけません",["なくてもいいです","てはいけません","なくていけません"],"いぬが おなかを すかせて いるから、はやく ごはんを あげなくては いけません。","개가 배고파하니까 빨리 밥을 줘야 해요.","배고파하니 꼭 줘야 해서 なくてはいけません. なくてもいい는 '안 줘도 된다', てはいけません은 '주면 안 된다'라 뜻이 반대이고, なくていけません은 は가 빠진 틀린 꼴이에요."]},{"id":"b174","g":"rule","lv":4,"p":"～なさい","m":"~해라 · ~하렴 (부모·선생님이 시킬 때)","c":"동사 ます형(ます 뺀 꼴) + なさい (行きなさい·食べなさい·しなさい·来なさい)","d":"부모가 아이에게, 선생님이 학생에게 시킬 때 쓰는 명령이에요. 명령형(行け)보다 부드럽지만 윗사람이나 친구에게는 쓰지 않아요. 시험 지시문(正しいものを選びなさい)에도 나와요.","ex":[["早く宿題をしなさい。","はやく しゅくだいを しなさい。","빨리 숙제를 하렴."],["ごはんの前に、手を洗いなさい。","ごはんの まえに、てを あらいなさい。","밥 먹기 전에 손을 씻으렴."]],"cmp":[["명령형 (行け·食べろ)","명령형은 거칠고 강함, なさい는 어른이 아이에게 하는 부드러운 명령"]],"qz":["先生は、「みんな、こっちへ（　　）」と言いました。","来なさい",["来るなさい","来いなさい","来りなさい"],"せんせいは、「みんな、こっちへ きなさい」と いいました。","선생님은 \"모두 이쪽으로 오렴\"이라고 말했습니다.","なさい는 ます형(ます 뺀 꼴)에 붙어요. 来ます → 来(き)なさい. 来るなさい·来いなさい·来りなさい는 틀린 꼴이에요."]},{"id":"b175","g":"give","lv":4,"p":"～てあげる／～てやる","m":"(남에게) ~해 주다","c":"동사 て형 + あげる / 동사 て형 + やる","d":"내가(또는 내 쪽 사람이) 남을 위해 무언가를 해 줄 때 써요. てやる는 동생·동물·식물처럼 아랫사람에게 쓰는 말이에요. 윗사람에게 '~해 드릴게요'라고 할 때 てあげます는 생색내는 느낌이라 お～します(お持ちします)를 써요.","ex":[["妹に本を読んであげました。","いもうとに ほんを よんで あげました。","여동생에게 책을 읽어 주었습니다."],["弟の自転車をなおしてやりました。","おとうとの じてんしゃを なおして やりました。","남동생의 자전거를 고쳐 주었습니다."]],"cmp":[["～てくれる","てあげる는 내가 남에게, てくれる는 남이 나(내 쪽)에게 해 줌"]],"qz":["弟のおもちゃがこわれたので、私が自分で直して（　　）。","あげました",["くれました","もらいました","くださいました"],"おとうとの おもちゃが こわれたので、わたしが じぶんで なおして あげました。","남동생의 장난감이 고장 나서 제가 직접 고쳐 주었습니다.","내가 직접 동생을 위해 해 줬으니 あげました. くれました·くださいました는 남이 나에게 해 줄 때, もらいました는 남이 해 준 것을 받을 때라 '내가 직접'과 맞지 않아요."]},{"id":"b176","g":"give","lv":4,"p":"～てくれる","m":"(남이 나에게) ~해 주다","c":"동사 て형 + くれる","d":"남이 나나 내 가족을 위해 무언가를 해 줄 때 쓰고, 고마운 마음이 들어 있어요. 한국어는 '~해 주다' 하나지만 받는 쪽이 나(내 쪽)면 꼭 くれる예요. 부탁할 때는 ～てくれませんか(~해 주지 않을래요?)라고 해요.","ex":[["友だちが駅まで送ってくれました。","ともだちが えきまで おくって くれました。","친구가 역까지 바래다주었습니다."],["ちょっと手伝ってくれませんか。","ちょっと てつだって くれませんか。","좀 도와주지 않을래요?"]],"cmp":[["～てもらう","같은 일을 주어만 바꿔 말함: 友だちが教えてくれた(친구가 주어) = 友だちに教えてもらった(내가 주어)"]],"qz":["私がかぜで休んだとき、友だちが私にノートを見せて（　　）。","くれました",["あげました","やりました","さしあげました"],"わたしが かぜで やすんだ とき、ともだちが わたしに ノートを みせて くれました。","제가 감기로 쉬었을 때 친구가 저에게 노트를 보여 주었습니다.","친구가 '나에게(私に)' 해 줬으니 くれました. あげました·やりました·さしあげました는 내 쪽에서 남에게 해 줄 때 써서 私に와 맞지 않아요."]},{"id":"b177","g":"give","lv":4,"p":"～てもらう／～てもらえますか","m":"(남에게) ~해 받다 · ~해 줄 수 있어요?","c":"동사 て형 + もらう / 동사 て형 + もらえますか·もらえませんか","d":"남이 해 준 일을 받는 내 쪽에서 말해요. 해 준 사람은 に로 나타내요(友だちに教えてもらう). 한국어로는 '(친구가) ~해 주었다'로 옮기면 자연스러워요. もらえますか는 가능형을 써서 '~해 줄 수 있어요?'하고 부탁하는 말이에요.","ex":[["田中さんに写真をとってもらいました。","たなかさんに しゃしんを とって もらいました。","다나카 씨가 사진을 찍어 주었습니다."],["すみません、もう一度言ってもらえますか。","すみません、もう いちど いって もらえますか。","죄송한데 한 번 더 말해 줄 수 있어요?"]],"cmp":[["～てくれる","같은 일: 先生が説明してくれた = 先生に説明してもらった. くれる는 해 준 사람이 주어, もらう는 받은 내가 주어"]],"qz":["田中さんに道を教えて（　　）ので、私はまよわずに駅に着きました。","もらった",["あげた","くれた","くださった"],"たなかさんに みちを おしえて もらったので、わたしは まよわずに えきに つきました。","다나카 씨가 길을 가르쳐 주어서 저는 헤매지 않고 역에 도착했습니다.","다나카 씨(に)에게서 받은 쪽이 나라서 もらった. くれた·くださった는 해 준 사람이 が로 올 때 쓰고, あげた는 내가 가르쳐 준 것이라 '내가 헤매지 않고'와 안 맞아요."]},{"id":"b178","g":"give","lv":4,"p":"～てくださる／～てくださいませんか","m":"(윗사람이 나에게) ~해 주시다 / ~해 주시지 않겠습니까?","c":"동사 て형 + くださる / 동사 て형 + くださいませんか","d":"てくれる의 존경어로, 윗사람이 나를 위해 해 주실 때 써요. くださる는 ます 앞에서 くださいます가 돼요(くださります ✕). てくださいませんか는 てください보다 정중한 부탁이에요.","ex":[["先生が作文を直してくださいました。","せんせいが さくぶんを なおして くださいました。","선생님께서 작문을 고쳐 주셨습니다."],["すみませんが、ここに住所を書いてくださいませんか。","すみませんが、ここに じゅうしょを かいて くださいませんか。","죄송하지만 여기에 주소를 써 주시지 않겠습니까?"]],"cmp":[["～ていただけませんか","둘 다 정중한 부탁. いただけませんか가 한층 더 공손하게 들림"]],"qz":["先生が私に、わからない問題をていねいに教えて（　　）。","くださいました",["くださりました","さしあげました","いただきました"],"せんせいが わたしに、わからない もんだいを ていねいに おしえて くださいました。","선생님께서 저에게 모르는 문제를 친절하게 가르쳐 주셨습니다.","윗사람(先生が)이 나에게 해 주셨으니 くださいました. くださりました는 틀린 꼴, さしあげる는 내가 해 드릴 때, いただく는 받는 내가 주어일 때 써요."]},{"id":"b179","g":"te","lv":4,"p":"～ている","m":"~하고 있다 (진행) · ~해 있다 (상태·결과)","c":"동사 て형 + いる","d":"계속하는 동작이면 '~하고 있는 중'(食べている), 순간에 끝나는 동작(結婚する·来る·着る 등)이면 '그 결과가 남아 있음'(結婚している = 결혼했다)이에요. 습관·직업(銀行で働いている)에도 써요. '모르다'는 知らない (知っていない ✕).","ex":[["弟は今、部屋で勉強しています。","おとうとは いま、へやで べんきょうして います。","남동생은 지금 방에서 공부하고 있습니다."],["姉はもう結婚しています。","あねは もう けっこんして います。","언니는 이미 결혼했습니다."]],"tag":"r5","cmp":[["～てある","자동사 + ている는 그냥 그런 상태(窓が開いている), 타동사 + てある는 누가 일부러 해 둔 상태(窓が開けてある)"]],"qz":["私が家に帰ったとき、弟はまだ（　　）。","寝ていました",["寝てありました","寝ておきました","寝てみました"],"わたしが いえに かえった とき、おとうとは まだ ねて いました。","내가 집에 돌아왔을 때 남동생은 아직 자고 있었습니다.","'まだ(아직)' 계속되는 동작이라 ている. 寝る는 자동사라 てある가 안 되고, ておく·てみる는 まだ와 맞지 않아요."]},{"id":"b180","g":"te","lv":4,"p":"～て／～で（잇기·이유）","m":"~하고 · ~해서 (순서) · ~해서 (이유)","c":"동사 て형 (읽다 → 読んで처럼 で가 되기도 함) / い형용사 い→くて / な형용사·명사 + で","d":"동작을 순서대로 잇거나(起きて、顔を洗う) 이유를 나타내요(遅れて、すみません). 이유의 て 뒤에는 기분·상태(困る·できない·すみません)가 오고, 부탁·명령·의지는 오지 않아요 — 그때는 から·ので를 써요.","ex":[["朝ごはんを食べて、学校へ行きます。","あさごはんを たべて、がっこうへ いきます。","아침밥을 먹고 학교에 갑니다."],["かぜをひいて、学校を休みました。","かぜを ひいて、がっこうを やすみました。","감기에 걸려서 학교를 쉬었습니다."]],"tag":"r5","cmp":[["～から／～ので","て의 이유 뒤에는 부탁이 못 와요: 暑くて窓を開けてください ✕ → 暑いから窓を開けてください"]],"qz":["新しい教室は（　　）、とても明るいです。","きれいで",["きれいくて","きれいだで","きれいに"],"あたらしい きょうしつは きれいで、とても あかるいです。","새 교실은 깨끗하고 아주 밝습니다.","きれい는 な형용사라 で로 이어요(い형용사처럼 くて ✕). きれいに는 '깨끗하게'라 뒤에 동사가 와야 해요."]},{"id":"b181","g":"te","lv":4,"p":"～てある","m":"~되어 있다 · ~해 두었다 (누가 해 놓은 상태)","c":"타동사 て형 + ある (대상은 보통 が)","d":"누군가 일부러 해 놓은 결과가 지금 남아 있다는 뜻이에요. 窓を開ける → 窓が開けてある처럼 を가 が로 바뀌는 것이 시험 포인트예요. 자동사(開く·閉まる)에는 붙지 않아요.","ex":[["教室にいすが並べてあります。","きょうしつに いすが ならべて あります。","교실에 의자가 줄지어 놓여 있습니다."],["切符はもう買ってあります。","きっぷは もう かって あります。","표는 벌써 사 두었습니다."]],"cmp":[["～ている(자동사)","窓が開いている는 '열려 있다'는 상태만, 窓が開けてある는 '누가 열어 두었다'는 뜻까지"],["～ておく","ておく는 미리 '해 두는' 동작, てある는 해 둔 뒤 남은 '결과 상태'"]],"qz":["見てください。教室の窓が全部（　　）よ。","開けてあります",["開けています","開けておきます","開けてみます"],"みて ください。きょうしつの まどが ぜんぶ あけて ありますよ。","보세요. 교실 창문이 전부 열려 있어요.","누가 열어 놓은 결과가 남아 있고 대상이 が라 てある. 開けている는 '여는 중'이라 が와 안 맞고, ておく·てみる는 を가 필요해요."]},{"id":"b182","g":"te","lv":4,"p":"～ていく","m":"~하고 가다 · ~해서 가다 · (앞으로) ~해 가다","c":"동사 て형 + いく","d":"① 어떤 방법·상태로 가다(歩いていく 걸어서 가다, 傘を持っていく 우산을 가지고 가다) ② 지금부터 앞으로 변화가 계속되다(寒くなっていく). 말하는 사람에게서 멀어지는 방향이에요. 보조 동사라 보통 히라가나 いく로 써요.","ex":[["雨が降りそうなので、傘を持っていきます。","あめが ふりそうなので、かさを もって いきます。","비가 올 것 같아서 우산을 가지고 가겠습니다."],["これから、もっと寒くなっていきますね。","これから、もっと さむく なって いきますね。","앞으로 더 추워지겠네요."]],"cmp":[["～てくる","ていく는 나에게서 멀어지는 쪽·지금부터 앞으로, てくる는 나에게 다가오는 쪽·과거부터 지금까지"]],"qz":["これから、私の日本語はもっと上手に（　　）と思います。","なっていく",["なってきた","なっておく","なってある"],"これから、わたしの にほんごは もっと じょうずに なって いくと おもいます。","앞으로 제 일본어는 더 능숙해져 갈 거라고 생각합니다.","'これから(앞으로)' 변해 갈 일이라 ていく. てきた는 지금까지 변해 온 일이라 これから와 안 맞고, ておく·てある는 변화에 못 써요."]},{"id":"b183","g":"te","lv":4,"p":"～てくる","m":"~하고 오다 · ~해 오다 · ~해지기 시작하다","c":"동사 て형 + くる","d":"① ~하고 (다시) 오다(買ってくる 사 오다, ちょっと見てくる 잠깐 보고 올게) ② 과거부터 지금까지 계속(ずっと練習してきた) ③ 변화가 나타나기 시작함(寒くなってきた·おなかがすいてきた). 말하는 사람 쪽으로 다가오는 방향이에요.","ex":[["コンビニでパンを買ってきます。","コンビニで パンを かって きます。","편의점에서 빵을 사 오겠습니다."],["だんだん暖かくなってきました。","だんだん あたたかく なって きました。","점점 따뜻해졌습니다."]],"cmp":[["～ていく","寒くなってきた는 지금까지 변해 온 것, 寒くなっていく는 지금부터 변해 갈 것"]],"qz":["三時間も歩いたので、さっきから足が痛く（　　）。","なってきました",["なっていきます","なっておきました","なってありました"],"さんじかんも あるいたので、さっきから あしが いたく なって きました。","세 시간이나 걸어서 아까부터 발이 아파지기 시작했습니다.","'さっきから' 지금까지 나타난 변화라 てくる. ていく는 앞으로의 변화라 さっきから와 안 맞고, ておく·てある는 변화에 못 써요."]},{"id":"b184","g":"te","lv":4,"p":"～ておく","m":"~해 두다 (미리 준비) · ~한 채로 두다","c":"동사 て형 + おく","d":"다음을 위해 미리 해 두는 것이 기본 뜻이에요. '그대로 두다'(窓は開けておいてください 창문은 열어 두세요)라는 뜻도 있어요. 회화에서는 ～とく로 줄여요(買っておく → 買っとく).","ex":[["お客さんが来る前に、部屋をそうじしておきます。","おきゃくさんが くる まえに、へやを そうじして おきます。","손님이 오기 전에 방을 청소해 두겠습니다."],["窓は開けておいてください。","まどは あけて おいて ください。","창문은 열어 두세요."]],"cmp":[["～てある","ておく는 '해 두는' 동작 자체(ジュースを冷やしておく), てある는 그 결과로 남은 상태(ジュースが冷やしてある)"]],"qz":["友だちが来るので、今からジュースを（　　）。","冷やしておきます",["冷やしてあります","冷えています","冷えておきます"],"ともだちが くるので、いまから ジュースを ひやして おきます。","친구가 오니까 지금부터 주스를 차게 해 두겠습니다.","친구가 오기 전에 今から 미리 해 두는 동작이라 ておく. てある는 이미 해 놓은 상태라 今から와 안 맞고, 冷える는 자동사라 を를 받지 못해요."]},{"id":"b185","g":"te","lv":4,"p":"～てみる","m":"~해 보다 (시험 삼아)","c":"동사 て형 + みる","d":"어떤지 알아보려고 한번 해 보는 거예요. 한국어 '~해 보다'와 거의 같아요. 보조 동사라 히라가나 みる로 쓰고 '보다(見る)'라는 뜻은 없어요. ～てみたい(~해 보고 싶다)도 자주 써요.","ex":[["この靴、はいてみてもいいですか。","この くつ、はいて みても いいですか。","이 신발 신어 봐도 됩니까?"],["一度、日本の着物を着てみたいです。","いちど、にほんの きものを きて みたいです。","한번 일본 기모노를 입어 보고 싶습니다."]],"qz":["初めての店なので、どんな味か一つ（　　）。","食べてみます",["食べてあります","食べておきます","食べていきます"],"はじめての みせなので、どんな あじか ひとつ たべて みます。","처음 가는 가게라서 어떤 맛인지 하나 먹어 보겠습니다.","'どんな味か' 알아보려고 해 보는 거라 てみる. てある는 を와 못 쓰고, ておく(미리 해 둠)·ていく(먹고 감)는 뜻이 안 맞아요."]},{"id":"b186","g":"change","lv":4,"p":"～くなる／～になる","m":"~해지다 · ~이 되다","c":"い형용사 い→く + なる / な형용사·명사 + に + なる","d":"상태가 바뀌는 것을 나타내요. いい는 よくなる (いくなる ✕). 동사의 변화는 ～ようになる를 써요.","ex":[["薬を飲んで、かぜがよくなりました。","くすりを のんで、かぜが よく なりました。","약을 먹고 감기가 나았습니다."],["弟は来年、高校生になります。","おとうとは らいねん、こうこうせいに なります。","남동생은 내년에 고등학생이 됩니다."]],"tag":"r5","cmp":[["～くする／～にする","なる는 저절로 바뀜(部屋が暗くなる), する는 누가 바꿈(部屋を暗くする)"]],"qz":["たくさん寝たので、気分が（　　）。","よくなりました",["いくなりました","いいになりました","よくしました"],"たくさん ねたので、きぶんが よく なりました。","푹 잤더니 기분이 좋아졌습니다.","いい는 よく + なる. いくなる·いいになる는 없는 꼴이고, 저절로 바뀐 거라 する가 아니라 なる예요."]},{"id":"b187","g":"change","lv":4,"p":"～にする（고르기·결정）","m":"~로 하다 (고르기·정하기)","c":"명사 + にする","d":"여럿 가운데 하나를 고르거나 정할 때 써요. 가게에서 주문할 때 '~로 할게요'가 ～にします예요. 할 일(동사)을 정할 때는 ～ことにする를 써요.","ex":[["飲み物は何にしますか。","のみものは なにに しますか。","음료는 무엇으로 하시겠습니까?"],["旅行は来月にしましょう。","りょこうは らいげつに しましょう。","여행은 다음 달로 합시다."]],"tag":"r5","cmp":[["～ことにする","명사를 고르면 にする(コーヒーにする), 할 일을 정하면 ことにする(行くことにする)"]],"qz":["デザートがたくさんありますね。私はプリン（　　）。","にします",["ことにします","になります","をします"],"デザートが たくさん ありますね。わたしは プリンに します。","디저트가 많네요. 저는 푸딩으로 할게요.","여럿 중 하나(명사)를 고르니 にする. ことにする는 동사 뒤에, になる는 '~이 되다', をする는 '~을 하다'라 안 맞아요."]},{"id":"b188","g":"change","lv":4,"p":"～くする／～にする（바꾸기）","m":"~하게 하다 · ~으로 만들다 (바꾸기)","c":"い형용사 い→く + する / な형용사·명사 + に + する","d":"누가 일부러 상태를 바꾸는 거예요. 한국어 '~하게 하다'와 같아요. 바꾸는 대상에는 を를 써요(部屋をきれいにする). いい는 よくする.","ex":[["テレビの音を小さくしてください。","テレビの おとを ちいさく して ください。","텔레비전 소리를 작게 해 주세요."],["子どもたちが教室をきれいにしました。","こどもたちが きょうしつを きれいに しました。","아이들이 교실을 깨끗하게 했습니다."]],"cmp":[["～くなる／～になる","する는 누가 바꿈(音を小さくする), なる는 저절로 바뀜(音が小さくなる)"]],"qz":["少し寒いので、部屋を（　　）ください。","暖かくして",["暖かくなって","暖かいにして","暖かくて"],"すこし さむいので、へやを あたたかく して ください。","조금 추우니까 방을 따뜻하게 해 주세요.","누가 일부러 바꾸는 거라 を + くする. なる는 저절로 바뀌어서 を를 못 받고, い형용사는 い→く로 바꿔요."]},{"id":"b189","g":"change","lv":4,"p":"～ようになる","m":"~하게 되다 (능력·습관의 변화)","c":"동사 사전형·가능형 + ようになる (안 하게 되다: ない형에서 ない → なくなる)","d":"전에는 못 하던(안 하던) 일을 하게 된 변화예요. 가능형과 함께 '~할 수 있게 되다'로 많이 써요. '안 하게 되다'는 食べなくなる처럼 ～なくなる가 기본이에요.","ex":[["日本語で電話ができるようになりました。","にほんごで でんわが できるように なりました。","일본어로 전화를 할 수 있게 되었습니다."],["弟は毎朝自分で起きるようになりました。","おとうとは まいあさ じぶんで おきるように なりました。","남동생은 매일 아침 스스로 일어나게 되었습니다."]],"cmp":[["～ことになる","ようになる는 능력·습관이 바뀜, ことになる는 남이 정해서 그렇게 됨(引っ越すことになった)"]],"qz":["毎日練習して、一人で自転車に乗れる（　　）。","ようになりました",["ことになりました","ことにしました","ことができました"],"まいにち れんしゅうして、ひとりで じてんしゃに のれるように なりました。","매일 연습해서 혼자 자전거를 탈 수 있게 되었습니다.","못 하던 일을 할 수 있게 된 변화라 ようになる. ことになる·ことにする는 정하는 일이라 가능형과 안 맞고, 乗れる에 ことができる를 또 붙이면 겹쳐요."]},{"id":"b190","g":"change","lv":4,"p":"～ようにする","m":"~하도록 하다 (노력·습관)","c":"동사 사전형·ない형 + ようにする","d":"그렇게 되도록 신경 쓰고 노력한다는 뜻이에요. 습관은 ～ようにしている, 부드러운 지시는 ～ようにしてください로 자주 써요.","ex":[["夜はスマホを見ないようにしています。","よるは スマホを みないように して います。","밤에는 스마트폰을 보지 않도록 하고 있습니다."],["明日は遅れないようにしてください。","あしたは おくれないように して ください。","내일은 늦지 않도록 해 주세요."]],"cmp":[["～ようになる","ようにする는 내가 노력함, ようになる는 결과로 변화가 생김"]],"qz":["体のために、なるべく毎日野菜を食べる（　　）。","ようにしています",["ようになっています","ことになっています","ようでした"],"からだの ために、なるべく まいにち やさいを たべるように して います。","건강을 위해 되도록 매일 채소를 먹도록 하고 있습니다.","'なるべく(되도록)' 스스로 노력하는 습관이라 ようにする. ようになる는 저절로 생긴 변화, ことになる는 남이 정한 규칙이에요."]},{"id":"b191","g":"comp","lv":4,"p":"～より～のほうが","m":"~보다 ~ 쪽이 (더)","c":"A + より + B + のほうが + 형용사 (동사는 사전형 + ほうが)","d":"둘을 비교해 B가 더하다는 뜻이에요. 한국어 '~가 더'처럼 쓰는데, B 쪽에는 보통 ほう(쪽)를 넣어요(冬のほうが). 순서를 바꿔 BのほうがAより～라고 해도 같은 뜻이에요.","ex":[["夏より冬のほうが好きです。","なつより ふゆの ほうが すきです。","여름보다 겨울을 더 좋아합니다."],["バスで行くより歩くほうが早いです。","バスで いくより あるく ほうが はやいです。","버스로 가는 것보다 걷는 쪽이 빠릅니다."]],"tag":"r5","cmp":[["～ほど～ない","より～のほうが는 B가 더함, AはBほど～ない는 A가 B만큼은 아님 (뜻은 비슷, 모양이 반대)"]],"qz":["この店はケーキよりパン（　　）おいしいです。","のほうが",["ほど","より","ぐらい"],"この みせは ケーキより パンの ほうが おいしいです。","이 가게는 케이크보다 빵이 더 맛있습니다.","'ケーキより'와 짝으로 더한 쪽에 のほうが. ほど는 뒤에 부정이 와야 하고, より를 또 쓰거나 ぐらい(같은 정도)는 より와 안 맞아요."]},{"id":"b192","g":"comp","lv":4,"p":"～と～とどちら","m":"~와 ~ 중 어느 쪽 (비교 질문)","c":"A + と + B + と + どちらが + 형용사 + ですか","d":"둘을 비교해서 물을 때 써요. 대답은 'Bのほうが～です', 둘 다 같으면 'どちらも～です'예요. 셋 이상에서 고를 때는 ～の中で何(どれ)が一番～를 써요. 회화에서는 どっち.","ex":[["コーヒーと紅茶とどちらがいいですか。","コーヒーと こうちゃと どちらが いいですか。","커피와 홍차 중 어느 쪽이 좋습니까?"],["山と海とどちらによく行きますか。","やまと うみと どちらに よく いきますか。","산과 바다 중 어느 쪽에 자주 갑니까?"]],"tag":"r5","qz":["田中さんは、犬とねこと（　　）が好きですか。","どちら",["どれ","何","どこ"],"たなかさんは、いぬと ねこと どちらが すきですか。","다나카 씨는 개와 고양이 중 어느 쪽을 좋아합니까?","둘을 비교해 물으니 どちら. どれ는 셋 이상에서 고를 때, 何·どこ는 'A와 B 중'을 묻는 말이 아니에요."]},{"id":"b193","g":"comp","lv":4,"p":"～たほうがいい","m":"~하는 편이 좋다 (조언)","c":"동사 た형 + ほうがいい / ない형 + ほうがいい","d":"상대에게 조언할 때 써요. 긍정은 기본적으로 た형을 써요(休んだほうがいい) — 시험에서는 た형이 정답이에요. 부정은 ない형 그대로(行かないほうがいい)예요.","ex":[["熱があるなら、早く寝たほうがいいですよ。","ねつが あるなら、はやく ねた ほうが いいですよ。","열이 있으면 일찍 자는 편이 좋아요."],["夜、一人で出かけないほうがいいです。","よる、ひとりで でかけない ほうが いいです。","밤에 혼자 나가지 않는 편이 좋습니다."]],"tag":"r5","qz":["かぜをひいているなら、今日は早く（　　）ほうがいいですよ。","帰った",["帰って","帰り","帰ろう"],"かぜを ひいて いるなら、きょうは はやく かえった ほうが いいですよ。","감기에 걸렸으면 오늘은 일찍 돌아가는 편이 좋아요.","조언은 た형 + ほうがいい. て형·ます형(帰り)·의지형(帰ろう)은 ほう 앞에 올 수 없어요."]},{"id":"b194","g":"comp","lv":4,"p":"～は～より","m":"~은 ~보다 (더) ~하다","c":"A + は + B + より + 형용사·동사","d":"A에 대해 'B보다 더 ~하다'라고 말해요. より가 한국어 '~보다'예요. 차이를 더 말하려면 ずっと(훨씬)·少し(조금)나 수량을 넣어요(Bよりずっと～).","ex":[["今日は昨日より暑いです。","きょうは きのうより あついです。","오늘은 어제보다 덥습니다."],["兄は私より三センチ背が高いです。","あには わたしより さんセンチ せが たかいです。","형은 저보다 3센티미터 키가 큽니다."]],"qz":["この川はあの川（　　）ずっと長いです。","より",["ほど","ほうが","しか"],"この かわは あの かわより ずっと ながいです。","이 강은 저 강보다 훨씬 깁니다.","'B보다'는 より. ほど·しか는 뒤에 부정이 와야 하고, ほうが는 더한 쪽(この川)에 붙여요."]},{"id":"b195","g":"comp","lv":4,"p":"～ほど～ない","m":"~만큼 ~하지 않다","c":"A + は + B + ほど + 부정형 (형용사·동사)","d":"'A는 B만큼은 아니다' — 결국 B 쪽이 더하다는 뜻이에요. 뒤에는 반드시 부정형이 와요(昨日ほど寒いです ✕).","ex":[["このテストは前のテストほど難しくなかったです。","この テストは まえの テストほど むずかしく なかったです。","이 시험은 지난번 시험만큼 어렵지 않았습니다."],["私は兄ほど速く走れません。","わたしは あにほど はやく はしれません。","저는 형만큼 빨리 달리지 못합니다."]],"cmp":[["～より～のほうが","今日は昨日ほど寒くない = 昨日のほうが今日より寒い"]],"qz":["今年の夏は、去年の夏ほど（　　）。","暑くありません",["暑いです","暑かったです","暑くなりました"],"ことしの なつは、きょねんの なつほど あつく ありません。","올해 여름은 작년 여름만큼 덥지 않습니다.","ほど 뒤에는 반드시 부정형이 와요. 暑いです·暑かったです·暑くなりました처럼 긍정이 오면 틀려요."]},{"id":"b196","g":"noun","lv":4,"p":"～たことがある","m":"~한 적이 있다 (경험)","c":"동사 た형 + ことがある (없다: ～たことがない)","d":"지금까지의 경험을 말해요. 어제·지난주처럼 가까운 한 번의 일에는 쓰지 않아요(昨日すしを食べたことがある ✕ → 昨日すしを食べました).","ex":[["日本の映画を見たことがありますか。","にほんの えいがを みた ことが ありますか。","일본 영화를 본 적이 있습니까?"],["私は一度も飛行機に乗ったことがありません。","わたしは いちども ひこうきに のった ことが ありません。","저는 한 번도 비행기를 탄 적이 없습니다."]],"tag":"r5","cmp":[["～ことがある(사전형)","た형 + ことがある는 '~한 적이 있다', 사전형 + ことがある는 '~할 때가 있다(가끔)'"]],"qz":["子どものころ、一度だけ富士山に（　　）ことがあります。","登った",["登る","登って","登ろう"],"こどもの ころ、いちどだけ ふじさんに のぼった ことが あります。","어렸을 때 딱 한 번 후지산에 오른 적이 있습니다.","'子どものころ' 한 경험이라 た형 + ことがある. 사전형이면 '(지금) 가끔 ~할 때가 있다'가 되어 안 맞고, て형·의지형은 こと 앞에 못 와요."]},{"id":"b197","g":"noun","lv":4,"p":"～こと（명사로 만들기）","m":"~하는 것 · ~한 것 (동사를 명사로)","c":"동사 보통형 / い형용사 ～い / な형용사 ～な + こと","d":"동사 등을 명사처럼 만들어 주어·목적어로 써요. ～ことができる·～ことにする·～たことがある·'趣味は～ことです'처럼 정해진 표현에는 꼭 こと를 써요 (の ✕).","ex":[["私の趣味は写真をとることです。","わたしの しゅみは しゃしんを とる ことです。","제 취미는 사진을 찍는 것입니다."],["毎日日記を書くことは大変です。","まいにち にっきを かく ことは たいへんです。","매일 일기를 쓰는 것은 힘듭니다."]],"cmp":[["～の(명사화)","見る·聞こえる·待つ처럼 눈앞의 동작을 보고 듣는 말 앞은 の(走るのが見える), 정해진 표현과 '~이다' 앞은 こと"]],"qz":["私の夢は、パイロットになる（　　）です。","こと",["の","もの","ところ"],"わたしの ゆめは、パイロットに なる ことです。","제 꿈은 파일럿이 되는 것입니다.","'夢は～ことです'처럼 '~이다' 앞은 こと. の는 이 자리에 쓰지 않고, もの는 물건, ところ는 '막 ~하려는 참'이라 안 맞아요."]},{"id":"b198","g":"noun","lv":4,"p":"～の（명사로 만들기）","m":"~하는 것 (동사를 명사로)","c":"동사 보통형 / い형용사 ～い / な형용사 ～な + の","d":"회화에서는 こと보다 の를 더 자주 써요(本を読むのが好き). 見る·見える·聞く·聞こえる·待つ처럼 눈앞에서 보고 듣는 동작 앞에서는 の만 써요(子どもが歌うのが聞こえる).","ex":[["私は料理を作るのが好きです。","わたしは りょうりを つくるのが すきです。","저는 요리를 만드는 것을 좋아합니다."],["となりの部屋で子どもが歌っているのが聞こえます。","となりの へやで こどもが うたって いるのが きこえます。","옆방에서 아이가 노래하는 것이 들립니다."]],"cmp":[["～こと","～ことができる·～ことにする·'趣味は～ことです'는 こと만 (読むのができる ✕)"]],"qz":["窓から、子どもたちが公園で遊んでいる（　　）が見えます。","の",["こと","もの","ため"],"まどから、こどもたちが こうえんで あそんで いるのが みえます。","창문으로 아이들이 공원에서 놀고 있는 것이 보입니다.","눈앞의 모습이 보이는 見える 앞은 の. こと는 보고 듣는 말 앞에 못 쓰고, もの·ため는 뜻이 안 맞아요."]},{"id":"b199","g":"noun","lv":4,"p":"～のだ／～んです","m":"~인 거예요 · ~거든요 (설명·사정 묻기)","c":"보통형 + んです (な형용사·명사는 ～なんです) · 글에서는 ～のだ·～のです","d":"사정을 설명하거나(遅れたんです 늦었거든요) 상대의 사정을 물을 때(どうしたんですか 무슨 일이에요?) 써요. 회화는 んです, 글은 のだ·のです. 사실만 전할 때 너무 많이 쓰면 어색해요.","ex":[["どうして昨日来なかったんですか。","どうして きのう こなかったんですか。","왜 어제 안 왔어요?"],["頭が痛かったんです。","あたまが いたかったんです。","머리가 아팠거든요."]],"cmp":[["～ます／～です","行きます는 사실만, 行くんです는 '사정이 있어서 그렇다'는 설명이 붙음"]],"qz":["遅れてすみません。電車が止まった（　　）。","んです",["です","ます","ことです"],"おくれて すみません。でんしゃが とまったんです。","늦어서 죄송합니다. 전철이 멈췄거든요.","늦은 사정을 설명하니 んです. 동사 た형 뒤에 です·ます를 바로 붙일 수 없고, ことです는 '~하는 것이다'라 뜻이 안 맞아요."]},{"id":"b200","g":"noun","lv":4,"p":"～かどうか","m":"~인지 어떤지 · ~인지 아닌지","c":"보통형 + かどうか (な형용사·명사는 だ를 빼고)","d":"예·아니요로 답하는 질문을 문장 속에 넣을 때 써요. 뒤에 分からない·知らない·聞く·考える가 자주 와요. 何·いつ 같은 의문사가 있으면 かどうか 대신 か만 써요(何時に来るか分からない).","ex":[["明日雨が降るかどうか分かりません。","あした あめが ふるか どうか わかりません。","내일 비가 올지 어떨지 모르겠습니다."],["この答えが正しいかどうか、先生に聞きましょう。","この こたえが ただしいか どうか、せんせいに ききましょう。","이 답이 맞는지 어떤지 선생님께 물어봅시다."]],"cmp":[["～か～ないか","뜻은 같아요: 行くかどうか = 行くか行かないか"]],"qz":["田中さんがパーティーに来る（　　）、分かりません。","かどうか",["ように","ために","のを"],"たなかさんが パーティーに くるか どうか、わかりません。","다나카 씨가 파티에 올지 어떨지 모르겠습니다.","올지 안 올지를 문장 속에 넣어 '모른다'고 하니 かどうか. ように·ために는 목적, のを는 分かる 앞에 안 맞아요."]},{"id":"b201","g":"noun","lv":4,"p":"～か～ないか","m":"~할지 안 할지 · ~했는지 안 했는지","c":"동사 사전형 + か + ない형 + か (과거: た형 + か + ～なかった + か)","d":"같은 동사의 긍정과 부정을 나란히 놓아 '어느 쪽인지'를 말해요. ～かどうか와 같은 뜻이고, 뒤에 決める·分からない·覚えていない가 자주 와요.","ex":[["パーティーに行くか行かないか、まだ決めていません。","パーティーに いくか いかないか、まだ きめて いません。","파티에 갈지 안 갈지 아직 정하지 않았습니다."],["ドアにかぎをかけたかかけなかったか、覚えていません。","ドアに かぎを かけたか かけなかったか、おぼえて いません。","문을 잠갔는지 안 잠갔는지 기억나지 않습니다."]],"qz":["この本を（　　）、明日までに決めてください。","買うか買わないか",["買うか買うか","買うと買わないと","買ったか買わないか"],"この ほんを かうか かわないか、あしたまでに きめて ください。","이 책을 살지 안 살지 내일까지 정해 주세요.","같은 동사의 긍정·부정을 か로 나란히 놓아요. 買うか買うか는 부정이 없고, と로는 못 잇고, 買ったか는 앞으로 정할 일과 시제가 안 맞아요."]},{"id":"b202","g":"noun","lv":4,"p":"～方","m":"~하는 법 · ~하는 방식","c":"동사 ます형(ます 뺀 꼴) + 方(かた)","d":"동사를 '방법'이라는 명사로 만들어요. 명사가 되므로 앞의 を는 の로 바꿔요(漢字を読む → 漢字の読み方). する동사는 명사 + の + しかた(料理のしかた).","ex":[["このカメラの使い方を教えてください。","この カメラの つかいかたを おしえて ください。","이 카메라 사용법을 가르쳐 주세요."],["駅までの行き方が分かりません。","えきまでの いきかたが わかりません。","역까지 가는 방법을 모르겠습니다."]],"qz":["先生に、この漢字の（　　）を聞きました。","読み方",["読む方","読んだ方","読むの方"],"せんせいに、この かんじの よみかたを ききました。","선생님께 이 한자 읽는 법을 여쭤봤습니다.","方는 ます형(読み)에 붙어 '~하는 법'이 돼요. 사전형·た형이나 の 뒤에는 붙지 않아요."]},{"id":"b203","g":"noun","lv":4,"p":"～すぎる","m":"너무 ~하다 (지나침)","c":"동사 ます형(ます 뺀 꼴) / い형용사 い를 뺀 꼴 / な형용사 + すぎる","d":"정도가 지나쳐서 좋지 않다는 느낌이에요. すぎる는 2그룹 동사처럼 활용해요(食べすぎた·高すぎます). いい는 よすぎる (いすぎる ✕).","ex":[["この問題は難しすぎて、分かりません。","この もんだいは むずかしすぎて、わかりません。","이 문제는 너무 어려워서 모르겠습니다."],["ゆうべ、テレビを見すぎました。","ゆうべ、テレビを みすぎました。","어젯밤에 텔레비전을 너무 많이 봤습니다."]],"qz":["このかばんは（　　）、私には買えません。","高すぎて",["高いすぎて","高くすぎて","高すぎって"],"この かばんは たかすぎて、わたしには かえません。","이 가방은 너무 비싸서 저는 살 수 없습니다.","い형용사는 い를 빼고 すぎる(高すぎる). すぎる는 2그룹처럼 て형이 すぎて예요."]},{"id":"b204","g":"noun","lv":4,"p":"～やすい","m":"~하기 쉽다 · ~하기 편하다 · 잘 ~하다","c":"동사 ます형(ます 뺀 꼴) + やすい","d":"그렇게 하기 쉽다(편하다)는 뜻이에요. '쉽게 그렇게 된다'는 뜻으로 좋지 않은 일에도 써요(かぜをひきやすい 감기에 잘 걸린다). い형용사처럼 활용해요(読みやすくない).","ex":[["この辞書は字が大きくて見やすいです。","この じしょは じが おおきくて みやすいです。","이 사전은 글자가 커서 보기 편합니다."],["冬はかぜをひきやすいです。","ふゆは かぜを ひきやすいです。","겨울에는 감기에 걸리기 쉽습니다."]],"cmp":[["～にくい","반대말: 読みやすい(읽기 쉽다) ↔ 読みにくい(읽기 어렵다)"]],"qz":["このペンは細い字もきれいに書けて、とても（　　）です。","書きやすい",["書きにくい","書くやすい","書いてやすい"],"この ペンは ほそい じも きれいに かけて、とても かきやすいです。","이 펜은 가는 글씨도 예쁘게 써져서 아주 쓰기 편합니다.","잘 써지니 ます형 + やすい. 書きにくい는 반대 뜻이고, やすい는 사전형·て형 뒤에 붙지 않아요."]},{"id":"b205","g":"noun","lv":4,"p":"～にくい","m":"~하기 어렵다 · 잘 ~하지 않다","c":"동사 ます형(ます 뺀 꼴) + にくい","d":"그렇게 하기가 힘들다(불편하다)는 뜻이에요. '쉽게 그렇게 되지 않는다'(割れにくい 잘 안 깨진다)에도 써요. 내용이 어려운 것은 難しい를 써요(難しい本).","ex":[["この肉はかたくて食べにくいです。","この にくは かたくて たべにくいです。","이 고기는 질겨서 먹기 힘듭니다."],["このコップは落としても割れにくいです。","この コップは おとしても われにくいです。","이 컵은 떨어뜨려도 잘 깨지지 않습니다."]],"qz":["この道は石が多くて、（　　）です。","歩きにくい",["歩きやすい","歩くにくい","歩いてにくい"],"この みちは いしが おおくて、あるきにくいです。","이 길은 돌이 많아서 걷기 힘듭니다.","돌이 많아 걷기 힘드니 ます형 + にくい. 歩きやすい는 반대 뜻이고, にくい는 사전형·て형 뒤에 붙지 않아요."]},{"id":"b206","g":"noun","lv":4,"p":"～がする","m":"(소리·냄새·맛·느낌이) 나다 · 들다","c":"音·声·におい·味·気 + がする","d":"귀·코·혀·몸으로 느낀 것을 말해요. 한국어는 '나다'지만 일본어는 する를 써요. 気がする(~한 느낌이 들다)도 자주 나와요(だれか来たような気がする).","ex":[["台所からいいにおいがします。","だいどころから いい においが します。","부엌에서 좋은 냄새가 납니다."],["外で大きな音がしました。","そとで おおきな おとが しました。","밖에서 큰 소리가 났습니다."]],"qz":["このスープは、少しレモンの味（　　）。","がします",["をします","がなります","がいます"],"この スープは、すこし レモンの あじが します。","이 수프는 조금 레몬 맛이 납니다.","맛·냄새·소리가 '나다'는 が + する. を로 바꾸거나 なる·いる를 쓰지 않아요."]},{"id":"b207","g":"noun","lv":4,"p":"～ずに／～ないで","m":"~하지 않고 · ~하지 말고","c":"동사 ない형 + で / ない형(ない를 뺀 꼴) + ずに (する → せずに)","d":"'~하지 않은 채로 다른 일을 한다'는 뜻이에요. ずに는 글·딱딱한 말, ないで는 회화에 많아요. する는 しずに가 아니라 せずに예요. ～ないでください(~하지 마세요)는 ずに로 바꿀 수 없어요.","ex":[["今朝は何も食べずに家を出ました。","けさは なにも たべずに いえを でました。","오늘 아침에는 아무것도 먹지 않고 집을 나왔습니다."],["辞書を使わないで読んでみてください。","じしょを つかわないで よんで みて ください。","사전을 쓰지 말고 읽어 보세요."]],"cmp":[["～なくて","ないで는 '~하지 않고(그 상태로)', なくて는 이유 '~하지 않아서'(バスが来なくて困った)"]],"qz":["宿題を（　　）、遊びに行ってはいけません。","せずに",["しずに","さずに","しなくて"],"しゅくだいを せずに、あそびに いっては いけません。","숙제를 하지 않고 놀러 가면 안 됩니다.","する의 ずに 꼴은 せずに예요(しずに ✕). しなくて는 '안 해서'라는 이유라 뜻이 안 맞아요."]},{"id":"b208","g":"noun","lv":4,"p":"～について","m":"~에 대해서 · ~에 관해서","c":"명사 + について (명사를 꾸밀 때: ～についての + 명사)","d":"이야기·생각·조사의 주제를 나타내요. 뒤에 話す·聞く·調べる·書く가 자주 와요. 명사를 꾸밀 때는 についての(日本についての本).","ex":[["夏休みの計画について話しましょう。","なつやすみの けいかくに ついて はなしましょう。","여름방학 계획에 대해 이야기합시다."],["この町の歴史についての本を読みました。","この まちの れきしに ついての ほんを よみました。","이 마을의 역사에 대한 책을 읽었습니다."]],"qz":["明日の授業では、日本のお祭り（　　）調べます。","について",["によって","によると","にとって"],"あしたの じゅぎょうでは、にほんの おまつりに ついて しらべます。","내일 수업에서는 일본 축제에 대해 조사합니다.","조사하는 주제라 について. によると는 들은 정보의 출처, によって는 '~에 따라', にとって는 '~에게 있어'라 안 맞아요."]},{"id":"b209","g":"noun","lv":4,"p":"～によって／～によると","m":"~에 따라 (다르다) · ~에 의해 · ~에 따르면 (정보 출처)","c":"명사 + によって / 명사 + によると","d":"によって는 '~에 따라 다르다'(人によって違う)와 수동문의 '~에 의해'로 써요. によると는 들은 정보의 출처이고, 문장 끝에 ～そうだ·～らしい가 짝으로 와요.","ex":[["国によって、あいさつのしかたが違います。","くにに よって、あいさつの しかたが ちがいます。","나라에 따라 인사하는 방법이 다릅니다."],["ニュースによると、明日は雪が降るそうです。","ニュースに よると、あしたは ゆきが ふるそうです。","뉴스에 따르면 내일은 눈이 온다고 합니다."]],"cmp":[["～そうだ（전해 들음）","によると는 출처를 앞에, そうだ·らしい는 문장 끝에 — 天気予報によると、雨が降るそうです처럼 짝으로 써요"]],"qz":["先生の話（　　）、来週テストがあるそうです。","によると",["によって","について","にとって"],"せんせいの はなしに よると、らいしゅう テストが あるそうです。","선생님 말씀에 따르면 다음 주에 시험이 있다고 합니다.","끝의 そうです와 짝으로 정보의 출처를 말하니 によると. によって는 '~에 따라(다르다)', について는 주제예요."]},{"id":"b210","g":"short","lv":4,"p":"～ちゃう／～じゃう","m":"~해 버리다 (～てしまう의 회화 줄임)","c":"～てしまう → ～ちゃう / ～でしまう → ～じゃう (과거: ～ちゃった·～じゃった)","d":"～てしまう를 친한 사이에서 줄여 말하는 꼴이에요. て형이 て로 끝나면 ちゃう(食べちゃう), で로 끝나면 じゃう(読んじゃう·遊んじゃう)가 돼요.","ex":[["あ、ケーキ、全部食べちゃった。","あ、ケーキ、ぜんぶ たべちゃった。","아, 케이크 다 먹어 버렸다."],["この本、一日で読んじゃった。","この ほん、いちにちで よんじゃった。","이 책 하루 만에 다 읽어 버렸어."]],"cmp":[["～ちゃ(～ては)","ちゃう는 '~해 버리다'(食べちゃった), ちゃ는 '~하면 (안 돼)'(食べちゃだめ)"]],"qz":["あ、お兄ちゃんのジュース、全部（　　）。","飲んじゃった",["飲んちゃった","飲みちゃった","飲んじゃ"],"あ、おにいちゃんの ジュース、ぜんぶ のんじゃった。","아, 형 주스를 다 마셔 버렸다.","飲んでしまった의 줄임이라 で→じゃ로 飲んじゃった. ちゃった는 て로 끝날 때 꼴이고, 飲んじゃ는 '마시면'이라 문장이 끝나지 않아요."]},{"id":"b211","g":"short","lv":4,"p":"～てる","m":"~하고 있어 · ~해 있어 (～ている의 회화 줄임)","c":"～ている → ～てる / ～でいる → ～でる (정중: ～ています → ～てます)","d":"～ている에서 い가 빠진 회화 꼴이에요. 뜻은 ～ている와 같아요(진행·상태). 住んでいる처럼 で로 끝나면 住んでる가 돼요.","ex":[["今、何してるの？","いま、なに してるの？","지금 뭐 하고 있어?"],["キムさんはどこに住んでるの？","キムさんは どこに すんでるの？","김 씨는 어디에 살아?"]],"qz":["弟は今、部屋でマンガを（　　）よ。","読んでる",["読んてる","読みてる","読んどく"],"おとうとは いま、へやで マンガを よんでるよ。","남동생은 지금 방에서 만화를 읽고 있어.","読んでいる의 회화 줄임은 読んでる. 読んどく는 '읽어 둘게'라 今·弟와 안 맞고, 読んてる·読みてる는 없는 꼴이에요."]},{"id":"b212","g":"short","lv":4,"p":"～とく","m":"~해 둘게 · ~해 둬 (～ておく의 회화 줄임)","c":"～ておく → ～とく / ～でおく → ～どく (～といて·～といた)","d":"～ておく에서 てお가 と로 줄어든 꼴이에요. 読んでおく처럼 で로 끝나면 どく가 돼요(読んどく). 부탁할 때는 ～といて(해 둬).","ex":[["明日の分も買っとくね。","あしたの ぶんも かっとくね。","내일 것도 사 둘게."],["その本、机の上に置いといて。","その ほん、つくえの うえに おいといて。","그 책 책상 위에 놓아 둬."]],"qz":["この本、明日までに（　　）よ。","読んどく",["読んとく","読んどいた","読むどく"],"この ほん、あしたまでに よんどくよ。","이 책, 내일까지 읽어 둘게.","読んでおく의 줄임은 で로 끝나서 読んどく. 読んとく·読むどく는 틀린 꼴, 読んどいた는 과거라 明日までに와 안 맞아요."]},{"id":"b213","g":"short","lv":4,"p":"～なくちゃ／～なきゃ","m":"~해야 해 (회화)","c":"～なくては → ～なくちゃ / ～なければ → ～なきゃ (ない형에서 ない를 뺀 꼴 + なくちゃ·なきゃ)","d":"～なくてはいけない·～なければならない의 회화 줄임말이에요. 뒤의 いけない·ならない는 보통 말하지 않아요(もう帰らなきゃ). 혼잣말에도 자주 써요.","ex":[["もう九時だ。早く寝なくちゃ。","もう くじだ。はやく ねなくちゃ。","벌써 9시다. 빨리 자야지."],["明日までにレポートを出さなきゃ。","あしたまでに レポートを ださなきゃ。","내일까지 리포트를 내야 해."]],"qz":["もう八時だ。急いで学校に（　　）。","行かなきゃ",["行きなきゃ","行くなきゃ","行かなくても"],"もう はちじだ。いそいで がっこうに いかなきゃ。","벌써 8시다. 서둘러 학교에 가야 해.","ない형(行か) + なきゃ로 '~해야 해'. 行き·行く에는 붙지 않고, 行かなくても는 '안 가도'라 急いで와 안 맞아요."]},{"id":"b214","g":"short","lv":4,"p":"～ちゃ（～ては）","m":"~하면 (안 돼) (～ては의 회화 줄임)","c":"～ては → ～ちゃ / ～では → ～じゃ (～ちゃだめ·～ちゃいけない)","d":"～てはいけない(~하면 안 된다)를 줄여 말할 때 많이 나와요: 見てはいけない → 見ちゃいけない·見ちゃだめ. 遊んでは처럼 で로 끝나면 じゃ가 돼요(遊んじゃだめ).","ex":[["ここで遊んじゃだめだよ。","ここで あそんじゃ だめだよ。","여기서 놀면 안 돼."],["まだ食べちゃいけないよ。","まだ たべちゃ いけないよ。","아직 먹으면 안 돼."]],"cmp":[["～ちゃう","ちゃ(～ては)는 '~하면 (안 돼)', ちゃう(～てしまう)는 '~해 버리다'"]],"qz":["あぶないから、この川で（　　）だめだよ。","泳いじゃ",["泳いちゃ","泳ぎちゃ","泳いじゃう"],"あぶないから、この かわで およいじゃ だめだよ。","위험하니까 이 강에서 수영하면 안 돼.","泳いでは의 줄임이라 で→じゃ로 泳いじゃ. 泳いちゃ·泳ぎちゃ는 틀린 꼴, 泳いじゃう는 '헤엄쳐 버리다'라 だめ 앞에 못 와요."]},{"id":"b215","g":"demo","lv":4,"p":"この・その・あの・どの","m":"이 · 그 · 저 · 어느 (+ 명사)","c":"명사 앞 (この本·その人·どの電車)","d":"こ는 말하는 사람 가까이, そ는 듣는 사람 가까이 또는 앞에서 말한 것, あ는 둘 다에게서 먼 것 또는 둘 다 아는 것, ど는 질문이에요. この·その는 혼자 쓰지 못하고 반드시 명사 앞에 와요(このは ✕ → これは).","ex":[["この傘はだれのですか。","この かさは だれのですか。","이 우산은 누구 것입니까?"],["どの電車に乗ればいいですか。","どの でんしゃに のれば いいですか。","어느 전철을 타면 됩니까?"]],"cmp":[["これ・それ・あれ・どれ","これ는 혼자 쓰는 말(これは本です), この는 명사 앞(この本は～)"]],"qz":["（　　）かばんは、誕生日に母にもらいました。","この",["これ","ここ","こう"],"この かばんは、たんじょうびに ははに もらいました。","이 가방은 생일에 엄마에게 받았습니다.","かばん 같은 명사 바로 앞에는 この. これ·ここ는 혼자 쓰는 말이라 명사 앞에 못 오고, こう는 동사 앞에 써요."]},{"id":"b216","g":"demo","lv":4,"p":"こんな・そんな・あんな・どんな","m":"이런 · 그런 · 저런 · 어떤 (+ 명사)","c":"명사 앞 (こんな本·どんな人) / ～に를 붙이면 '이렇게(나)'(こんなに)","d":"모양·성질을 가리켜요. 거리 규칙은 この·その·あの·どの와 같고, そんな는 상대가 방금 한 말을 받을 때도 써요(そんなことないよ 그렇지 않아). どんな는 '어떤'을 묻는 말이에요.","ex":[["どんな音楽が好きですか。","どんな おんがくが すきですか。","어떤 음악을 좋아합니까?"],["そんな話は聞いたことがありません。","そんな はなしは きいた ことが ありません。","그런 이야기는 들은 적이 없습니다."]],"qz":["新しい英語の先生は（　　）人ですか。やさしいですか。","どんな",["どう","どれ","どこ"],"あたらしい えいごの せんせいは どんな ひとですか。やさしいですか。","새 영어 선생님은 어떤 사람입니까? 상냥합니까?","사람(명사)의 성질을 물으니 명사 앞에 쓰는 どんな. どう는 동사·형용사 앞, どれ·どこ는 혼자 쓰는 말이라 명사 앞에 못 와요."]},{"id":"b217","g":"demo","lv":4,"p":"こう・そう・ああ・どう","m":"이렇게 · 그렇게 · 저렇게 · 어떻게","c":"동사·형용사 앞 (こう書く·どうする)","d":"방법·모양을 가리키는 말이에요. そう는 상대 말에 맞장구칠 때 많이 써요(そうですね·そうですか). ああ는 둘 다 아는 일을 가리킬 때 주로 써요. どう는 どうですか(어때요)·どうしますか(어떻게 할래요).","ex":[["この漢字はこう書きます。","この かんじは こう かきます。","이 한자는 이렇게 씁니다."],["これからどうしますか。","これから どう しますか。","이제 어떻게 할 겁니까?"]],"qz":["よく見てください。はしを（　　）持ちます。","こう",["この","こんな","これ"],"よく みて ください。はしを こう もちます。","잘 보세요. 젓가락을 이렇게 잡습니다.","동사(持ちます) 앞에서 방법을 가리키니 こう(이렇게). この·こんな는 명사 앞에 쓰고, これ는 を 뒤에 또 올 수 없어요."]},{"id":"b218","g":"demo","lv":4,"p":"こちら・そちら・あちら・どちら","m":"이쪽 · 그쪽 · 저쪽 · 어느 쪽 (정중)","c":"혼자 쓰는 말 (こちらは～·どちらですか)","d":"방향을 가리키지만 ここ·これ·この人의 정중한 말로도 써요(こちらは田中さんです 이분은 다나카 씨입니다). どちら는 '어느 쪽'(둘 중 고르기)과 どこ의 정중한 말 두 가지예요. 회화에서는 こっち·そっち·あっち·どっち.","ex":[["こちらは山田さんです。","こちらは やまださんです。","이분은 야마다 씨입니다."],["お手洗いはどちらですか。","おてあらいは どちらですか。","화장실은 어느 쪽입니까?"]],"qz":["お手洗いは（　　）です。あそこの青いドアですよ。","あちら",["こちら","そちら","どちら"],"おてあらいは あちらです。あそこの あおい ドアですよ。","화장실은 저쪽입니다. 저기 파란 문이에요.","'あそこ(저기)'를 가리키니 あちら. こちら는 말하는 사람 가까이, そちら는 듣는 사람 가까이, どちら는 묻는 말이에요."]},{"id":"b219","g":"demo","lv":4,"p":"どういう／どうやって／どうして","m":"어떤 (내용) · 어떻게 (방법) · 왜 (이유)","c":"どういう + 명사 / どうやって + 동사 / どうして + 문장","d":"どういう는 '어떤 내용·뜻의'(これはどういう意味ですか 이건 무슨 뜻이에요?), どうやって는 '어떤 방법으로', どうして는 '왜'(= なぜ)예요. どうして로 물으면 대답은 ～から·～んです로 해요.","ex":[["駅までどうやって行きますか。","えきまで どうやって いきますか。","역까지 어떻게 갑니까?"],["どうして日本語を勉強しているんですか。","どうして にほんごを べんきょうして いるんですか。","왜 일본어를 공부하고 있어요?"]],"qz":["先生、この言葉は（　　）意味ですか。","どういう",["どうやって","どうして","どう"],"せんせい、この ことばは どういう いみですか。","선생님, 이 말은 무슨 뜻입니까?","명사(意味) 앞에서 내용을 물으니 どういう. どうやって는 방법, どうして는 이유를 묻고, どう는 명사 앞에 못 와요."]},{"id":"b220","g":"keigo","lv":4,"p":"お～ください","m":"~해 주십시오 (정중한 부탁·권함)","c":"お + 동사 ます형(ます 뺀 꼴) + ください / ご + 한자어 명사 + ください","d":"～てください보다 정중해서 가게·안내 방송에서 많이 들어요(お待ちください·お入りください). 한자어는 ご(ご注意ください). 見る·いる처럼 ます형이 한 글자인 동사에는 쓰지 않아요(お見ください ✕ → ご覧ください).","ex":[["こちらにお名前をお書きください。","こちらに おなまえを おかき ください。","이쪽에 성함을 써 주십시오."],["ドアが閉まります。ご注意ください。","ドアが しまります。ごちゅうい ください。","문이 닫힙니다. 주의해 주십시오."]],"qz":["名前を呼ぶまで、こちらで少し（　　）ください。","お待ち",["お待って","お待つ","待ち"],"なまえを よぶまで、こちらで すこし おまち ください。","이름을 부를 때까지 이쪽에서 잠시 기다려 주십시오.","お + ます형(待ち) + ください. て형·사전형에는 お를 붙이지 않고, お 없이 待ちください라고도 하지 않아요."]},{"id":"b221","g":"keigo","lv":4,"p":"お～になる（존경）","m":"~하시다 (상대의 행동을 높임)","c":"お + 동사 ます형(ます 뺀 꼴) + になる / ご + 한자어 명사 + になる","d":"윗사람·손님의 행동을 높여요(お帰りになる 돌아가시다). 내 행동에는 쓰지 않아요. 見る·来る·いる처럼 특별한 존경어가 있는 동사는 그 말을 써요(ご覧になる·いらっしゃる).","ex":[["部長は何時ごろお戻りになりますか。","ぶちょうは なんじごろ おもどりに なりますか。","부장님은 몇 시쯤 돌아오십니까?"],["この本をお読みになりましたか。","この ほんを およみに なりましたか。","이 책을 읽으셨습니까?"]],"cmp":[["お～する","お～になる는 상대의 행동(존경), お～する는 나의 행동(겸양) — 先生がお待ちになる / 私がお待ちする"]],"qz":["田中先生は、もう家に（　　）か。","お帰りになりました",["お帰りしました","お帰りいたしました","お帰りにしました"],"たなかせんせいは、もう いえに おかえりに なりましたか。","다나카 선생님은 벌써 댁에 돌아가셨습니까?","선생님의 행동을 높이니 존경 お～になる. お～する·お～いたす는 내 행동을 낮추는 겸양이라 선생님께 쓰면 틀려요."]},{"id":"b222","g":"keigo","lv":4,"p":"お～する／お～いたす（겸양）","m":"(제가) ~해 드리다 (나를 낮춤)","c":"お + 동사 ます형(ます 뺀 꼴) + する·いたす / ご + 한자어 명사 + する·いたす","d":"내가 상대를 위해 하는 행동을 낮춰 말해요. いたす를 쓰면 する보다 더 공손해요. 상대와 관계있는 행동(들어 드리다·안내해 드리다)에 쓰고, 나 혼자 하는 일에는 쓰지 않아요.","ex":[["重そうですね。お持ちしましょうか。","おもそうですね。おもち しましょうか。","무거워 보이네요. 들어 드릴까요?"],["会議室へご案内いたします。","かいぎしつへ ごあんない いたします。","회의실로 안내해 드리겠습니다."]],"cmp":[["お～になる","お～する는 나의 행동(겸양), お～になる는 상대의 행동(존경)"]],"qz":["先生、雨が降っていますね。私のかさを（　　）。","お貸ししましょうか",["お貸しになりましょうか","ご貸ししましょうか","お借りしましょうか"],"せんせい、あめが ふって いますね。わたしの かさを おかし しましょうか。","선생님, 비가 오네요. 제 우산을 빌려 드릴까요?","내가 선생님께 해 드리는 일이라 겸양 お～する. お～になる는 상대의 행동, 貸す 같은 고유어는 ご가 아니라 お, 借りる는 '빌리다'예요."]},{"id":"b223","g":"keigo","lv":4,"p":"특별 존경어 (いらっしゃる·なさる·くださる·ご覧になる·ご存じだ)","m":"상대를 높이는 특별한 말","c":"いる·行く·来る → いらっしゃる / する → なさる / くれる → くださる / 見る → ご覧になる / 知っている → ご存じだ","d":"규칙(お～になる) 대신 완전히 다른 말을 써요. いらっしゃる·なさる·くださる는 ます 앞에서 る가 い로 바뀌어요(いらっしゃいます·なさいます·くださいます). 言う → おっしゃる, 食べる·飲む → 召し上がる도 함께 외워요.","ex":[["社長は今、会議室にいらっしゃいます。","しゃちょうは いま、かいぎしつに いらっしゃいます。","사장님은 지금 회의실에 계십니다."],["山田先生をご存じですか。","やまだせんせいを ごぞんじですか。","야마다 선생님을 아십니까?"]],"cmp":[["특별 겸양어","같은 '가다·오다·있다'라도 상대면 いらっしゃる, 나면 参る·おる"]],"qz":["校長先生は、もうこの写真を（　　）か。","ご覧になりました",["拝見しました","ご覧しました","お見になりました"],"こうちょうせんせいは、もう この しゃしんを ごらんに なりましたか。","교장 선생님은 벌써 이 사진을 보셨습니까?","교장 선생님이 보는 것이라 존경어 ご覧になる. 拝見する는 내가 볼 때 쓰는 겸양어이고, ご覧する·お見になる는 없는 말이에요."]},{"id":"b224","g":"keigo","lv":4,"p":"특별 겸양어 (いただく·おる·いたす·参る·申す)","m":"나를 낮추는 특별한 말","c":"もらう·食べる·飲む → いただく / いる → おる / する → いたす / 行く·来る → 参る / 言う → 申す","d":"내 행동을 낮춰서 상대를 높여요. ～ている는 ～ておる가 되어 ～ております(お待ちしております)로 써요. 見る → 拝見する, 会う → お目にかかる, 訪ねる·聞く → 伺う도 함께 외워요.","ex":[["はじめまして。キムと申します。","はじめまして。キムと もうします。","처음 뵙겠습니다. 김이라고 합니다."],["明日の十時にそちらへ参ります。","あしたの じゅうじに そちらへ まいります。","내일 10시에 그쪽으로 찾아가겠습니다."]],"cmp":[["특별 존경어","상대가 오면 いらっしゃる, 내가 가면 参る / 상대가 말하면 おっしゃる, 내가 말하면 申す"]],"qz":["先生、おかしをありがとうございます。私も一つ（　　）。","いただきます",["めしあがります","いらっしゃいます","くださいます"],"せんせい、おかしを ありがとう ございます。わたしも ひとつ いただきます。","선생님, 과자 감사합니다. 저도 하나 먹겠습니다.","'私も' 먹는 것이라 겸양어 いただく. めしあがる는 상대가 먹을 때 쓰는 존경어이고, いらっしゃる·くださる는 '계시다·주시다'예요."]},{"id":"b225","g":"keigo","lv":4,"p":"ございます（정중어）","m":"있습니다 · ~입니다 (아주 정중)","c":"あります → ございます / ～です → ～でございます","d":"말 전체를 아주 공손하게 하는 말이에요. 가게·호텔 직원이 손님에게 많이 써요. ありがとうございます·おはようございます의 ございます도 같은 말이에요. 누구의 행동을 높이는 말(존경어)은 아니에요.","ex":[["お手洗いは二階にございます。","おてあらいは にかいに ございます。","화장실은 2층에 있습니다."],["こちらが新しいメニューでございます。","こちらが あたらしい メニューで ございます。","이쪽이 새 메뉴입니다."]],"qz":["お客様、エレベーターはあちらに（　　）。","ございます",["いらっしゃいます","おります","でございます"],"おきゃくさま、エレベーターは あちらに ございます。","손님, 엘리베이터는 저쪽에 있습니다.","물건이 '있습니다'의 아주 정중한 말은 ございます. いらっしゃる·おる는 사람에게 쓰고, でございます는 '~입니다'라 に 뒤에 안 와요."]},{"id":"b226","g":"sup","lv":4,"p":"あげる／くれる／もらう","m":"주다 (내가 남에게) · 주다 (남이 나에게) · 받다","c":"A は B に あげる / B が (私に) くれる / 私は B に(から) もらう","d":"한국어는 모두 '주다'지만, 받는 사람이 나(또는 내 가족)면 くれる, 그 밖이면 あげる예요. もらう는 받는 사람이 주어예요. 윗사람과 주고받을 때는 差し上げる·くださる·いただく를 써요.","ex":[["私は田中さんにおみやげをあげました。","わたしは たなかさんに おみやげを あげました。","저는 다나카 씨에게 선물을 주었습니다."],["誕生日に父が時計をくれました。","たんじょうびに ちちが とけいを くれました。","생일에 아버지가 시계를 주셨습니다."]],"tag":"sup","cmp":[["～てあげる／～てくれる／～てもらう","물건 대신 '행동'을 주고받을 때는 て형 + あげる·くれる·もらう"]],"qz":["誕生日に、友だちが私にかわいいペンを（　　）。","くれました",["あげました","もらいました","いただきました"],"たんじょうびに、ともだちが わたしに かわいい ペンを くれました。","생일에 친구가 나에게 귀여운 펜을 주었습니다.","주는 사람(友だち)이 주어이고 받는 사람이 '나'라 くれる. あげる는 내가 남에게, もらう·いただく는 받는 사람이 주어일 때 써요."]},{"id":"b227","g":"sup","lv":4,"p":"～ていただけませんか","m":"~해 주실 수 없겠습니까? (아주 정중한 부탁)","c":"동사 て형 + いただけませんか (いただく의 가능형 + ませんか)","d":"윗사람이나 처음 보는 사람에게 부탁할 때 써요. 대체로 ～てください → ～てくれませんか → ～てもらえませんか → ～ていただけませんか 순으로 더 정중해져요. 친구에게는 너무 딱딱해요.","ex":[["すみません、もう一度言っていただけませんか。","すみません、もう いちど いって いただけませんか。","죄송합니다만, 한 번 더 말씀해 주실 수 없겠습니까?"],["私の作文を見ていただけませんか。","わたしの さくぶんを みて いただけませんか。","제 작문을 봐 주실 수 없겠습니까?"]],"tag":"sup","cmp":[["～てくださいませんか","둘 다 아주 정중해요. くださいませんか는 상대가 주어(해 주시겠어요?), いただけませんか는 내가 받는 쪽(해 받을 수 있을까요?)"]],"qz":["すみません、駅へ行く道を（　　）。","教えていただけませんか",["教えていただきませんか","教えてさしあげませんか","教えてあげませんか"],"すみません、えきへ いく みちを おしえて いただけませんか。","실례합니다, 역에 가는 길을 가르쳐 주실 수 없겠습니까?","정중한 부탁은 いただく의 가능형 いただける로 いただけませんか. いただきませんか는 '받지 않을래요?', あげる·さしあげる는 내가 해 줄 때 말이에요."]},{"id":"b228","g":"sup","lv":4,"p":"～てほしい","m":"(남이) ~해 주면 좋겠다 · ~해 주길 바란다","c":"사람 + に + 동사 て형 + ほしい (하지 않기를: ない형 + でほしい)","d":"다른 사람이 해 주기를 바라는 마음이에요. 바라는 상대에는 に를 써요. 윗사람에게 직접 말하면 실례일 수 있어서 그때는 ～ていただけませんか를 써요.","ex":[["友だちにもっと早く来てほしいです。","ともだちに もっと はやく きて ほしいです。","친구가 더 일찍 와 주면 좋겠습니다."],["このことはだれにも言わないでほしいです。","この ことは だれにも いわないで ほしいです。","이 일은 아무에게도 말하지 않으면 좋겠습니다."]],"tag":"sup","cmp":[["～たい","たい는 내가 하고 싶음(行きたい), てほしい는 남이 해 주길 바람(来てほしい)"]],"qz":["日曜日は、母に私の好きなカレーを作って（　　）です。","ほしい",["ほしがる","あげる","くれる"],"にちようびは、ははに わたしの すきな カレーを つくって ほしいです。","일요일에는 엄마가 내가 좋아하는 카레를 만들어 주면 좋겠습니다.","엄마(に)가 해 주길 내가 바라니 てほしい. ほしがる는 남의 바람이고, あげる·くれる 같은 동사 뒤에는 です를 바로 못 붙여요."]},{"id":"b229","g":"sup","lv":4,"p":"～たがる","m":"(남이) ~하고 싶어 하다","c":"동사 ます형(ます 뺀 꼴) + たがる (지금 모습: ～たがっている)","d":"나 아닌 사람의 희망을 겉모습으로 보고 말할 때 써요. 일본어는 남의 마음을 단정하지 않아서 弟は行きたいです보다 弟は行きたがっています가 자연스러워요. 1그룹 동사처럼 활용해요(行きたがらない). ほしい는 ほしがる.","ex":[["弟は新しいゲームを買いたがっています。","おとうとは あたらしい ゲームを かいたがって います。","남동생은 새 게임을 사고 싶어 합니다."],["うちの犬はいつも散歩に行きたがります。","うちの いぬは いつも さんぽに いきたがります。","우리 집 개는 늘 산책 가고 싶어 합니다."]],"tag":"sup","cmp":[["～たい","たい는 나의 희망(私は行きたい), たがる는 남의 희망(弟は行きたがっている)"]],"qz":["妹はいつも私の服を（　　）。","着たがります",["着たいです","着てほしいです","着たいがります"],"いもうとは いつも わたしの ふくを きたがります。","여동생은 늘 내 옷을 입고 싶어 합니다.","내가 아닌 여동생의 바람이라 たがる. 着たい는 나의 바람, 着てほしい는 남이 해 주길 바라는 말이고, 着たいがる는 없는 꼴이에요."]},{"id":"b230","g":"sup","lv":4,"p":"～予定だ","m":"~할 예정이다","c":"동사 사전형 + 予定だ / 명사 + の + 予定だ","d":"이미 정해진 일정을 말해요. 마음속 생각(의지)을 말하는 ～つもりだ와 달리, 달력에 적힌 계획 같은 느낌이에요.","ex":[["来週の月曜日に大阪へ行く予定です。","らいしゅうの げつようびに おおさかへ いく よていです。","다음 주 월요일에 오사카에 갈 예정입니다."],["明日は午後から会議の予定です。","あしたは ごごから かいぎの よていです。","내일은 오후부터 회의가 있을 예정입니다."]],"tag":"sup","cmp":[["～つもりだ","つもり는 마음속 생각(의지), 予定는 정해진 일정"]],"qz":["新しい駅は、来年の春にできる（　　）です。","予定",["つもり","ところ","ほう"],"あたらしい えきは、らいねんの はるに できる よていです。","새 역은 내년 봄에 생길 예정입니다.","정해진 일정이라 予定. つもり는 사람의 마음속 생각이라 駅에 못 쓰고, ところ는 '막 ~하려는 참', ほう는 비교예요."]},{"id":"b231","g":"sup","lv":4,"p":"～場合は","m":"~할 경우에는 · ~일 때는","c":"동사 보통형 / い형용사 ～い / な형용사 ～な / 명사 + の + 場合(は)","d":"'만약 그런 일이 생기면 어떻게 하는지'를 말할 때 써요. 안내문·규칙·설명서에 자주 나와요. ～とき와 비슷하지만 '그런 경우가 생기면'이라는 가정의 느낌이 강해요.","ex":[["雨の場合は、試合は来週になります。","あめの ばあいは、しあいは らいしゅうに なります。","비가 올 경우에는 시합은 다음 주가 됩니다."],["道が分からない場合は、電話してください。","みちが わからない ばあいは、でんわして ください。","길을 모를 경우에는 전화해 주세요."]],"tag":"sup","qz":["火事の（　　）は、エレベーターを使わないでください。","場合",["ため","まま","まで"],"かじの ばあいは、エレベーターを つかわないで ください。","불이 났을 경우에는 엘리베이터를 쓰지 마세요.","'그런 일이 생기면'을 나타내니 명사 + の + 場合は. ため(위해·때문)·まま(~한 채)·まで(까지)는 は와 이어져 규칙을 말하는 뜻이 안 돼요."]},{"id":"b232","g":"sup","lv":4,"p":"～な（금지）","m":"~하지 마 (강한 금지)","c":"동사 사전형 + な (する → するな, 来る → 来るな)","d":"아주 강한 명령이라 표지판·운동 경기·급한 때에나 써요. 보통 말할 때는 ～ないで·～ないでください를 써요.","ex":[["危ないから、ここで走るな。","あぶないから、ここで はしるな。","위험하니까 여기서 뛰지 마."],["「さわるな」と書いてあります。","「さわるな」と かいて あります。","'만지지 마'라고 쓰여 있습니다."]],"tag":"sup","cmp":[["～なさい","な는 금지(行くな 가지 마), なさい는 명령(行きなさい 가거라)"]],"qz":["あぶない！かむかもしれないから、その犬に（　　）！","さわるな",["さわりなさい","さわらな","さわるなさい"],"あぶない！かむかも しれないから、その いぬに さわるな！","위험해! 물지도 모르니까 그 개를 만지지 마!","강한 금지는 사전형 + な(さわるな). さわりなさい는 '만져라'라는 명령이라 반대 뜻이고, さわらな·さわるなさい는 없는 꼴이에요."]},{"id":"b233","g":"sup","lv":4,"p":"～ことがある（가끔）","m":"~할 때가 있다 (가끔)","c":"동사 사전형·ない형 + ことがある","d":"늘 그런 것은 아니지만 가끔 그런 일이 있다는 뜻이에요. た형 + ことがある(~한 적이 있다, 경험)와 모양이 비슷해서 시험에 잘 나와요. 時々·たまに와 함께 자주 써요.","ex":[["時々、電車で寝てしまうことがあります。","ときどき、でんしゃで ねて しまう ことが あります。","가끔 전철에서 잠들어 버릴 때가 있습니다."],["忙しい日は昼ごはんを食べないことがあります。","いそがしい ひは ひるごはんを たべない ことが あります。","바쁜 날은 점심을 먹지 않을 때가 있습니다."]],"tag":"sup","cmp":[["～たことがある","た형이면 경험(行ったことがある 간 적이 있다), 사전형이면 가끔(行くことがある 갈 때가 있다)"]],"qz":["今でも時々、小学校の友だちと公園で（　　）ことがあります。","遊ぶ",["遊んだ","遊んで","遊ぼう"],"いまでも ときどき、しょうがっこうの ともだちと こうえんで あそぶ ことが あります。","지금도 가끔 초등학교 친구와 공원에서 놀 때가 있습니다.","'今でも時々(지금도 가끔)' 있는 일이라 사전형 + ことがある. た형이면 '~한 적이 있다(경험)'가 되어 今でも와 안 맞아요."]},{"id":"b234","g":"sup","lv":4,"p":"～が見える／～が聞こえる","m":"~이 보이다 · ~이 들리다 (저절로)","c":"명사 + が + 見える·聞こえる","d":"보려고(들으려고) 하지 않아도 저절로 눈에 들어오고 귀에 들리는 거예요. 대상에는 を가 아니라 が를 써요. 가능형 見られる·聞ける는 '(기회·조건이 되어) 볼 수 있다·들을 수 있다'라서 뜻이 달라요.","ex":[["晴れた日は、ここから富士山が見えます。","はれた ひは、ここから ふじさんが みえます。","맑은 날에는 여기서 후지산이 보입니다."],["どこからかピアノの音が聞こえます。","どこからか ピアノの おとが きこえます。","어디선가 피아노 소리가 들립니다."]],"tag":"sup","cmp":[["見られる／聞ける","山が見える는 저절로 보임, この映画はネットで見られる는 볼 기회·방법이 있음"]],"qz":["あれ？となりの部屋から、ねこの鳴き声が（　　）。","聞こえます",["聞けます","聞きます","聞かせます"],"あれ？となりの へやから、ねこの なきごえが きこえます。","어? 옆방에서 고양이 울음소리가 들립니다.","들으려 하지 않았는데 저절로 들리니 聞こえる. 聞ける는 '들을 기회가 있다'는 가능형이고, 聞く·聞かせる는 が와 함께 못 써요."]},{"id":"b235","g":"sup","lv":4,"p":"～ように言う","m":"~하라고 말하다 (지시·부탁을 전함)","c":"동사 사전형·ない형 + ように + 言う·頼む·注意する","d":"누가 시킨 말이나 부탁을 전할 때 써요. 「早く来てください」라고 들은 것을 전하면 早く来るように言われました가 돼요. 직접 인용(「～てください」と言われた)과 달리 내용만 간추려 전하는 말이에요.","ex":[["先生に宿題を忘れないように言われました。","せんせいに しゅくだいを わすれないように いわれました。","선생님께서 숙제를 잊지 말라고 하셨습니다."],["田中さんに、あとで電話するように言ってください。","たなかさんに、あとで でんわするように いって ください。","다나카 씨에게 나중에 전화하라고 전해 주세요."]],"tag":"sup","qz":["友だちに、ノートを貸してくれる（　　）頼みました。","ように",["ために","ことに","そうに"],"ともだちに、ノートを かして くれるように たのみました。","친구에게 노트를 빌려 달라고 부탁했습니다.","부탁한 내용을 전하니 ように + 頼む. ために는 목적, ことに·そうに는 頼む 앞에 쓰지 않아요."]},{"id":"b236","g":"sup","lv":4,"p":"～ずつ","m":"~씩","c":"수량·정도를 나타내는 말 + ずつ (一つずつ·少しずつ)","d":"똑같은 양으로 나누거나 같은 양을 되풀이할 때 써요. 한국어 '~씩'과 같아요. 少しずつ(조금씩)는 '천천히 조금씩 변한다'는 느낌으로도 자주 써요.","ex":[["お菓子を一人二つずつ取ってください。","おかしを ひとり ふたつずつ とって ください。","과자를 한 사람당 두 개씩 가져가세요."],["日本語が少しずつ分かるようになりました。","にほんごが すこしずつ わかるように なりました。","일본어를 조금씩 알게 되었습니다."]],"tag":"sup","qz":["三人に、りんごを一つ（　　）あげました。全部で三つです。","ずつ",["だけ","しか","ごろ"],"さんにんに、りんごを ひとつずつ あげました。ぜんぶで みっつです。","세 명에게 사과를 하나씩 주었습니다. 모두 세 개입니다.","세 명에게 같은 수만큼 나누었으니 ずつ. だけ면 모두 한 개라 '全部で三つ'와 안 맞고, しか는 뒤에 부정, ごろ는 시간에 써요."]},{"id":"b237","g":"sup","lv":4,"p":"～んですが","m":"~인데요 (부탁·질문 앞에 사정을 말함)","c":"보통형 + んですが (な형용사·명사는 ～なんですが)","d":"부탁이나 질문을 하기 전에 먼저 내 사정을 말하는 표현이에요. 뒤에 ～てくれませんか·～ていただけませんか·どうすればいいですか가 자주 와요. 뒷말을 줄이고 'ちょっと分からないんですが…'로 끝내도 부탁하는 느낌이 전해져요.","ex":[["かぎをなくしたんですが、どうすればいいですか。","かぎを なくしたんですが、どう すれば いいですか。","열쇠를 잃어버렸는데, 어떻게 하면 됩니까?"],["来週休みたいんですが、いいですか。","らいしゅう やすみたいんですが、いいですか。","다음 주에 쉬고 싶은데, 괜찮습니까?"]],"tag":"sup","qz":["この漢字が読めない（　　）、教えていただけませんか。","んですが",["のに","ために","んですか"],"この かんじが よめないんですが、おしえて いただけませんか。","이 한자를 못 읽겠는데, 가르쳐 주실 수 없겠습니까?","부탁하기 전에 내 사정을 말하니 んですが. のに는 불만스러운 '~인데도', ために는 목적, んですか는 질문이라 뒤의 부탁과 안 이어져요."]},{"id":"b238","g":"sup","lv":4,"p":"～と思う／～と言う","m":"~라고 생각하다 · ~라고 말하다","c":"보통형 + と思う·と言う (명사·な형용사는 ～だと思う)","d":"생각이나 들은 말을 전해요. 앞은 보통형이고, 명사·な형용사는 だ를 꼭 넣어요(学生だと思う). 남이 한 말은 ～と言っていました로 전하고, 그대로 옮기면 「　」と言う예요.","ex":[["あの人はキムさんの弟だと思います。","あの ひとは キムさんの おとうとだと おもいます。","저 사람은 김 씨 남동생이라고 생각합니다."],["山田さんは明日来ないと言っていました。","やまださんは あした こないと いって いました。","야마다 씨는 내일 안 온다고 했습니다."]],"tag":"sup","cmp":[["～(よ)うと思う","보통형 + と思う는 의견·추측, 의지형 + と思う는 내 계획(行こうと思う)"]],"qz":["明日の朝は、たぶん雨（　　）思います。","だと",["と","なと","のと"],"あしたの あさは、たぶん あめだと おもいます。","내일 아침은 아마 비가 올 것 같습니다.","명사(雨) 뒤에 と思う를 붙일 때는 だ를 꼭 넣어 だと. 雨と思う는 틀리고, なと·のと는 없는 꼴이에요."]},{"id":"b239","g":"sup","lv":4,"p":"～という","m":"~라는 (이름·내용)","c":"명사·보통형 + という + 명사","d":"상대가 모를 수 있는 이름을 소개하거나(「みどり」という店), 내용을 설명할 때(先生が帰るという話) 써요. 회화에서는 ～っていう로 줄이기도 해요.","ex":[["駅の前に「みどり」というパン屋があります。","えきの まえに「みどり」という パンやが あります。","역 앞에 '미도리'라는 빵집이 있습니다."],["先生が国へ帰るという話を聞きました。","せんせいが くにへ かえるという はなしを ききました。","선생님이 고국으로 돌아가신다는 이야기를 들었습니다."]],"tag":"sup","qz":["「ハチ」（　　）犬の話を知っていますか。","という",["と言った","と思う","といって"],"「ハチ」という いぬの はなしを しって いますか。","'하치'라는 개 이야기를 알고 있습니까?","이름을 소개하며 명사(犬)를 꾸미니 という. と言った는 '~라고 말한', と思う는 '~라고 생각하는'이라 뜻이 안 맞고, といって는 명사 앞에 못 와요."]},{"id":"b240","g":"sup","lv":4,"p":"～っぽい","m":"~같다 · ~스럽다 · 잘 ~하다","c":"명사 · 동사 ます형 · い형용사(い를 뺀 꼴) + っぽい","d":"회화에서 자주 쓰는 말이에요(JLPT에서는 N3 수준). 명사에 붙으면 '~ 같다'(子どもっぽい 아이 같다·白っぽい 희끄무레하다), 동사에 붙으면 '잘 ~한다'(忘れっぽい 잘 잊어버린다)예요. 좋지 않은 느낌일 때가 많아요.","ex":[["兄は忘れっぽいです。","あには わすれっぽいです。","형은 잘 잊어버립니다."],["この服は少し子どもっぽいですね。","この ふくは すこし こどもっぽいですね。","이 옷은 조금 아이 같네요."]],"tag":"sup","cmp":[["～らしい(~답다)","子どもらしい는 아이다워서 좋음, 子どもっぽい는 (어른인데) 아이 같음"]],"qz":["兄は高校生なのに、すぐ泣いて、ちょっと（　　）です。","子どもっぽい",["子どもらしい","子どもっぽく","子どもぽい"],"あには こうこうせいなのに、すぐ ないて、ちょっと こどもっぽいです。","형은 고등학생인데 금방 울어서 좀 아이 같습니다.","아이가 아닌데 아이 같다는 좋지 않은 느낌이라 っぽい. らしい는 진짜 아이가 아이다울 때 써요. っぽく는 です 앞에 못 오고, ぽい는 っ가 빠졌어요."]}]};
